const CBQ_DATA={C:[{id:"C1",num:1,title:"Variance Analysis \u2014 NovaTech Manufacturing",topics:"DM Variance \xB7 DL Variance \xB7 Responsibility",case:`NovaTech Manufacturing produces industrial control panels using a standard costing system. For November, the production department completed 4,000 units.

The purchasing manager bought materials from a new supplier at a lower price. However, the production manager reports that workers used more material and more hours than standard due to machine setup issues.

The CFO needs a complete variance analysis to identify deviations and assign responsibility.`,exhibit:{headers:["Item","Standard","Actual"],rows:[["Units Produced","4,000","4,000"],["DM per unit","2.5 kg @ $8.00/kg","2.8 kg @ $7.50/kg"],["DL per unit","1.5 hrs @ $20.00/hr","1.7 hrs @ $20.50/hr"],["Fixed OH","$48,000","$51,200"]]},questions:[{type:"calc",id:"C1Q1",text:"Calculate the DM Price Variance for November.",hint:"(AP \u2212 SP) \xD7 AQ purchased. AQ = 4,000 \xD7 2.8",exact:5600,tol:10,pre:"$",suf:"",fb:"DM Price Variance = (AP \u2212 SP) \xD7 AQ = ($7.50 \u2212 $8.00) \xD7 11,200 kg = \u2212$0.50 \xD7 11,200 = $5,600 Favorable. Cheaper purchase price = favorable."},{type:"calc",id:"C1Q2",text:"Calculate the DM Quantity Variance.",hint:"(AQ used \u2212 SQ allowed) \xD7 SP",exact:9600,tol:10,pre:"$",suf:"",fb:"DM Qty Variance = (AQ \u2212 SQ) \xD7 SP = (11,200 \u2212 10,000) \xD7 $8.00 = $9,600 Unfavorable. More material used than standard."},{type:"calc",id:"C1Q3",text:"Calculate the DL Rate Variance.",hint:"(AR \u2212 SR) \xD7 AH. AH = 4,000 \xD7 1.7",exact:3400,tol:10,pre:"$",suf:"",fb:"DL Rate Variance = (AR \u2212 SR) \xD7 AH = ($20.50 \u2212 $20.00) \xD7 6,800 hrs = $3,400 Unfavorable. Paid more per hour than standard."},{type:"select",id:"C1Q4",text:"The DM Price Variance responsibility belongs to:",opts:["Production Manager","Purchasing Manager","Plant Superintendent","CFO"],ans:1,fb:"The Purchasing Manager negotiates and controls the price paid for materials, making them responsible for the Price Variance."},{type:"drag",id:"C1Q5",text:"Classify each variance as Favorable (F) or Unfavorable (U):",items:["DM Price Variance","DM Qty Variance","DL Rate Variance","DL Efficiency Variance"],zones:["Favorable","Unfavorable"],correct:{"DM Price Variance":"Favorable","DM Qty Variance":"Unfavorable","DL Rate Variance":"Unfavorable","DL Efficiency Variance":"Unfavorable"},fb:"DM Price: Favorable (cheaper). DM Qty: Unfavorable (more used). DL Rate: Unfavorable (higher hourly pay). DL Efficiency: Unfavorable (more hours used)."},{type:"blank",id:"C1Q6",text:"The DM Quantity Variance is the responsibility of the [B1], because it reflects the efficiency of [B2] usage in production.",blanks:[{id:"B1",opts:["Purchasing Manager","Production Manager","CFO"],ans:"Production Manager"},{id:"B2",opts:["labor","material","overhead"],ans:"material"}],fb:"The Production Manager controls shop floor operations, including how efficiently materials are consumed."}]},{id:"C2",num:2,title:"ROI vs. Residual Income \u2014 Apex Group",topics:"ROI \xB7 Residual Income \xB7 Goal Congruence",case:`Apex Group operates two independent divisions evaluated on ROI. The CFO suspects that the ROI system is causing goal incongruence \u2014 managers are rejecting investments that would benefit the overall company.

A new project requires $500,000 investment and generates $70,000 in annual operating income. The required rate of return for both divisions is 12%.`,exhibit:{headers:["","Division Alpha","Division Beta"],rows:[["Assets Employed","$5,000,000","$2,000,000"],["Operating Income","$700,000","$260,000"],["New Project \u2014 Investment","$500,000","$500,000"],["New Project \u2014 Income","$70,000","$70,000"]]},questions:[{type:"calc",id:"C2Q1",text:"What is Division Alpha's current ROI?",hint:"Operating Income \xF7 Assets Employed",exact:14,tol:.1,pre:"",suf:"%",fb:"ROI = $700,000 \xF7 $5,000,000 = 14%"},{type:"calc",id:"C2Q2",text:"What is Division Alpha's current Residual Income (RI)?",hint:"Operating Income \u2212 (Assets \xD7 Required Rate)",exact:1e5,tol:10,pre:"$",suf:"",fb:"RI = $700,000 \u2212 ($5,000,000 \xD7 12%) = $700,000 \u2212 $600,000 = $100,000"},{type:"calc",id:"C2Q3",text:"What is the RI of the new project alone?",hint:"Project Income \u2212 (Investment \xD7 Required Rate)",exact:1e4,tol:10,pre:"$",suf:"",fb:"Project RI = $70,000 \u2212 ($500,000 \xD7 12%) = $70,000 \u2212 $60,000 = $10,000 Positive \u2192 adds value."},{type:"select",id:"C2Q4",text:"If Alpha is measured by ROI, will the manager accept the new project? (Project ROI = 14%)",opts:["Yes \u2014 14% ROI is high enough to accept","No \u2014 it will dilute the division ROI if combined average falls","Yes \u2014 positive ROI always accepted","No \u2014 ROI is below the hurdle rate"],ans:1,fb:"New combined ROI = ($700K+$70K) \xF7 ($5M+$500K) = $770K \xF7 $5.5M = 14.0%. Barely changes, but the fear of dilution causes managers to reject. At higher current ROI, managers reject anything that pulls their metric down."},{type:"select",id:"C2Q5",text:"Which metric better aligns divisional managers with company goals?",opts:["ROI \u2014 easy percentage comparison","Residual Income \u2014 accepts any project earning above the hurdle rate","ROI \u2014 penalizes large assets","Both are equally effective"],ans:1,fb:"RI promotes goal congruence: accept any project with positive RI (earns above required rate) = good for the company. ROI creates dysfunctional behavior when current ROI exceeds the hurdle rate."},{type:"blank",id:"C2Q6",text:"When a division's ROI already [B1] the required rate, managers tend to [B2] projects that earn above the hurdle rate, harming the company.",blanks:[{id:"B1",opts:["is below","exceeds","equals"],ans:"exceeds"},{id:"B2",opts:["accept","reject","delay"],ans:"reject"}],fb:"This is the classic goal incongruence problem: high-performing divisions (ROI > hurdle) reject value-creating projects that would dilute their metric. RI solves this."}]},{id:"C3",num:3,title:"EVA & DuPont Analysis \u2014 Meridian Corp",topics:"EVA \xB7 WACC \xB7 DuPont ROI",case:`Meridian Corp is a listed manufacturer. The board wants to know if the company is creating shareholder value.

Capital structure: 60% equity (cost 14%) and 40% debt (after-tax cost 6%). Net Sales = $8,000,000. NOPAT = $520,000. Net Income = $480,000. Total Assets (= Invested Capital) = $4,000,000.`,exhibit:{headers:["Item","Amount"],rows:[["Net Sales","$8,000,000"],["NOPAT","$520,000"],["Net Income","$480,000"],["Invested Capital","$4,000,000"],["Equity (60%)","@ 14%"],["Debt (40%)","@ 6% after-tax"]]},questions:[{type:"calc",id:"C3Q1",text:"Calculate WACC.",hint:"(Wd \xD7 Kd) + (We \xD7 Ke)",exact:10.8,tol:.1,pre:"",suf:"%",fb:"WACC = (40% \xD7 6%) + (60% \xD7 14%) = 2.4% + 8.4% = 10.8%"},{type:"calc",id:"C3Q2",text:"Calculate EVA.",hint:"NOPAT \u2212 (WACC \xD7 Invested Capital)",exact:88e3,tol:10,pre:"$",suf:"",fb:"EVA = $520,000 \u2212 (10.8% \xD7 $4,000,000) = $520,000 \u2212 $432,000 = $88,000"},{type:"select",id:"C3Q3",text:"The EVA of $88,000 means:",opts:["Meridian is destroying value (WACC > NOPAT)","Meridian is creating value \u2014 it earns more than its cost of capital","Meridian is breaking even","EVA needs market price to interpret"],ans:1,fb:"Positive EVA = value created. Meridian earns $88,000 more than what investors require. EVA > 0 \u2192 good for shareholders."},{type:"calc",id:"C3Q4",text:"Calculate Asset Turnover (DuPont component).",hint:"Net Sales \xF7 Total Assets",exact:2,tol:.05,pre:"",suf:"x",fb:"Asset Turnover = $8,000,000 \xF7 $4,000,000 = 2.0x"},{type:"drag",id:"C3Q5",text:"Match each formula to its DuPont component:",items:["Net Income \xF7 Sales","Sales \xF7 Total Assets","Profit Margin \xD7 Asset Turnover"],zones:["Profit Margin","Asset Turnover","DuPont ROI"],correct:{"Net Income \xF7 Sales":"Profit Margin","Sales \xF7 Total Assets":"Asset Turnover","Profit Margin \xD7 Asset Turnover":"DuPont ROI"},fb:"Profit Margin = Net Income \xF7 Sales. Asset Turnover = Sales \xF7 Assets. DuPont ROI = Profit Margin \xD7 Asset Turnover."},{type:"blank",id:"C3Q6",text:"EVA uses [B1] (not Net Income) and [B2] as the cost of capital, making it more comprehensive than simple RI.",blanks:[{id:"B1",opts:["NOPAT","EBIT","Gross Profit"],ans:"NOPAT"},{id:"B2",opts:["WACC","Required Rate of Return","Cost of Equity"],ans:"WACC"}],fb:"EVA = NOPAT \u2212 (WACC \xD7 Invested Capital). NOPAT removes tax distortions. WACC reflects both debt and equity costs."}]},{id:"C4",num:4,title:"Balanced Scorecard \u2014 Sunrise Hospital Group",topics:"BSC \xB7 KPIs \xB7 Strategy Alignment",case:`Sunrise Hospital Group is implementing the Balanced Scorecard (BSC) framework to link strategy to performance measurement.

The CEO states: "Financial success comes from satisfying patients. Patient satisfaction requires excellent internal processes. Excellent processes require investing in our people and systems."

Management must classify KPIs into the four BSC perspectives.`,exhibit:{headers:["KPI","BSC Perspective (?)"],rows:[["Return on Equity","?"],["Patient Satisfaction Score","?"],["Average Treatment Time","?"],["Staff Training Hours","?"],["Cost per Patient","?"],["Employee Turnover Rate","?"]]},questions:[{type:"drag",id:"C4Q1",text:"Drag each KPI to the correct BSC perspective:",items:["Return on Equity","Patient Satisfaction Score","Average Treatment Time","Staff Training Hours"],zones:["Financial","Customer","Internal Process","Learning & Growth"],correct:{"Return on Equity":"Financial","Patient Satisfaction Score":"Customer","Average Treatment Time":"Internal Process","Staff Training Hours":"Learning & Growth"},fb:"Financial \u2192 ROE. Customer \u2192 Patient Satisfaction. Internal Process \u2192 Treatment Time. Learning & Growth \u2192 Training Hours."},{type:"select",id:"C4Q2",text:"In the BSC cause-and-effect chain, which perspective is the FOUNDATION driving all others?",opts:["Financial","Customer","Internal Process","Learning & Growth"],ans:3,fb:"Learning & Growth is the root: invest in people \u2192 improve processes \u2192 satisfy customers \u2192 achieve financial results. It all starts from the bottom."},{type:"select",id:"C4Q3",text:'"Patient Satisfaction Score" is a:',opts:["Purely lagging indicator \u2014 measures past results","Lagging indicator for operations AND leading indicator for financial results","Purely leading indicator \u2014 predicts future only","Neither \u2014 not a valid performance metric"],ans:1,fb:"BSC metrics are often both: Patient Satisfaction lags operational performance (past service quality) but leads future revenue and loyalty (leading financial indicator). This dual nature is a BSC strength."},{type:"select",id:"C4Q4",text:"The main advantage of BSC over traditional financial reporting is:",opts:["It eliminates financial statements","It links non-financial drivers to long-term financial outcomes","It focuses only on customer satisfaction","It replaces budgeting"],ans:1,fb:"BSC provides a balanced, multi-perspective view connecting non-financial drivers (processes, people, customers) to long-term financial success \u2014 something pure financial statements cannot show."},{type:"blank",id:"C4Q5",text:"The [B1] perspective covers operational efficiency (e.g., treatment time), while the [B2] perspective covers skills and systems needed to sustain those operations.",blanks:[{id:"B1",opts:["Financial","Customer","Internal Process","Learning & Growth"],ans:"Internal Process"},{id:"B2",opts:["Financial","Customer","Internal Process","Learning & Growth"],ans:"Learning & Growth"}],fb:"Internal Process = HOW we operate. Learning & Growth = WHAT enables us to operate well (people, technology, culture)."}]},{id:"C5",num:5,title:"Transfer Pricing \u2014 Vertex Industries",topics:"Transfer Price \xB7 Capacity \xB7 Goal Congruence",case:`Vertex Industries has two divisions. The Components Division makes a part (variable cost $45/unit, external price $80). Capacity: 20,000 units/year.

Scenario A: Division is at FULL capacity (20,000 units sold externally).
Scenario B: Division has 5,000 units of spare capacity.

The Assembly Division requests 5,000 units internally. It can source externally at $80.`,exhibit:{headers:["Item","Value"],rows:[["Variable Cost per unit","$45"],["External Market Price","$80"],["Annual Capacity","20,000 units"],["Scenario A \u2014 Current Output","20,000 (full capacity)"],["Scenario B \u2014 Current Output","15,000 (spare = 5,000)"],["Requested Transfer","5,000 units"]]},questions:[{type:"calc",id:"C5Q1",text:"Minimum transfer price at FULL capacity (Scenario A)?",hint:"Min TP = Variable Cost + Opportunity Cost per unit",exact:80,tol:.5,pre:"$",suf:"",fb:"At full capacity, to give 5,000 units to Assembly, Components gives up 5,000 external sales. Min TP = $45 + ($80\u2212$45) = $45 + $35 = $80. Opportunity cost = lost CM = $35/unit."},{type:"calc",id:"C5Q2",text:"Minimum transfer price with SPARE capacity (Scenario B)?",hint:"No opportunity cost when spare capacity available",exact:45,tol:.5,pre:"$",suf:"",fb:"With spare capacity, no external sales are foregone. Opportunity cost = $0. Min TP = Variable Cost = $45 only."},{type:"select",id:"C5Q3",text:"At full capacity with TP = $80, which statement is TRUE for the overall company?",opts:["Company gains \u2014 internal transfer saves costs","Company is indifferent \u2014 no overall benefit or cost from the internal transfer","Company loses \u2014 Components foregoes premium sales","Company gains \u2014 Assembly pays less than market"],ans:1,fb:"At TP = $80 (= external price), Components is indifferent between internal and external. Assembly pays same as market. Overall company: no gain or loss (unless selling/shipping costs are saved on internal transfers)."},{type:"select",id:"C5Q4",text:"The PRIMARY purpose of a transfer pricing system is to:",opts:["Minimize total tax liability","Measure divisional performance fairly and encourage decisions that benefit the whole company","Maximize the supplying division's profit","Match external market prices exactly"],ans:1,fb:"Transfer pricing serves two goals: (1) fair performance measurement of each division, and (2) goal congruence \u2014 decisions that benefit each division should also benefit the overall company."},{type:"blank",id:"C5Q5",text:"Min TP formula = Variable Cost + [B1]. With spare capacity, the [B1] equals zero, so Min TP = [B2] cost only.",blanks:[{id:"B1",opts:["Fixed Cost","Opportunity Cost","Selling Price"],ans:"Opportunity Cost"},{id:"B2",opts:["total","variable","fixed"],ans:"variable"}],fb:"Min TP = Variable Cost + Opportunity Cost. Opportunity cost = CM foregone per unit when capacity is given up. With spare capacity: opportunity cost = $0, so Min TP = variable cost."}]},{id:"C6",num:6,title:"Sales Mix & Volume Variance \u2014 Coastal Beverages Inc.",topics:"Sales Mix Variance \xB7 Sales Quantity Variance \xB7 Sales Volume Variance",case:"Coastal Beverages Inc. sells two products: X and Y. Management budgeted a specific sales mix for the quarter but actual results shifted toward the higher-margin product.",exhibit:{headers:["Product","Budgeted Units","Budgeted CM/Unit","Actual Units"],rows:[["X","6,000","$10.00","5,500"],["Y","4,000","$15.00","5,500"],["Total","10,000","","11,000"]]},questions:[{type:"calc",id:"C6Q1",text:"Calculate the budgeted weighted-average contribution margin per unit.",hint:"(60% \xD7 $10) + (40% \xD7 $15)",exact:12,tol:.1,pre:"$",suf:"",fb:"Budgeted weighted-average CM = (60% \xD7 $10) + (40% \xD7 $15) = $6 + $6 = $12 per unit."},{type:"calc",id:"C6Q2",text:"Calculate the total Sales Quantity Variance (both products combined).",hint:"For each product: (Actual total units \xD7 budgeted mix% \u2212 budgeted units) \xD7 budgeted CM",exact:12e3,tol:50,pre:"$",suf:"",fb:"X: (11,000\xD760% \u2212 6,000)\xD7$10 = $6,000 F. Y: (11,000\xD740% \u2212 4,000)\xD7$15 = $6,000 F. Total Sales Quantity Variance = $12,000 Favorable \u2014 driven purely by higher total volume at the budgeted mix."},{type:"calc",id:"C6Q3",text:"Calculate the total Sales Mix Variance (both products combined).",hint:"For each product: (Actual units \u2212 Actual total \xD7 budgeted mix%) \xD7 budgeted CM",exact:5500,tol:50,pre:"$",suf:"",fb:"X: (5,500 \u2212 6,600)\xD7$10 = -$11,000 U. Y: (5,500 \u2212 4,400)\xD7$15 = $16,500 F. Total Sales Mix Variance = $5,500 Favorable \u2014 the shift toward higher-margin Product Y helped overall profit."},{type:"calc",id:"C6Q4",text:"Calculate the total Sales Volume Variance.",hint:"Sales Quantity Variance + Sales Mix Variance",exact:17500,tol:50,pre:"$",suf:"",fb:"Sales Volume Variance = Quantity Variance ($12,000 F) + Mix Variance ($5,500 F) = $17,500 Favorable."},{type:"select",id:"C6Q5",text:"Which variance specifically isolates the profit effect of selling a different PROPORTION of high- vs low-margin products (holding total volume constant)?",opts:["Sales Volume Variance","Sales Quantity Variance","Sales Mix Variance","Sales Price Variance"],ans:2,fb:"The Sales Mix Variance holds total unit volume constant and isolates the effect of shifting the mix toward higher- or lower-margin products."},{type:"blank",id:"C6Q6",text:"Sales Volume Variance = Sales [B1] Variance + Sales [B2] Variance.",blanks:[{id:"B1",opts:["Quantity","Price","Efficiency"],ans:"Quantity"},{id:"B2",opts:["Mix","Rate","Spending"],ans:"Mix"}],fb:"The total Sales Volume Variance decomposes into the Sales Quantity Variance (effect of total volume) and the Sales Mix Variance (effect of product mix shift)."}]},{id:"C7",num:7,title:"Overhead Variance Analysis \u2014 Anchor Industrial",topics:"VOH Spending & Efficiency \xB7 FOH Budget & Volume Variance",case:"Anchor Industrial budgets fixed overhead of $100,000 at a normal capacity of 20,000 machine hours (standard fixed rate = $5.00/hr) and a standard variable overhead rate of $3.00/hr. For the period, 18,500 standard hours were allowed for the actual output achieved.",exhibit:{headers:["Item","Amount"],rows:[["Budgeted Fixed OH","$100,000"],["Normal capacity (std fixed rate basis)","20,000 hrs ($5.00/hr)"],["Standard Variable OH rate","$3.00/hr"],["Standard hours allowed for actual output","18,500 hrs"],["Actual machine hours worked","19,000 hrs"],["Actual Variable OH incurred","$60,000"],["Actual Fixed OH incurred","$102,000"]]},questions:[{type:"calc",id:"C7Q1",text:"Calculate the Variable OH Spending Variance.",hint:"Actual VOH \u2212 (Actual hours \xD7 standard VOH rate)",exact:3e3,tol:50,pre:"$",suf:"",fb:"VOH Spending Variance = $60,000 \u2212 (19,000 \xD7 $3.00) = $60,000 \u2212 $57,000 = $3,000 Unfavorable."},{type:"calc",id:"C7Q2",text:"Calculate the Variable OH Efficiency Variance.",hint:"(Actual hours \u2212 standard hours allowed) \xD7 standard VOH rate",exact:1500,tol:50,pre:"$",suf:"",fb:"VOH Efficiency Variance = (19,000 \u2212 18,500) \xD7 $3.00 = $1,500 Unfavorable."},{type:"calc",id:"C7Q3",text:"Calculate the Fixed OH Budget (Spending) Variance.",hint:"Actual Fixed OH \u2212 Budgeted Fixed OH",exact:2e3,tol:50,pre:"$",suf:"",fb:"FOH Budget Variance = $102,000 \u2212 $100,000 = $2,000 Unfavorable."},{type:"calc",id:"C7Q4",text:"Calculate the Fixed OH Volume Variance.",hint:"Budgeted Fixed OH \u2212 (standard hours allowed \xD7 standard fixed rate)",exact:7500,tol:50,pre:"$",suf:"",fb:"FOH Volume Variance = $100,000 \u2212 (18,500 \xD7 $5.00) = $100,000 \u2212 $92,500 = $7,500 Unfavorable."},{type:"select",id:"C7Q5",text:"The Fixed OH Volume Variance primarily signals:",opts:["Whether spending was controlled during the period","Whether actual output differed from the normal capacity used to set the fixed rate","A pricing error in materials purchasing","A labor efficiency problem"],ans:1,fb:"The Volume Variance arises purely because actual output (measured in standard hours allowed) differed from the normal capacity denominator used to compute the standard fixed rate \u2014 it is not a spending or efficiency measure."},{type:"blank",id:"C7Q6",text:"The Fixed OH Volume Variance arises because actual output differed from [B1] capacity, and unlike the spending and efficiency variances, it is generally considered [B2] by operating managers in the short run.",blanks:[{id:"B1",opts:["normal","actual","theoretical"],ans:"normal"},{id:"B2",opts:["uncontrollable","fully controllable","irrelevant"],ans:"uncontrollable"}],fb:"Because fixed costs do not change with volume, the Volume Variance mainly reflects a capacity-utilization outcome rather than a controllable spending decision."}]},{id:"C8",num:8,title:"Segment Reporting \u2014 Sunrise Apparel Group",topics:"Contribution Income Statement \xB7 Segment Margin \xB7 Traceable vs Common Fixed Costs",case:"Sunrise Apparel Group reports results for its two divisions using a segmented contribution income statement. Corporate overhead of $50,000 is a common fixed cost that cannot be traced to either division.",exhibit:{headers:["Item","Retail Division","Wholesale Division"],rows:[["Sales","$500,000","$350,000"],["Variable costs","$300,000","$200,000"],["Traceable fixed costs","$120,000","$90,000"]]},questions:[{type:"calc",id:"C8Q1",text:"Calculate the Retail Divisions contribution margin.",hint:"Sales \u2212 variable costs",exact:2e5,tol:500,pre:"$",suf:"",fb:"Retail CM = $500,000 \u2212 $300,000 = $200,000."},{type:"calc",id:"C8Q2",text:"Calculate the Retail Divisions segment margin.",hint:"Contribution margin \u2212 traceable fixed costs",exact:8e4,tol:500,pre:"$",suf:"",fb:"Retail segment margin = $200,000 \u2212 $120,000 = $80,000."},{type:"calc",id:"C8Q3",text:"Calculate the Wholesale Divisions segment margin.",hint:"($350,000\u2212$200,000) \u2212 $90,000",exact:6e4,tol:500,pre:"$",suf:"",fb:"Wholesale CM = $350,000 \u2212 $200,000 = $150,000. Segment margin = $150,000 \u2212 $90,000 = $60,000."},{type:"calc",id:"C8Q4",text:"Calculate total company net income after covering common fixed costs.",hint:"Sum of both segment margins \u2212 common fixed costs",exact:9e4,tol:500,pre:"$",suf:"",fb:"Total net income = $80,000 + $60,000 \u2212 $50,000 common fixed costs = $90,000."},{type:"select",id:"C8Q5",text:"Common (corporate) fixed costs should NOT be allocated down to the divisions because:",opts:["They are always immaterial in amount","They would disappear if a division were eliminated, so allocating them distorts segment profitability","GAAP prohibits any allocation of fixed costs","They are always variable, not fixed"],ans:1,fb:"Common fixed costs (like corporate overhead) persist regardless of any single divisions existence, so allocating them to segments can make an otherwise profitable segment look unprofitable and mislead a keep-or-drop decision."},{type:"blank",id:"C8Q6",text:"Segment margin = Contribution Margin \u2212 [B1] Fixed Costs, and represents the profit a division would lose if it were [B2].",blanks:[{id:"B1",opts:["Traceable","Common","Total"],ans:"Traceable"},{id:"B2",opts:["discontinued","expanded","audited"],ans:"discontinued"}],fb:"Segment margin subtracts only the fixed costs directly traceable to that segment, making it the best measure of a segments contribution to covering common costs and profit."}]},{id:"C9",num:9,title:"Labor Mix & Yield Variance \u2014 BlendCraft Beverages",topics:"Labor Mix Variance \xB7 Labor Yield Variance \xB7 Total Labor Efficiency Variance",case:"BlendCraft Beverages uses two labor grades to staff a bottling batch: Skilled and Unskilled workers. The standard mix calls for 60% skilled and 40% unskilled hours. For the batch actually produced, the standard hours allowed (at standard mix) totaled 950 hours, but the crew actually worked 1,000 hours using a different mix than standard.",exhibit:{headers:["Labor Grade","Standard","Actual"],rows:[["Skilled (60% std mix)","6 hrs @ $20.00/hr","550 hrs @ $20.00/hr"],["Unskilled (40% std mix)","4 hrs @ $10.00/hr","450 hrs @ $10.00/hr"],["Standard hours allowed for actual output","950 hrs","\u2014"],["Total actual hours worked","\u2014","1,000 hrs"]]},questions:[{type:"calc",id:"C9Q1",text:"Calculate the standard weighted-average labor rate per hour (based on the 60/40 standard mix).",hint:"(60% \xD7 $20) + (40% \xD7 $10)",exact:16,tol:.2,pre:"$",suf:"",fb:"Standard weighted-average rate = (60% \xD7 $20) + (40% \xD7 $10) = $12 + $4 = $16.00 per hour."},{type:"calc",id:"C9Q2",text:"Calculate the total Labor Mix Variance.",hint:"Compare actual hours by grade to actual total hours split at the STANDARD mix, \xD7 standard rate for each grade",exact:500,tol:20,pre:"$",suf:"",fb:"At standard mix, 1,000 actual hours would split 600 Skilled / 400 Unskilled. Skilled: (550\u2212600)\xD7$20 = -$1,000 F. Unskilled: (450\u2212400)\xD7$10 = $500 U. Total Labor Mix Variance = $500 Favorable (used relatively fewer of the costlier skilled hours than the standard mix called for)."},{type:"calc",id:"C9Q3",text:"Calculate the Labor Yield Variance.",hint:"(Actual total hours \u2212 standard hours allowed) \xD7 standard weighted-average rate",exact:800,tol:20,pre:"$",suf:"",fb:"Labor Yield Variance = (1,000 \u2212 950) \xD7 $16.00 = $800 Unfavorable \u2014 more total hours were used than the output should have required."},{type:"calc",id:"C9Q4",text:"Calculate the Total Labor Efficiency Variance.",hint:"Labor Mix Variance + Labor Yield Variance",exact:300,tol:20,pre:"$",suf:"",fb:"Total Labor Efficiency Variance = $500 F (mix) + $800 U (yield) = $300 Unfavorable net."},{type:"select",id:"C9Q5",text:"The Labor Mix Variance specifically measures the cost effect of:",opts:["Using more or fewer total hours than standard allows","Substituting one labor grade for another within the same total hours","Paying a different wage rate than standard","A change in the selling price of the finished product"],ans:1,fb:"The Mix Variance isolates the cost impact of shifting the proportion of skilled vs. unskilled hours, holding total actual hours constant."},{type:"blank",id:"C9Q6",text:"Total Labor Efficiency Variance = Labor [B1] Variance + Labor [B2] Variance.",blanks:[{id:"B1",opts:["Mix","Rate","Spending"],ans:"Mix"},{id:"B2",opts:["Yield","Price","Volume"],ans:"Yield"}],fb:"Just as with sales variances, the total efficiency variance splits into a Mix component (grade substitution) and a Yield component (total input vs. standard allowed)."}]},{id:"C10",num:10,title:"Non-Financial Performance Measures \u2014 TechNova Manufacturing",topics:"Quality Metrics \xB7 Customer Metrics \xB7 Leading vs Lagging Indicators",case:"TechNova Manufacturing tracks several non-financial metrics alongside its financial statements. Last quarter, out of 1,000 customer orders, 940 were delivered on time and 25 generated a formal complaint. Separately, 18 of the companys 150 employees left during the year.",exhibit:{headers:["Metric","Data"],rows:[["On-time deliveries","940 of 1,000 orders"],["Customer complaints","25 of 1,000 orders"],["Employees who left","18 of 150 employees"]]},questions:[{type:"calc",id:"C10Q1",text:"Calculate the on-time delivery rate.",hint:"940 \xF7 1,000",exact:94,tol:.5,pre:"",suf:"%",fb:"On-time delivery rate = 940 \xF7 1,000 = 94%."},{type:"calc",id:"C10Q2",text:"Calculate the customer complaint rate.",hint:"25 \xF7 1,000",exact:2.5,tol:.2,pre:"",suf:"%",fb:"Customer complaint rate = 25 \xF7 1,000 = 2.5%."},{type:"calc",id:"C10Q3",text:"Calculate the employee turnover rate.",hint:"18 \xF7 150",exact:12,tol:.5,pre:"",suf:"%",fb:"Employee turnover rate = 18 \xF7 150 = 12%."},{type:"select",id:"C10Q4",text:"On-time delivery rate is generally considered a LEADING indicator because it:",opts:["Can only be measured after annual financial statements are released","Signals future customer satisfaction and retention before it shows up in financial results","Has no relationship to future financial performance","Is only useful for external auditors"],ans:1,fb:"Leading indicators (like delivery performance and quality) tend to predict future financial outcomes, whereas measures like net income are lagging \u2014 they report what already happened."},{type:"drag",id:"C10Q5",text:"Classify each measure into its primary performance category:",items:["On-time delivery rate","Customer complaint rate","Employee turnover rate"],zones:["Quality/Process","Customer","Employee/Learning & Growth"],correct:{"On-time delivery rate":"Quality/Process","Customer complaint rate":"Customer","Employee turnover rate":"Employee/Learning & Growth"},fb:"Non-financial measures are typically grouped by the operational area they reflect \u2014 process/quality, customer experience, or employee/learning & growth."},{type:"blank",id:"C10Q6",text:"Non-financial measures are valuable because they often provide [B1] warning of problems that will eventually affect [B2] results, giving management time to react.",blanks:[{id:"B1",opts:["early","delayed","no"],ans:"early"},{id:"B2",opts:["financial","unrelated","historical"],ans:"financial"}],fb:"Because non-financial measures like quality and customer satisfaction typically move before revenue and profit do, they give management an early signal to act."}]}],D:[{id:"D2",num:1,title:"Job Order Costing \u2014 PrecisionCraft Workshop",topics:"POHR \xB7 Job Cost Sheet \xB7 Under/Over-Applied Overhead",case:`PrecisionCraft Workshop uses a job order costing system with a predetermined overhead rate (POHR) based on direct labor hours.

At the start of the year, management estimated total overhead of $480,000 and total direct labor hours of 60,000. Job #201 was completed during the year for a key customer.`,exhibit:{headers:["Item","Data"],rows:[["Estimated Annual Overhead","$480,000"],["Estimated DL Hours","60,000"],["Job #201 \u2014 Direct Materials","$12,000"],["Job #201 \u2014 DL Hours","500 hours"],["DL Wage Rate","$18 per hour"],["Actual OH Incurred (year)","$492,000"],["Actual DL Hours (year)","60,000"]]},questions:[{type:"calc",id:"D2Q1",text:"Calculate the Predetermined Overhead Rate (POHR).",hint:"POHR = Estimated Overhead \xF7 Estimated Cost Driver (DL Hours)",exact:8,tol:0,pre:"$",suf:" per DLH",fb:"POHR = $480,000 \xF7 60,000 DLH = $8 per DLH. Set at the start of the year and used to apply overhead to all jobs throughout the year."},{type:"calc",id:"D2Q2",text:"Calculate the total cost of Job #201.",hint:"Job Cost = DM + DL + Applied OH. DL = 500 hrs \xD7 $18. Applied OH = 500 hrs \xD7 POHR",exact:25e3,tol:0,pre:"$",suf:"",fb:"DL = 500 \xD7 $18 = $9,000. Applied OH = 500 \xD7 $8 = $4,000. Total = $12,000 + $9,000 + $4,000 = $25,000."},{type:"calc",id:"D2Q3",text:"Calculate total Overhead Applied for the entire year.",hint:"OH Applied = Actual DL Hours worked \xD7 POHR",exact:48e4,tol:0,pre:"$",suf:"",fb:"OH Applied = 60,000 actual DLH \xD7 $8 = $480,000. Applied OH uses the ACTUAL activity level \xD7 predetermined rate \u2014 not actual overhead costs incurred."},{type:"calc",id:"D2Q4",text:"Calculate the Under- or Over-Applied Overhead for the year.",hint:"Under/Over = Actual OH \u2212 Applied OH. Positive = Under-applied.",exact:12e3,tol:0,pre:"$",suf:" under-applied",fb:"$492,000 \u2212 $480,000 = $12,000 Under-applied. Jobs were not charged enough overhead during the year."},{type:"select",id:"D2Q5",text:"Under-applied overhead of $12,000 means:",opts:["More overhead was applied to jobs than actually incurred \u2014 COGS overstated","Less overhead was applied to jobs than actually incurred \u2014 COGS understated","Overhead was perfectly applied \u2014 no adjustment needed","Fixed costs were lower than expected"],ans:1,fb:"Under-applied = Actual > Applied. Jobs absorbed only $480,000 of $492,000 actual overhead. COGS and inventory are UNDERSTATED. At year-end, close $12,000 to COGS (debit COGS, increasing it)."},{type:"blank",id:"D2Q6",text:"Under-applied overhead is closed at year-end by [B1] Cost of Goods Sold. Over-applied overhead is closed by [B2] Cost of Goods Sold.",blanks:[{id:"B1",opts:["debiting (increasing)","crediting (decreasing)"],ans:"debiting (increasing)"},{id:"B2",opts:["debiting (increasing)","crediting (decreasing)"],ans:"crediting (decreasing)"}],fb:"Under-applied: actual > applied \u2192 COGS understated \u2192 DEBIT COGS. Over-applied: actual < applied \u2192 COGS overstated \u2192 CREDIT COGS. This closes the Manufacturing Overhead account to zero at year-end."}]},{id:"D3",num:2,title:"Process Costing \u2014 PureFlow Chemicals",topics:"Equivalent Units \xB7 Weighted Average \xB7 Cost per EU",case:`PureFlow Chemicals processes raw chemicals through a single department. Direct materials are added at the START of the process. Conversion costs are incurred evenly throughout.

The weighted average method is used. The cost accountant must calculate equivalent units, cost per EU, and the cost of units completed and transferred out.`,exhibit:{headers:["Item","Units / Amount"],rows:[["Beginning WIP (50% conversion complete)","2,000 units"],["Units Started in Period","18,000 units"],["Units Completed & Transferred Out","17,000 units"],["Ending WIP (50% conversion complete)","3,000 units"],["DM Cost \u2014 Beginning WIP","$40,000"],["DM Cost \u2014 Added in Period","$320,000"],["Conversion Cost \u2014 Beginning WIP","$15,000"],["Conversion Cost \u2014 Added in Period","$170,000"]]},questions:[{type:"calc",id:"D3Q1",text:"Calculate Equivalent Units for Direct Materials (Weighted Average).",hint:"DM is added at START \u2014 all units (transferred + EWIP) are 100% complete for DM.",exact:2e4,tol:0,pre:"",suf:" EU",fb:"EU(DM) = 17,000 + 3,000 \xD7 100% = 20,000. All units \u2014 transferred out AND in EWIP \u2014 are fully complete for DM since it was added at the start."},{type:"calc",id:"D3Q2",text:"Calculate Equivalent Units for Conversion Costs (Weighted Average).",hint:"EU(Conv) = Units Transferred + Ending WIP \xD7 % complete for conversion",exact:18500,tol:0,pre:"",suf:" EU",fb:"EU(Conv) = 17,000 + 3,000 \xD7 50% = 17,000 + 1,500 = 18,500. The 3,000 EWIP units are 50% converted = 1,500 equivalent fully-converted units."},{type:"calc",id:"D3Q3",text:"Calculate the Cost per Equivalent Unit for Direct Materials.",hint:"WA: Total DM Cost = BWIP DM + Current DM. Divide by EU(DM).",exact:18,tol:0,pre:"$",suf:" per EU",fb:"Total DM = $40,000 + $320,000 = $360,000. CPU(DM) = $360,000 \xF7 20,000 = $18.00. Weighted average blends BWIP and current costs together."},{type:"calc",id:"D3Q4",text:"Calculate total cost transferred to the next department (17,000 units).",hint:"CPU(Conv) = ($15,000 + $170,000) \xF7 18,500. Total CPU = CPU(DM) + CPU(Conv). Cost Transferred = 17,000 \xD7 Total CPU.",exact:476e3,tol:50,pre:"$",suf:"",fb:"CPU(Conv) = $185,000 \xF7 18,500 = $10.00. Total CPU = $18 + $10 = $28. Cost transferred = 17,000 \xD7 $28 = $476,000."},{type:"select",id:"D3Q5",text:"Why is the concept of Equivalent Units necessary in process costing?",opts:["To track individual job costs like in job order costing","To convert partially complete units into a full-unit equivalent for fair cost allocation","To eliminate the need for a predetermined overhead rate","To calculate the contribution margin per unit"],ans:1,fb:"In process costing, all units are indistinguishable \u2014 we cannot assign costs to individual units. EU converts partially complete units into their full-unit equivalent so we can calculate a meaningful cost per unit and fairly allocate costs between completed and in-process units."},{type:"blank",id:"D3Q6",text:"Under Weighted Average, BWIP costs are [B1] with current period costs. Under FIFO, BWIP costs are [B2] from current period costs.",blanks:[{id:"B1",opts:["combined (blended)","separated","ignored"],ans:"combined (blended)"},{id:"B2",opts:["kept separate","combined","ignored"],ans:"kept separate"}],fb:"WA blends all costs \u2192 simpler but hides period-to-period changes. FIFO keeps BWIP separate \u2192 more accurate performance measurement. On the CMA exam, know both EU formulas: WA includes BWIP completion % in EU; FIFO adds work needed to complete BWIP separately."}]},{id:"D4",num:3,title:"Activity-Based Costing \u2014 TechParts Inc.",topics:"ABC vs Traditional Costing \xB7 Cost Drivers \xB7 Product Cost Distortion",case:`TechParts Inc. makes two products: Alpha (high-volume, simple) and Beta (low-volume, complex). The company uses a plant-wide overhead rate based on Direct Labor Hours.

The controller suspects cost distortion and wants to implement ABC with two overhead pools: Machine Setups and General Machining.`,exhibit:{headers:["Item","Alpha","Beta","Total"],rows:[["Units Produced","10,000","1,000","11,000"],["Direct Labor Hours","20,000 DLH","5,000 DLH","25,000 DLH"],["Number of Machine Setups","10","40","50"],["Overhead \u2014 Machine Setups","\u2014","\u2014","$200,000"],["Overhead \u2014 General Machining","\u2014","\u2014","$300,000"],["Total Overhead","\u2014","\u2014","$500,000"]]},questions:[{type:"calc",id:"D4Q1",text:"Calculate the traditional plant-wide overhead rate (based on DLH).",hint:"Traditional Rate = Total Overhead \xF7 Total DL Hours",exact:20,tol:0,pre:"$",suf:" per DLH",fb:"Traditional Rate = $500,000 \xF7 25,000 DLH = $20/DLH. This single rate applies the same cost per DLH to both products \u2014 ignoring how differently they actually consume overhead resources."},{type:"calc",id:"D4Q2",text:"Under traditional costing, calculate overhead cost per unit for Alpha.",hint:"Alpha overhead = 20,000 DLH \xD7 $20. Divide by 10,000 units.",exact:40,tol:0,pre:"$",suf:" per unit",fb:"Alpha OH = 20,000 \xD7 $20 = $400,000 \xF7 10,000 = $40/unit. Alpha uses 80% of total DLH so it absorbs $400,000 of the $500,000 total."},{type:"calc",id:"D4Q3",text:"Using ABC, calculate overhead cost per unit for Beta.",hint:"Setup rate = $200,000 \xF7 50. Machine rate = $300,000 \xF7 25,000 DLH. Beta ABC OH = (40 setups \xD7 rate) + (5,000 DLH \xD7 rate). Divide by 1,000 units.",exact:220,tol:0,pre:"$",suf:" per unit",fb:"Setup rate = $4,000/setup. Machine rate = $12/DLH. Beta OH = (40 \xD7 $4,000) + (5,000 \xD7 $12) = $160,000 + $60,000 = $220,000 \xF7 1,000 = $220/unit. Traditional only charged $100 \u2014 a $120 understatement!"},{type:"select",id:"D4Q4",text:"Under ABC, Alpha costs $28/unit vs $40 traditional. Beta costs $220/unit vs $100 traditional. Which statement is correct?",opts:["Traditional accurately priced both products","Alpha is UNDERCOSTED and Beta is OVERCOSTED under traditional","Alpha is OVERCOSTED and Beta is UNDERCOSTED under traditional \u2014 traditional hides Beta's true complexity cost","Both methods are equally valid for pricing"],ans:2,fb:"ABC Alpha = (10 \xD7 $4,000 + 20,000 \xD7 $12) \xF7 10,000 = $28. Traditional overcosts Alpha ($40 vs $28) and massively undercosts Beta ($100 vs $220). Beta consumes 80% of setups but only 20% of DLH \u2014 traditional misses this entirely."},{type:"drag",id:"D4Q5",text:"Match each cost driver to its most appropriate overhead activity:",items:["Number of Machine Setups","Direct Labor Hours","Number of Purchase Orders","Square Footage Occupied"],zones:["Batch Setup Activity","Machining Activity","Procurement Activity","Facility Activity"],correct:{"Number of Machine Setups":"Batch Setup Activity","Direct Labor Hours":"Machining Activity","Number of Purchase Orders":"Procurement Activity","Square Footage Occupied":"Facility Activity"},fb:"ABC matches each cost pool to the activity that DRIVES the cost: Setups \u2192 setup count. Machine time \u2192 DLH. Purchasing \u2192 PO count. Facility \u2192 space. Choosing the correct driver is the most critical step in ABC design."},{type:"blank",id:"D4Q6",text:"Under traditional costing, high-volume simple products tend to be [B1] because they absorb too much overhead via DLH. Low-volume complex products tend to be [B2] because they consume disproportionate batch-level resources.",blanks:[{id:"B1",opts:["overcosted","undercosted","correctly costed"],ans:"overcosted"},{id:"B2",opts:["overcosted","undercosted","correctly costed"],ans:"undercosted"}],fb:"This is the classic ABC finding: traditional DLH-based costing cross-subsidizes complex products. High-volume products end up overpriced and low-volume complex products underpriced \u2014 leading to bad pricing and product mix decisions. ABC corrects this."}]},{id:"D5",num:4,title:"Joint Products \u2014 PetroRefine Corp.",topics:"Joint Cost Allocation \xB7 Further Processing Decision \xB7 Split-Off Point",case:`PetroRefine Corp. processes crude oil through a joint refining process costing $180,000. At the split-off point, three joint products emerge.

Management must (1) allocate joint costs for financial reporting using the physical units method, and (2) decide product by product whether to sell at split-off or process further.`,exhibit:{headers:["Product","Output","Split-off Price","Further Process Cost","Price After Processing"],rows:[["Gasoline","5,000 gal","$25/gal","Not applicable","\u2014"],["Diesel","3,000 gal","$20/gal","$30,000","$35/gal"],["Kerosene","2,000 gal","$15/gal","$40,000","$24/gal"]]},questions:[{type:"calc",id:"D5Q1",text:"Using the physical units method, calculate the joint cost allocated to Gasoline.",hint:"Physical units: each product's share = its units \xF7 total units. Total gallons = 10,000.",exact:9e4,tol:0,pre:"$",suf:"",fb:"Gasoline = 5,000 \xF7 10,000 = 50%. Allocated = 50% \xD7 $180,000 = $90,000. Physical units allocates purely on quantity \u2014 simple but ignores relative sales values."},{type:"calc",id:"D5Q2",text:"Calculate the incremental profit from further processing Diesel. Should it be processed further?",hint:"Incremental Revenue = (New price \u2212 Split-off price) \xD7 units. Net = Incremental Revenue \u2212 Further Processing Cost.",exact:15e3,tol:0,pre:"$",suf:" net benefit",fb:"Incr. Revenue = ($35 \u2212 $20) \xD7 3,000 = $45,000. Incr. Cost = $30,000. Net benefit = $15,000. YES \u2014 process Diesel further. It adds $15,000 of incremental value."},{type:"calc",id:"D5Q3",text:"Calculate the incremental profit (loss) from further processing Kerosene. Should it be processed further?",hint:"Incremental Revenue = (New price \u2212 Split-off price) \xD7 units. Compare to Further Processing Cost.",exact:22e3,tol:0,pre:"$",suf:" net LOSS \u2014 sell at split-off",fb:"Incr. Revenue = ($24 \u2212 $15) \xD7 2,000 = $18,000. Incr. Cost = $40,000. Net loss = $22,000. NO \u2014 sell Kerosene at split-off. Further processing destroys $22,000 of value."},{type:"select",id:"D5Q4",text:"The $180,000 joint processing cost is IRRELEVANT to the further processing decision. Why?",opts:["Joint costs are always immaterial","Joint costs are sunk costs \u2014 already incurred regardless of what happens after the split-off point","Joint costs are not allocated to individual products","Joint costs only matter for tax purposes"],ans:1,fb:"Joint costs are SUNK at the split-off point \u2014 incurred before the decision and unchangeable regardless of the choice made. Only INCREMENTAL revenues and costs beyond split-off are relevant. This is a core managerial accounting principle: sunk costs are always irrelevant."},{type:"drag",id:"D5Q5",text:"Classify each product's optimal decision:",items:["Gasoline (no further processing option)","Diesel (net benefit $15,000)","Kerosene (net loss $22,000)"],zones:["Sell at Split-Off","Process Further"],correct:{"Gasoline (no further processing option)":"Sell at Split-Off","Diesel (net benefit $15,000)":"Process Further","Kerosene (net loss $22,000)":"Sell at Split-Off"},fb:"Rule: Process further ONLY when incremental revenue > incremental cost. Gasoline: sell at split-off (no option). Diesel: process further ($45K rev > $30K cost). Kerosene: sell at split-off ($18K rev < $40K cost)."},{type:"blank",id:"D5Q6",text:"In a further processing decision, joint costs are [B1] because they are [B2] costs already incurred before the split-off point.",blanks:[{id:"B1",opts:["relevant","irrelevant","sometimes relevant"],ans:"irrelevant"},{id:"B2",opts:["sunk","variable","avoidable"],ans:"sunk"}],fb:"Sunk costs = past costs, cannot be changed \u2192 ALWAYS irrelevant to decisions. The further processing decision only considers what changes AFTER split-off. Note: joint cost allocation method matters only for FINANCIAL REPORTING (inventory valuation) \u2014 never for operational decisions."}]},{id:"D6",num:5,title:"Variable vs. Absorption Costing \u2014 Summit Sporting Goods",topics:"Absorption Costing \xB7 Variable Costing \xB7 Income Reconciliation",case:"Summit Sporting Goods produced 10,000 units and sold 8,000 units this year, starting with zero beginning inventory. The controller wants to compare operating income under both costing methods.",exhibit:{headers:["Item","Amount"],rows:[["Direct materials","$8.00/unit"],["Direct labor","$5.00/unit"],["Variable manufacturing OH","$2.00/unit"],["Fixed manufacturing OH (total)","$60,000"],["Selling price","$40.00/unit"],["Variable selling & admin","$3.00/unit"],["Fixed selling & admin (total)","$80,000"]]},questions:[{type:"calc",id:"D6Q1",text:"Calculate the absorption costing product cost per unit.",hint:"DM + DL + Variable OH + (Fixed OH \xF7 units produced)",exact:21,tol:.5,pre:"$",suf:"",fb:"Absorption unit cost = $8 + $5 + $2 + ($60,000 \xF7 10,000 units = $6) = $21 per unit."},{type:"calc",id:"D6Q2",text:"Calculate the variable costing product cost per unit.",hint:"DM + DL + Variable OH only \u2014 fixed OH is a period cost",exact:15,tol:.5,pre:"$",suf:"",fb:"Variable costing unit cost = $8 + $5 + $2 = $15 per unit (fixed OH is expensed in full as a period cost, not included in unit product cost)."},{type:"calc",id:"D6Q3",text:"Calculate operating income under ABSORPTION costing.",hint:"(8,000 \xD7 $40) \u2212 (8,000 \xD7 $21) \u2212 (8,000 \xD7 $3) \u2212 $80,000",exact:48e3,tol:500,pre:"$",suf:"",fb:"Sales $320,000 \u2212 COGS $168,000 (8,000\xD7$21) = Gross margin $152,000. Less variable S&A $24,000 and fixed S&A $80,000 = Operating income $48,000."},{type:"calc",id:"D6Q4",text:"Calculate operating income under VARIABLE costing.",hint:"Contribution margin \u2212 total fixed costs (Fixed OH + Fixed S&A)",exact:36e3,tol:500,pre:"$",suf:"",fb:"Contribution margin = $320,000 \u2212 $120,000 (var COGS) \u2212 $24,000 (var S&A) = $176,000. Less Fixed OH $60,000 and Fixed S&A $80,000 = Operating income $36,000."},{type:"calc",id:"D6Q5",text:"Calculate the difference between absorption and variable costing operating income.",hint:"Fixed OH per unit \xD7 change in inventory units",exact:12e3,tol:500,pre:"$",suf:"",fb:"Difference = $6 Fixed OH/unit \xD7 (10,000 produced \u2212 8,000 sold = 2,000 unit increase in inventory) = $12,000, matching $48,000 \u2212 $36,000."},{type:"select",id:"D6Q6",text:"Absorption costing income is HIGHER than variable costing income here because:",opts:["Absorption costing ignores fixed costs entirely","Production exceeded sales, so some fixed OH is deferred in ending inventory under absorption costing","The selling price was misstated","Variable costing always overstates income when inventory grows"],ans:1,fb:"When production > sales, absorption costing defers a portion of fixed overhead into ending inventory (as an asset) rather than expensing it all in the current period, which inflates reported income relative to variable costing."}]},{id:"D7",num:6,title:"Service Department Allocation \u2014 Continental Manufacturing",topics:"Direct Method \xB7 Service Department Costs \xB7 Production Department Allocation",case:"Continental Manufacturing has two service departments (Maintenance and IT) that support two production departments (Assembly and Finishing). Using the direct method, service department costs are allocated only to production departments, ignoring any services provided between service departments.",exhibit:{headers:["Service Dept","Cost","Assembly Usage","Finishing Usage"],rows:[["Maintenance","$80,000","3,000 hrs","2,000 hrs"],["IT","$40,000","400 hrs","600 hrs"]]},questions:[{type:"calc",id:"D7Q1",text:"Calculate the Maintenance cost allocated to Assembly.",hint:"$80,000 \xD7 (3,000 \xF7 5,000)",exact:48e3,tol:500,pre:"$",suf:"",fb:"Maintenance to Assembly = $80,000 \xD7 (3,000 \xF7 5,000 total production-dept hours) = $48,000."},{type:"calc",id:"D7Q2",text:"Calculate the Maintenance cost allocated to Finishing.",hint:"$80,000 \xD7 (2,000 \xF7 5,000)",exact:32e3,tol:500,pre:"$",suf:"",fb:"Maintenance to Finishing = $80,000 \xD7 (2,000 \xF7 5,000) = $32,000."},{type:"calc",id:"D7Q3",text:"Calculate the IT cost allocated to Assembly.",hint:"$40,000 \xD7 (400 \xF7 1,000)",exact:16e3,tol:200,pre:"$",suf:"",fb:"IT to Assembly = $40,000 \xD7 (400 \xF7 1,000 total production-dept hours) = $16,000."},{type:"calc",id:"D7Q4",text:"Calculate the IT cost allocated to Finishing.",hint:"$40,000 \xD7 (600 \xF7 1,000)",exact:24e3,tol:200,pre:"$",suf:"",fb:"IT to Finishing = $40,000 \xD7 (600 \xF7 1,000) = $24,000."},{type:"calc",id:"D7Q5",text:"Calculate the TOTAL service department cost allocated to Assembly (Maintenance + IT).",hint:"$48,000 + $16,000",exact:64e3,tol:500,pre:"$",suf:"",fb:"Total to Assembly = $48,000 (Maintenance) + $16,000 (IT) = $64,000."},{type:"select",id:"D7Q6",text:"The main limitation of the direct method of service department allocation is that it:",opts:["Is more complex to calculate than the reciprocal method","Ignores services that service departments provide to EACH OTHER","Cannot be used with more than two production departments","Always overstates total costs allocated"],ans:1,fb:"The direct method allocates service costs straight to production departments only, ignoring any Maintenance-to-IT or IT-to-Maintenance service usage \u2014 which the step-down and reciprocal methods attempt to capture."}]},{id:"D8",num:7,title:"Cost Estimation \u2014 High-Low Method \u2014 Vantage Logistics",topics:"High-Low Method \xB7 Mixed Cost Formula \xB7 Cost Prediction",case:"Vantage Logistics wants to estimate its monthly delivery truck operating costs as a function of miles driven, using the high and low activity months from the past year.",exhibit:{headers:["Month","Miles Driven","Total Cost"],rows:[["Highest activity","8,000 miles","$42,000"],["Lowest activity","3,000 miles","$27,000"]]},questions:[{type:"calc",id:"D8Q1",text:"Calculate the variable cost per mile.",hint:"(High cost \u2212 low cost) \xF7 (high miles \u2212 low miles)",exact:3,tol:.1,pre:"$",suf:"",fb:"Variable rate = ($42,000 \u2212 $27,000) \xF7 (8,000 \u2212 3,000) = $15,000 \xF7 5,000 = $3.00 per mile."},{type:"calc",id:"D8Q2",text:"Calculate the fixed cost per month.",hint:"Total cost at high activity \u2212 (variable rate \xD7 high miles)",exact:18e3,tol:200,pre:"$",suf:"",fb:"Fixed cost = $42,000 \u2212 ($3.00 \xD7 8,000) = $42,000 \u2212 $24,000 = $18,000 per month."},{type:"calc",id:"D8Q3",text:"Using the cost formula, estimate total cost for a month with 6,000 miles driven.",hint:"Fixed cost + (variable rate \xD7 miles)",exact:36e3,tol:500,pre:"$",suf:"",fb:"Estimated cost = $18,000 + ($3.00 \xD7 6,000) = $18,000 + $18,000 = $36,000."},{type:"select",id:"D8Q4",text:"The main weakness of the high-low method is that it:",opts:["Requires statistical software to compute","Uses only two data points and can be distorted by an outlier month","Cannot separate fixed and variable costs at all","Only works for manufacturing companies"],ans:1,fb:"Because high-low relies on only the highest and lowest activity points, an unusual (outlier) month at either extreme can distort the entire cost formula."},{type:"select",id:"D8Q5",text:"Compared to the high-low method, regression analysis is generally considered more reliable because it:",opts:["Is easier to calculate by hand","Uses all available data points, not just two extremes","Never requires any judgment from the analyst","Eliminates the need for a cost driver"],ans:1,fb:"Regression analysis uses every observation in the dataset (and provides statistics like R\xB2 to gauge fit), making it generally more reliable than a two-point high-low estimate."},{type:"blank",id:"D8Q6",text:'The formula Y = a + bX is called the [B1], where "a" represents the [B2] cost component and "b" represents the [B3] cost per unit of activity.',blanks:[{id:"B1",opts:["cost equation","break-even formula","variance formula"],ans:"cost equation"},{id:"B2",opts:["fixed","variable","total"],ans:"fixed"},{id:"B3",opts:["fixed","variable","sunk"],ans:"variable"}],fb:'The mixed-cost (cost) equation Y = a + bX separates a fixed component "a" from a variable rate "b" applied to the activity level X.'}]},{id:"D9",num:8,title:"Life-Cycle & Target Costing \u2014 NextGen Electronics",topics:"Target Costing \xB7 Value Engineering \xB7 Life-Cycle Costing",case:"NextGen Electronics is designing a new wearable device. Market research sets the target selling price at $250 with a required 20% target profit margin on price. Engineering currently estimates the product will cost $230 to make. Management also wants to see the products full life-cycle cost.",exhibit:{headers:["Item","Amount"],rows:[["Target selling price","$250 per unit"],["Target profit margin","20% of price"],["Current estimated unit cost","$230"],["R&D and design costs (life-of-product)","$500,000"],["Manufacturing costs (life-of-product)","$3,000,000"],["Marketing costs (life-of-product)","$400,000"],["Post-sale support/warranty costs (life-of-product)","$300,000"],["Expected units sold over product life","20,000"]]},questions:[{type:"calc",id:"D9Q1",text:"Calculate the target profit per unit.",hint:"20% \xD7 $250",exact:50,tol:1,pre:"$",suf:"",fb:"Target profit = 20% \xD7 $250 = $50 per unit."},{type:"calc",id:"D9Q2",text:"Calculate the target cost per unit.",hint:"Target price \u2212 target profit",exact:200,tol:1,pre:"$",suf:"",fb:"Target cost = $250 \u2212 $50 = $200 per unit."},{type:"calc",id:"D9Q3",text:"Calculate the cost reduction needed through value engineering.",hint:"Current estimated cost \u2212 target cost",exact:30,tol:1,pre:"$",suf:"",fb:"Cost reduction needed = $230 \u2212 $200 = $30 per unit \u2014 the value-engineering gap the team must close before launch."},{type:"calc",id:"D9Q4",text:"Calculate the total life-cycle cost of the product.",hint:"Sum of R&D, manufacturing, marketing, and post-sale support costs",exact:42e5,tol:5e3,pre:"$",suf:"",fb:"Total life-cycle cost = $500,000 + $3,000,000 + $400,000 + $300,000 = $4,200,000."},{type:"calc",id:"D9Q5",text:"Calculate the life-cycle cost per unit.",hint:"Total life-cycle cost \xF7 expected units sold",exact:210,tol:2,pre:"$",suf:"",fb:"Life-cycle cost per unit = $4,200,000 \xF7 20,000 units = $210."},{type:"select",id:"D9Q6",text:'The majority of a products life-cycle cost is typically "locked in" at which stage, even though little of it has actually been SPENT yet?',opts:["The manufacturing stage","The design/planning stage","The post-sale support stage","The disposal stage"],ans:1,fb:"Design decisions determine materials, components, and processes that drive most downstream manufacturing and support costs \u2014 so cost is effectively locked in during design, long before it is incurred."}]},{id:"D10",num:9,title:"Theory of Constraints & Throughput \u2014 Falcon Assembly Line",topics:"Theory of Constraints \xB7 Bottleneck Identification \xB7 Throughput Contribution",case:"Falcon Assembly Line has three sequential processes. Management wants to know the maximum daily output and profit given the process with the least capacity.",exhibit:{headers:["Process","Daily Capacity"],rows:[["Cutting","1,000 units"],["Welding","700 units"],["Painting","900 units"]]},questions:[{type:"select",id:"D10Q1",text:"Which process is the bottleneck (constraint) on the line?",opts:["Cutting","Welding","Painting","There is no bottleneck"],ans:1,fb:"Welding has the lowest capacity (700 units/day), so it constrains total daily output regardless of the other processes capacity."},{type:"calc",id:"D10Q2",text:"Selling price is $80/unit and direct material is $30/unit. Calculate the throughput contribution per unit (Theory of Constraints definition: Sales \u2212 totally variable/material cost only).",hint:"$80 \u2212 $30",exact:50,tol:1,pre:"$",suf:"",fb:"Throughput contribution = $80 \u2212 $30 = $50 per unit. Under TOC, only truly variable costs like direct material reduce throughput; labor and overhead are treated as fixed operating expense in the short run."},{type:"calc",id:"D10Q3",text:"Calculate the maximum daily output given the constraint.",hint:"The bottlenecks daily capacity limits total output",exact:700,tol:0,pre:"",suf:" units",fb:"The line can never produce more than the bottleneck (Welding) allows: 700 units per day, no matter how much capacity Cutting or Painting have."},{type:"calc",id:"D10Q4",text:"Calculate total daily throughput contribution at maximum output.",hint:"Max units \xD7 throughput contribution per unit",exact:35e3,tol:200,pre:"$",suf:"",fb:"Total throughput contribution = 700 units \xD7 $50 = $35,000 per day."},{type:"calc",id:"D10Q5",text:"Total daily operating expenses (all other factory costs) are $28,000. Calculate daily operating income.",hint:"Total throughput contribution \u2212 operating expenses",exact:7e3,tol:200,pre:"$",suf:"",fb:"Daily operating income = $35,000 \u2212 $28,000 = $7,000."},{type:"blank",id:"D10Q6",text:"Under the Theory of Constraints, the only cost typically treated as truly variable at the unit level is [B1]; nearly all other factory costs are treated as [B2] in the short run and should not reduce reported throughput.",blanks:[{id:"B1",opts:["direct material","direct labor","all manufacturing overhead"],ans:"direct material"},{id:"B2",opts:["fixed operating expense","fully variable","irrelevant"],ans:"fixed operating expense"}],fb:"TOC deliberately treats labor and overhead as fixed in the short run, keeping management focused on maximizing throughput through the bottleneck rather than on labor efficiency at non-constraint stations."}]},{id:"D11",num:10,title:"Departmental vs. Plant-wide Overhead Rates \u2014 Horizon Metal Works",topics:"Plant-wide Overhead Rate \xB7 Departmental Overhead Rates \xB7 Product Cost Distortion",case:"Horizon Metal Works currently applies overhead using a single plant-wide rate based on direct labor hours (DLH). The controller wants to compare this to using separate departmental rates for Machining and Assembly.",exhibit:{headers:["Item","Machining","Assembly","Total"],rows:[["Budgeted overhead","$300,000","$100,000","$400,000"],["Budgeted DLH","40,000","40,000","80,000"],["Job X actual DLH used","8 hrs","2 hrs","10 hrs"]]},questions:[{type:"calc",id:"D11Q1",text:"Calculate the single plant-wide overhead rate per DLH.",hint:"Total budgeted OH \xF7 total budgeted DLH",exact:5,tol:.1,pre:"$",suf:"",fb:"Plant-wide rate = $400,000 \xF7 80,000 DLH = $5.00 per DLH."},{type:"calc",id:"D11Q2",text:"Calculate the Machining department overhead rate per DLH.",hint:"$300,000 \xF7 40,000",exact:7.5,tol:.1,pre:"$",suf:"",fb:"Machining rate = $300,000 \xF7 40,000 DLH = $7.50 per DLH."},{type:"calc",id:"D11Q3",text:"Calculate the Assembly department overhead rate per DLH.",hint:"$100,000 \xF7 40,000",exact:2.5,tol:.1,pre:"$",suf:"",fb:"Assembly rate = $100,000 \xF7 40,000 DLH = $2.50 per DLH."},{type:"calc",id:"D11Q4",text:"Calculate overhead applied to Job X using the PLANT-WIDE rate.",hint:"10 total DLH \xD7 $5.00",exact:50,tol:1,pre:"$",suf:"",fb:"OH applied (plant-wide) = 10 DLH \xD7 $5.00 = $50."},{type:"calc",id:"D11Q5",text:"Calculate overhead applied to Job X using DEPARTMENTAL rates.",hint:"(8 hrs \xD7 $7.50) + (2 hrs \xD7 $2.50)",exact:65,tol:1,pre:"$",suf:"",fb:"OH applied (departmental) = (8 \xD7 $7.50) + (2 \xD7 $2.50) = $60 + $5 = $65."},{type:"select",id:"D11Q6",text:"Departmental rates give a more accurate cost for Job X here because:",opts:["Departmental rates are always required by GAAP","Job X is Machining-intensive, and Machining consumes overhead at a much higher rate than the plant average","The plant-wide rate is illegal to use","Departmental rates always produce a lower cost"],ans:1,fb:"Job X uses 8 of its 10 hours in Machining, a department whose OH rate ($7.50) is well above the diluted plant-wide average ($5.00) \u2014 the plant-wide rate understates the true resources this job consumed."}]}],A:[{id:"A1",num:1,title:"Revenue Recognition \u2014 SkyBridge Software",topics:"ASC 606 \xB7 Five-Step Model \xB7 Performance Obligations \xB7 Allocation",case:`SkyBridge Software signs a contract with a client for $90,000. The contract includes three distinct performance obligations: a software license, implementation services, and 12 months of technical support.

The finance team must apply the ASC 606 five-step model to determine how much revenue to allocate to each obligation and when to recognize it.`,exhibit:{headers:["Performance Obligation","Standalone Selling Price (SSP)","Recognition Timing"],rows:[["Software License","$60,000","?"],["Implementation Services","$20,000","?"],["Technical Support (12 months)","$20,000","?"],["Total SSP","$100,000","\u2014"],["Contract Price","$90,000","\u2014"]]},questions:[{type:"calc",id:"A1Q1",text:"Calculate the revenue allocated to the Software License under ASC 606.",hint:"Allocate based on relative SSP. License proportion = $60,000 \xF7 $100,000. Apply to contract price.",exact:54e3,tol:0,pre:"$",suf:"",fb:"License = 60/100 \xD7 $90,000 = $54,000. ASC 606 Step 4 requires allocating the transaction price based on RELATIVE standalone selling prices \u2014 not the SSP directly, because the contract price differs from total SSP."},{type:"calc",id:"A1Q2",text:"Calculate the revenue allocated to Technical Support.",hint:"Support proportion = $20,000 \xF7 $100,000. Apply to $90,000.",exact:18e3,tol:0,pre:"$",suf:"",fb:"Support = 20/100 \xD7 $90,000 = $18,000. Even though the SSP is $20,000, only $18,000 is allocated because the contract was priced at a discount ($90K vs $100K SSP total)."},{type:"calc",id:"A1Q3",text:"How much Technical Support revenue is recognized each month?",hint:"Support is recognized evenly over 12 months.",exact:1500,tol:0,pre:"$",suf:" per month",fb:"Monthly support revenue = $18,000 \xF7 12 = $1,500. Support is a performance obligation satisfied OVER TIME (the customer simultaneously receives and consumes the benefit each month)."},{type:"select",id:"A1Q4",text:"When is the Software License revenue of $54,000 recognized?",opts:["Evenly over 12 months like the support","At the point in time when the license is transferred to the customer","When the full $90,000 cash is collected","Only after implementation services are complete"],ans:1,fb:"A software license is typically recognized at a POINT IN TIME \u2014 when control transfers to the customer (delivery of the license key). It is a separate performance obligation from the support. If the license were a right-to-access (with ongoing updates), it would be over time."},{type:"drag",id:"A1Q5",text:"Match each performance obligation to its revenue recognition pattern:",items:["Software License (control transfers at delivery)","Implementation Services (performed over weeks)","Technical Support (12-month contract)"],zones:["Point in Time","Over Time"],correct:{"Software License (control transfers at delivery)":"Point in Time","Implementation Services (performed over weeks)":"Over Time","Technical Support (12-month contract)":"Over Time"},fb:"ASC 606 Step 5: Recognize revenue when (or as) each PO is satisfied. Point in time = control transfers at a moment. Over time = customer simultaneously receives and consumes, entity creates/enhances asset customer controls, or no alternative use and right to payment."},{type:"blank",id:"A1Q6",text:"ASC 606 Step 3 is to determine the [B1]. Step 4 allocates it based on [B2] selling prices.",blanks:[{id:"B1",opts:["transaction price","performance obligations","contract modification"],ans:"transaction price"},{id:"B2",opts:["standalone","contract","discounted"],ans:"standalone"}],fb:"The 5 steps: (1) Identify the contract. (2) Identify performance obligations. (3) Determine the TRANSACTION PRICE (total consideration). (4) Allocate to POs based on STANDALONE selling prices. (5) Recognize revenue when/as each PO is satisfied."}]},{id:"A2",num:2,title:"Inventory Costing \u2014 BrightGoods Trading",topics:"FIFO \xB7 LIFO \xB7 Weighted Average \xB7 LIFO Reserve",case:`BrightGoods Trading uses a periodic inventory system. Prices have been rising throughout the year. Management wants to compare results under all three cost flow assumptions and understand the LIFO reserve.

The company sold 700 units during the year.`,exhibit:{headers:["Transaction","Units","Unit Cost","Total Cost"],rows:[["Beginning Inventory","200","$10.00","$2,000"],["Purchase 1","300","$12.00","$3,600"],["Purchase 2","500","$15.00","$7,500"],["Total Available","1,000","\u2014","$13,100"],["Units Sold","700","\u2014","?"],["Ending Inventory","300","\u2014","?"]]},questions:[{type:"calc",id:"A2Q1",text:"Calculate Ending Inventory under FIFO.",hint:"FIFO: ending inventory consists of the MOST RECENT purchases. 300 units remain.",exact:4500,tol:0,pre:"$",suf:"",fb:"FIFO EI = 300 units \xD7 $15.00 (most recent purchase) = $4,500. FIFO assumes the first units purchased are the first sold \u2014 so ending inventory holds the newest (highest cost) units."},{type:"calc",id:"A2Q2",text:"Calculate COGS under LIFO (periodic).",hint:"LIFO: ending inventory consists of the OLDEST units. EI = 200 @ $10 + 100 @ $12. COGS = Total \u2212 EI.",exact:9900,tol:0,pre:"$",suf:"",fb:"LIFO EI = 200 \xD7 $10 + 100 \xD7 $12 = $2,000 + $1,200 = $3,200. LIFO COGS = $13,100 \u2212 $3,200 = $9,900. LIFO assumes newest units are sold first \u2014 COGS reflects current (higher) costs."},{type:"calc",id:"A2Q3",text:"Calculate COGS under the Weighted Average method.",hint:"WA unit cost = Total Cost \xF7 Total Units. WA COGS = Units Sold \xD7 WA unit cost.",exact:9170,tol:0,pre:"$",suf:"",fb:"WA unit cost = $13,100 \xF7 1,000 = $13.10. WA COGS = 700 \xD7 $13.10 = $9,170. Weighted average blends all costs equally \u2014 COGS falls between FIFO and LIFO in a rising price environment."},{type:"calc",id:"A2Q4",text:"Calculate the LIFO Reserve at year-end.",hint:"LIFO Reserve = FIFO Ending Inventory \u2212 LIFO Ending Inventory",exact:1300,tol:0,pre:"$",suf:"",fb:"LIFO Reserve = $4,500 (FIFO EI) \u2212 $3,200 (LIFO EI) = $1,300. The LIFO reserve represents how much higher inventory (and net income) would be if the company used FIFO instead of LIFO."},{type:"select",id:"A2Q5",text:"In a period of RISING prices, which statement about FIFO vs LIFO is correct?",opts:["FIFO produces higher COGS and lower net income than LIFO","LIFO produces lower COGS and higher net income than FIFO","FIFO produces lower COGS, higher net income, higher ending inventory, and higher taxes","LIFO and FIFO produce identical net income in rising prices"],ans:2,fb:"Rising prices: FIFO assigns older (cheaper) costs to COGS \u2192 LOWER COGS \u2192 HIGHER gross profit \u2192 HIGHER net income \u2192 HIGHER taxes. LIFO assigns newer (higher) costs to COGS \u2192 HIGHER COGS \u2192 LOWER income \u2192 LOWER taxes (tax advantage). FIFO better reflects current inventory values on the balance sheet."},{type:"blank",id:"A2Q6",text:"LIFO is [B1] under IFRS. Under both GAAP and IFRS, inventory is written down when cost exceeds [B2].",blanks:[{id:"B1",opts:["prohibited","required","allowed"],ans:"prohibited"},{id:"B2",opts:["Net Realizable Value (NRV)","Fair Market Value","Replacement Cost"],ans:"Net Realizable Value (NRV)"}],fb:"IFRS prohibits LIFO \u2014 only FIFO and Weighted Average are allowed. LCNRV (Lower of Cost or Net Realizable Value) applies under both GAAP and IFRS: if NRV < cost, write down inventory. Under GAAP, write-downs cannot be reversed. Under IFRS, reversals ARE allowed if NRV recovers."}]},{id:"A3",num:3,title:"Depreciation & Asset Disposal \u2014 MetalWorks Corp.",topics:"Straight-Line \xB7 DDB \xB7 Book Value \xB7 Gain/Loss on Disposal",case:`MetalWorks Corp. acquired a manufacturing machine. Management is evaluating different depreciation methods and needs to calculate the financial impact of disposing of the machine after three years of straight-line depreciation.

The machine will be sold for $45,000 at the end of Year 3.`,exhibit:{headers:["Item","Amount"],rows:[["Acquisition Cost","$120,000"],["Estimated Salvage Value","$20,000"],["Useful Life","5 years"],["Year 1 Production","30,000 units"],["Total Production Capacity","100,000 units"],["Disposal Price (end of Year 3)","$45,000"]]},questions:[{type:"calc",id:"A3Q1",text:"Calculate the annual Straight-Line depreciation expense.",hint:"SL = (Cost \u2212 Salvage Value) \xF7 Useful Life",exact:2e4,tol:0,pre:"$",suf:" per year",fb:"SL = ($120,000 \u2212 $20,000) \xF7 5 = $100,000 \xF7 5 = $20,000/year. Straight-line is the simplest method \u2014 equal expense each year over the asset's useful life."},{type:"calc",id:"A3Q2",text:"Calculate the Double-Declining Balance (DDB) depreciation for Year 1.",hint:"DDB rate = 2 \xF7 Useful Life. Apply to book value at start of year. Salvage NOT deducted initially.",exact:48e3,tol:0,pre:"$",suf:"",fb:"DDB rate = 2/5 = 40%. Year 1 = 40% \xD7 $120,000 = $48,000. DDB ignores salvage value in the rate calculation \u2014 but must STOP depreciating when book value reaches salvage value."},{type:"calc",id:"A3Q3",text:"Calculate DDB depreciation for Year 2.",hint:"Year 2 BV = Cost \u2212 Year 1 DDB. Apply 40% to Year 2 BV.",exact:28800,tol:0,pre:"$",suf:"",fb:"Year 2 BV = $120,000 \u2212 $48,000 = $72,000. Year 2 DDB = 40% \xD7 $72,000 = $28,800. DDB accelerates depreciation \u2014 highest in early years, declining each year."},{type:"calc",id:"A3Q4",text:"Calculate the book value after 3 years using Straight-Line depreciation.",hint:"Accumulated Depreciation (SL, 3 years) = 3 \xD7 annual SL. BV = Cost \u2212 Accum Dep.",exact:6e4,tol:0,pre:"$",suf:"",fb:"Accum Dep = 3 \xD7 $20,000 = $60,000. BV = $120,000 \u2212 $60,000 = $60,000. This is the net book value \u2014 what remains on the balance sheet before disposal."},{type:"calc",id:"A3Q5",text:"Calculate the Gain or Loss on disposal when the machine is sold for $45,000.",hint:"Gain/Loss = Proceeds \u2212 Book Value at disposal.",exact:15e3,tol:0,pre:"$",suf:" LOSS",fb:"Loss = $45,000 \u2212 $60,000 = \u2212$15,000 (loss). Proceeds < book value \u2192 LOSS on disposal. If proceeds > BV \u2192 GAIN. The gain/loss appears on the income statement under other income/expense."},{type:"select",id:"A3Q6",text:"Which depreciation method produces the HIGHEST depreciation expense in Year 1?",opts:["Straight-Line \u2014 always the highest","Double-Declining Balance \u2014 accelerated method","Units of Production \u2014 depends on actual usage","All methods give the same Year 1 amount"],ans:1,fb:"DDB Year 1 = $48,000 vs SL = $20,000. DDB is an accelerated method \u2014 front-loads depreciation. Units of production Year 1 = ($100,000/100,000) \xD7 30,000 = $30,000. DDB is highest. Accelerated methods are preferred for tax purposes (reduce taxable income faster)."}]},{id:"A4",num:4,title:"Financial Statement Analysis \u2014 ClearPath Retailers",topics:"Liquidity Ratios \xB7 Solvency \xB7 Profitability \xB7 Interest Coverage",case:`ClearPath Retailers is being evaluated by both a bank (for a loan) and potential investors. The analyst must calculate key financial ratios from the statements to assess liquidity, solvency, and profitability.

All data is provided in the exhibit below.`,exhibit:{headers:["Item","Amount"],rows:[["Cash","$50,000"],["Accounts Receivable","$80,000"],["Inventory","$120,000"],["Prepaid Expenses","$10,000"],["Total Assets","$800,000"],["Current Liabilities","$130,000"],["Long-Term Debt","$270,000"],["Total Equity","$400,000"],["Net Sales","$600,000"],["Cost of Goods Sold","$360,000"],["EBIT","$100,000"],["Interest Expense","$20,000"],["Net Income","$60,000"]]},questions:[{type:"calc",id:"A4Q1",text:"Calculate the Current Ratio.",hint:"Current Ratio = Total Current Assets \xF7 Current Liabilities. CA = Cash + AR + Inventory + Prepaid.",exact:2,tol:.01,pre:"",suf:"x",fb:"Total CA = $50K + $80K + $120K + $10K = $260,000. Current Ratio = $260,000 \xF7 $130,000 = 2.0x. A ratio of 2.0 means the company has $2 of current assets for every $1 of current liabilities \u2014 generally considered adequate."},{type:"calc",id:"A4Q2",text:"Calculate the Quick Ratio (Acid-Test Ratio).",hint:"Quick Ratio = (Cash + AR) \xF7 Current Liabilities. Excludes inventory and prepaid.",exact:1,tol:.01,pre:"",suf:"x",fb:"Quick Ratio = ($50,000 + $80,000) \xF7 $130,000 = $130,000 \xF7 $130,000 = 1.0x. The quick ratio excludes inventory (less liquid) and prepaid expenses \u2014 a stricter liquidity test. A ratio of 1.0 means just enough liquid assets to cover current liabilities."},{type:"calc",id:"A4Q3",text:"Calculate the Return on Equity (ROE).",hint:"ROE = Net Income \xF7 Total Equity",exact:15,tol:.1,pre:"",suf:"%",fb:"ROE = $60,000 \xF7 $400,000 = 15%. ROE measures how efficiently the company generates profit from shareholders' equity. Higher ROE = better returns for equity investors."},{type:"calc",id:"A4Q4",text:"Calculate the Interest Coverage Ratio.",hint:"Interest Coverage = EBIT \xF7 Interest Expense",exact:5,tol:.05,pre:"",suf:"x",fb:"Interest Coverage = $100,000 \xF7 $20,000 = 5.0x. The company earns $5 of operating income for every $1 of interest \u2014 strong debt service capacity. A ratio below 1.5x raises serious solvency concerns."},{type:"drag",id:"A4Q5",text:"Classify each ratio into the correct category:",items:["Current Ratio","Debt-to-Equity Ratio","Return on Assets","Interest Coverage Ratio"],zones:["Liquidity Ratio","Solvency Ratio","Profitability Ratio"],correct:{"Current Ratio":"Liquidity Ratio","Debt-to-Equity Ratio":"Solvency Ratio","Return on Assets":"Profitability Ratio","Interest Coverage Ratio":"Solvency Ratio"},fb:"Liquidity: ability to meet short-term obligations (Current, Quick, Cash ratios). Solvency: ability to meet long-term debt obligations (D/E, Debt-to-Assets, Interest Coverage). Profitability: ability to generate profit (ROA, ROE, Gross Margin, Net Profit Margin)."},{type:"blank",id:"A4Q6",text:"The Quick Ratio excludes [B1] from current assets because it is less liquid. A current ratio ABOVE [B2] is generally considered a sign of adequate short-term liquidity.",blanks:[{id:"B1",opts:["inventory and prepaid expenses","accounts receivable","cash"],ans:"inventory and prepaid expenses"},{id:"B2",opts:["1.0","2.0","0.5"],ans:"1.0"}],fb:'The quick ratio strips out the least liquid current assets (inventory must be sold first, prepaid cannot be converted to cash). A current ratio > 1.0 means CA > CL (can cover obligations). The "ideal" ratio varies by industry \u2014 retail often runs 1.5\u20132.0x.'}]},{id:"A5",num:5,title:"Bonds Payable \u2014 HorizonCo",topics:"Bond Issue Price \xB7 Discount \xB7 Effective Interest Method \xB7 Carrying Value",case:`HorizonCo issues 5-year bonds with a face value of $1,000,000 and a stated coupon rate of 8% (annual). At the time of issue, the market (effective) interest rate is 10%.

The finance team must calculate the issue price, record the discount, and apply the effective interest method for Year 1 amortization.`,exhibit:{headers:["Item","Data"],rows:[["Face Value","$1,000,000"],["Coupon Rate (stated)","8% annual"],["Annual Coupon Payment","$80,000"],["Market Rate at Issuance","10%"],["Term","5 years"],["PV Annuity Factor (10%, 5 yrs)","3.791"],["PV Single Payment Factor (10%, 5 yrs)","0.621"]]},questions:[{type:"calc",id:"A5Q1",text:"Calculate the issue price of the bonds.",hint:"Issue Price = PV of coupons + PV of face value. Use the provided PV factors.",exact:924280,tol:50,pre:"$",suf:"",fb:"PV of coupons = $80,000 \xD7 3.791 = $303,280. PV of face = $1,000,000 \xD7 0.621 = $621,000. Issue price = $924,280. Bonds issued BELOW face because market rate (10%) > coupon rate (8%) \u2014 investors demand a discount to earn market return."},{type:"calc",id:"A5Q2",text:"Calculate the Discount on Bonds Payable at issuance.",hint:"Discount = Face Value \u2212 Issue Price",exact:75720,tol:50,pre:"$",suf:"",fb:"Discount = $1,000,000 \u2212 $924,280 = $75,720. The discount represents additional interest cost above the coupon \u2014 it will be amortized over 5 years, increasing interest expense each year."},{type:"calc",id:"A5Q3",text:"Calculate Year 1 Interest Expense using the effective interest method.",hint:"Interest Expense = Beginning Carrying Value \xD7 Market Rate",exact:92428,tol:50,pre:"$",suf:"",fb:"Year 1 Interest Expense = $924,280 \xD7 10% = $92,428. The effective interest method applies the market rate to the CARRYING VALUE \u2014 not the face value. Expense exceeds the $80,000 cash coupon because the bond was issued at a discount."},{type:"calc",id:"A5Q4",text:"Calculate the discount amortized in Year 1.",hint:"Discount Amortized = Interest Expense \u2212 Cash Coupon Paid",exact:12428,tol:50,pre:"$",suf:"",fb:"Amortized = $92,428 \u2212 $80,000 = $12,428. Each year, the discount amortization INCREASES the carrying value of the bond, bringing it toward face value by maturity. The carrying value after Year 1 = $924,280 + $12,428 = $936,708."},{type:"select",id:"A5Q5",text:"Because the market rate (10%) exceeds the coupon rate (8%), the bonds were issued:",opts:["At a premium \u2014 above face value","At face value \u2014 par","At a discount \u2014 below face value","At salvage value"],ans:2,fb:"Market rate > coupon rate \u2192 bonds issued at a DISCOUNT (below face). Buyers pay less than face because the coupon payments are below market. Conversely: market rate < coupon rate \u2192 premium (above face). Market rate = coupon rate \u2192 issued at par (face value)."},{type:"blank",id:"A5Q6",text:"Under the effective interest method, interest expense equals carrying value \xD7 [B1] rate. When bonds are issued at a discount, interest expense is [B2] than the cash coupon paid each period.",blanks:[{id:"B1",opts:["market (effective)","coupon (stated)","average"],ans:"market (effective)"},{id:"B2",opts:["higher","lower","equal"],ans:"higher"}],fb:"Effective interest method: Interest Expense = CV \xD7 market rate. Cash paid = Face \xD7 coupon rate. For discount bonds: CV < Face and market rate > coupon rate \u2192 Interest Expense > Cash paid. The difference is amortization of the discount, which increases CV each year until it reaches face value at maturity."}]},{id:"A6",num:6,title:"Leases (ASC 842) \u2014 FlexSpace Corp",topics:"ASC 842 \xB7 Finance vs Operating Lease \xB7 ROU Asset \xB7 Lease Liability \xB7 Interest Expense",case:`FlexSpace Corp signs a 4-year lease for manufacturing equipment on January 1. The company must determine the lease classification under ASC 842, record the Right-of-Use (ROU) asset and lease liability at inception, and calculate Year 1 expenses.

No ownership transfer occurs at lease end, and there is no purchase option. The asset has an economic life of 6 years and a fair value of $110,000.`,exhibit:{headers:["Lease Term","Annual Payment (end of year)","Implicit Rate","PV Annuity Factor (6%, 4 yrs)","Economic Life","Fair Value of Asset"],rows:[["4 years","$30,000","6%","3.465","6 years","$110,000"]]},questions:[{type:"calc",id:"A6Q1",text:"Calculate the present value of lease payments (initial lease liability).",hint:"PV = Annual Payment \xD7 PV Annuity Factor",exact:103950,tol:10,pre:"$",suf:"",fb:"PV = $30,000 \xD7 3.465 = $103,950. This becomes BOTH the initial lease liability AND the ROU asset on the balance sheet at commencement. Under ASC 842, ALL leases with terms > 12 months must be recognized on the balance sheet."},{type:"select",id:"A6Q2",text:"Under ASC 842, this lease is classified as a Finance Lease because:",opts:["The lease term (4 yrs) exceeds 75% of economic life (6 yrs)","The PV of lease payments ($103,950) is \u2265 90% of fair value ($110,000) \u2014 94.5%","Ownership transfers at end of lease","The asset has no alternative use to the lessor"],ans:1,fb:"PV/FV = $103,950 \xF7 $110,000 = 94.5% \u2265 90% \u2192 Finance Lease criterion met. Note: lease term test fails (4/6 = 67% < 75%). Only ONE criterion needs to be met for finance lease classification. The 5 criteria: (1) Ownership transfer, (2) Purchase option, (3) Lease term \u2265 75% economic life, (4) PV \u2265 90% fair value, (5) Specialized asset."},{type:"calc",id:"A6Q3",text:"Calculate Year 1 interest expense on the lease liability.",hint:"Interest = Beginning Lease Liability \xD7 Implicit Rate",exact:6237,tol:10,pre:"$",suf:"",fb:"Year 1 Interest = $103,950 \xD7 6% = $6,237. For a finance lease, interest expense is recorded SEPARATELY from amortization of the ROU asset \u2014 similar to a financed purchase. This is a key difference from an operating lease (which records a single straight-line lease cost)."},{type:"calc",id:"A6Q4",text:"Calculate Year 1 amortization expense for the ROU asset (straight-line over lease term).",hint:"Annual Amortization = ROU Asset \xF7 Lease Term",exact:25988,tol:50,pre:"$",suf:"",fb:"Annual Amortization = $103,950 \xF7 4 years = $25,987.50 \u2248 $25,988. For a FINANCE lease, the ROU asset is amortized over the lease term (not economic life, since no ownership transfer). Total Year 1 P&L impact: $6,237 interest + $25,988 amortization = $32,225 \u2014 front-loaded compared to operating lease's $30,000 straight-line cost."},{type:"drag",id:"A6Q5",text:"Classify each item under Finance Lease accounting:",items:["ROU Asset","Lease Liability","Interest Expense","Amortization of ROU Asset"],zones:["Balance Sheet","Income Statement"],correct:{"ROU Asset":"Balance Sheet","Lease Liability":"Balance Sheet","Interest Expense":"Income Statement","Amortization of ROU Asset":"Income Statement"},fb:"ASC 842 Finance Lease: Balance Sheet \u2192 ROU Asset (non-current asset) + Lease Liability (current & non-current portions). Income Statement \u2192 Interest Expense (finance cost, declining each year) + Amortization Expense (straight-line, constant each year). Total expense is front-loaded vs. a flat operating lease cost."},{type:"blank",id:"A6Q6",text:"Under ASC 842, the ROU asset and lease liability are initially measured at the [B1] of future lease payments. An operating lease records a single [B2] lease cost, while a finance lease records interest and amortization separately.",blanks:[{id:"B1",opts:["present value","future value","face value"],ans:"present value"},{id:"B2",opts:["straight-line","accelerated","declining balance"],ans:"straight-line"}],fb:"Both finance and operating leases recognize an ROU asset and liability = PV of remaining payments. The KEY difference is P&L treatment: Operating lease \u2192 single straight-line lease cost (rent-like). Finance lease \u2192 interest expense (declining) + amortization (constant) = front-loaded total expense. Operating lease better for income optics in early years."}]},{id:"A7",num:7,title:"Cash Flow Statement \u2014 RetailPrime Corp",topics:"Indirect Method \xB7 Operating \xB7 Investing \xB7 Financing \xB7 Non-cash Items",case:`RetailPrime Corp's accountant must prepare the Statement of Cash Flows for the year using the indirect method. The income statement and balance sheet changes have been compiled, along with selected transaction data.

The company sold equipment during the year at a gain. All other transactions are as described in the exhibit.`,exhibit:{headers:["Item","Amount"],rows:[["Net Income","$120,000"],["Depreciation Expense","$35,000"],["Gain on Sale of Equipment","$12,000"],["Increase in Accounts Receivable","$18,000"],["Decrease in Inventory","$25,000"],["Increase in Accounts Payable","$8,000"],["Purchase of New Equipment","$(80,000)"],["Proceeds from Equipment Sale","$32,000"],["Issuance of Long-Term Bonds","$100,000"],["Repayment of Bank Loan","$(40,000)"],["Cash Dividends Paid","$(20,000)"]]},questions:[{type:"calc",id:"A7Q1",text:"Calculate Net Cash Provided by Operating Activities (CFO).",hint:"Start with Net Income. Add back non-cash items (depreciation). Remove non-operating gains. Adjust for working capital changes.",exact:158e3,tol:0,pre:"$",suf:"",fb:"CFO = $120,000 NI + $35,000 depreciation \u2212 $12,000 gain \u2212 $18,000 AR increase + $25,000 inventory decrease + $8,000 AP increase = $158,000. Key rule: increases in current assets are OUTFLOWS (uses of cash); increases in current liabilities are INFLOWS (sources of cash)."},{type:"calc",id:"A7Q2",text:"Calculate Net Cash Used in Investing Activities (CFI).",hint:"Investing = long-term asset transactions. Include both equipment purchase AND proceeds from sale.",exact:48e3,tol:0,pre:"$",suf:" outflow",fb:"CFI = \u2212$80,000 (purchase) + $32,000 (sale proceeds) = \u2212$48,000 net outflow. Note: the FULL $32,000 proceeds appear here \u2014 not $20,000 book value. The $12,000 gain is removed from CFO precisely because the full proceeds belong in CFI. Double-counting is avoided this way."},{type:"calc",id:"A7Q3",text:"Calculate Net Cash Provided by Financing Activities (CFF).",hint:"Financing = debt and equity transactions with lenders and investors.",exact:4e4,tol:0,pre:"$",suf:"",fb:"CFF = +$100,000 bonds \u2212 $40,000 loan repayment \u2212 $20,000 dividends = $40,000 net inflow. Dividends PAID = financing outflow under US GAAP (IFRS allows operating or financing). Dividends RECEIVED = operating or investing under GAAP (operating or financing under IFRS)."},{type:"select",id:"A7Q4",text:"Why is the $12,000 gain on equipment sale SUBTRACTED in the operating section?",opts:["Because gains are not real cash flows","Because the full sale proceeds ($32,000) are reported in investing \u2014 keeping the gain in NI would double-count the cash","Because gains reduce taxes","Because equipment is a current asset"],ans:1,fb:"The cash received from the sale ($32,000) is properly reported as an investing inflow. Net income already includes the $12,000 gain. If we don't subtract it from CFO, the $12,000 would be counted twice: once in NI (operating) and once in CFI (investing). The subtraction in CFO eliminates this double-count."},{type:"drag",id:"A7Q5",text:"Classify each item in the indirect method cash flow statement:",items:["Depreciation add-back","Increase in Accounts Receivable","Purchase of Equipment","Issuance of Bonds","Dividends Paid"],zones:["Operating","Investing","Financing"],correct:{"Depreciation add-back":"Operating","Increase in Accounts Receivable":"Operating","Purchase of Equipment":"Investing","Issuance of Bonds":"Financing","Dividends Paid":"Financing"},fb:"Operating: all NI adjustments (non-cash items + working capital changes). Investing: long-term asset transactions (buy/sell PP&E, investments, lending). Financing: transactions with capital providers \u2014 debt (borrow/repay) and equity (issue stock, pay dividends, buy back shares)."},{type:"blank",id:"A7Q6",text:"Depreciation is added back to net income because it is a [B1] expense that reduces income but does NOT reduce cash. The gain on asset sale is subtracted because the full proceeds are reported under [B2] activities.",blanks:[{id:"B1",opts:["non-cash","variable","operating"],ans:"non-cash"},{id:"B2",opts:["investing","operating","financing"],ans:"investing"}],fb:"Indirect method logic: start with accrual-based NI and convert to cash basis. Add back non-cash charges (depreciation, amortization). Remove non-operating items (gains/losses on asset sales \u2014 belongs in CFI). Adjust for working capital changes. Result = cash actually generated from core operations."}]},{id:"A8",num:8,title:"Deferred Taxes \u2014 PrecisionTech Corp",topics:"Deferred Tax Liability \xB7 Deferred Tax Asset \xB7 Temporary vs Permanent Differences \xB7 Tax Expense",case:`PrecisionTech Corp reports pre-tax book income of $300,000 for the year. The tax department has identified three items that create differences between book and taxable income.

The corporate tax rate is 25%. The finance team must calculate the deferred tax balances and total income tax expense.`,exhibit:{headers:["Item","Book Treatment","Tax Treatment","Type of Difference"],rows:[["Depreciation","$60,000 (straight-line)","$100,000 (MACRS accelerated)","Temporary"],["Warranty Expense","$30,000 (accrued at sale)","$0 (deductible when paid)","Temporary"],["Municipal Bond Interest","$10,000 income recognized","Not taxable \u2014 exempt","Permanent"]]},questions:[{type:"calc",id:"A8Q1",text:"Calculate the Deferred Tax Liability (DTL) created by the depreciation difference.",hint:"DTL = (Tax Depreciation \u2212 Book Depreciation) \xD7 Tax Rate",exact:1e4,tol:0,pre:"$",suf:"",fb:"Depreciation difference = $100,000 \u2212 $60,000 = $40,000. DTL = $40,000 \xD7 25% = $10,000. Accelerated tax depreciation makes taxable income LOWER now \u2192 tax savings now but higher taxes later \u2192 LIABILITY. The company has a future obligation to pay these taxes when the temporary difference reverses."},{type:"calc",id:"A8Q2",text:"Calculate the Deferred Tax Asset (DTA) created by the warranty difference.",hint:"DTA = Warranty Expense (book only) \xD7 Tax Rate",exact:7500,tol:0,pre:"$",suf:"",fb:"Warranty difference = $30,000 \u2212 $0 = $30,000. DTA = $30,000 \xD7 25% = $7,500. Book recognizes warranty expense NOW but tax only allows deduction when warranty is PAID \u2192 taxable income is HIGHER now \u2192 prepaid taxes \u2192 ASSET. The DTA represents future tax savings when the warranty is actually paid and becomes deductible."},{type:"calc",id:"A8Q3",text:"Calculate taxable income for the year.",hint:"Start with book income. Subtract extra tax depreciation. Add back warranty (not yet deductible). Subtract municipal bond interest (permanent \u2014 never taxable).",exact:28e4,tol:0,pre:"$",suf:"",fb:"Taxable Income = $300,000 \u2212 ($100,000\u2212$60,000) + $30,000 \u2212 $10,000 = $300,000 \u2212 $40,000 + $30,000 \u2212 $10,000 = $280,000. The municipal bond interest reduces taxable income permanently (it's never taxable). This is why the effective tax rate differs from the statutory 25%."},{type:"calc",id:"A8Q4",text:"Calculate total Income Tax Expense for the year (book basis).",hint:"Tax Expense = Current Tax Payable + Net Deferred Tax Expense (DTL \u2212 DTA)",exact:72500,tol:0,pre:"$",suf:"",fb:"Current tax payable = $280,000 \xD7 25% = $70,000. Net deferred expense = DTL $10,000 \u2212 DTA $7,500 = $2,500. Total Tax Expense = $70,000 + $2,500 = $72,500. Check: ($300,000 \u2212 $10,000 permanent) \xD7 25% = $290,000 \xD7 25% = $72,500 \u2713. Permanent differences affect the EFFECTIVE tax rate; temporary differences affect TIMING only."},{type:"select",id:"A8Q5",text:"Which item creates a PERMANENT difference (not reversing in future periods)?",opts:["Accelerated depreciation \u2014 reverses as asset depreciates","Warranty expense \u2014 reverses when warranty is paid","Municipal bond interest \u2014 exempt from tax in all periods","All three are permanent differences"],ans:2,fb:"Permanent differences NEVER reverse \u2014 they affect the effective tax rate forever. Examples: municipal bond interest (tax-exempt income), fines/penalties (not deductible), life insurance premiums. Temporary differences reverse over time: depreciation reverses over asset life; warranty reverses when paid. Permanent differences create NO deferred tax; only temporary differences create DTAs/DTLs."},{type:"blank",id:"A8Q6",text:"A Deferred Tax Liability arises when taxable income is [B1] than book income in the current period, creating a future tax [B2]. A Deferred Tax Asset arises when taxable income is higher than book income, representing future tax [B3].",blanks:[{id:"B1",opts:["lower","higher","equal"],ans:"lower"},{id:"B2",opts:["obligation (payable)","benefit (savings)","credit"],ans:"obligation (payable)"},{id:"B3",opts:["savings (benefits)","obligations","losses"],ans:"savings (benefits)"}],fb:"DTL: Low taxable income NOW \u2192 low tax NOW \u2192 higher tax LATER = liability (owe future taxes). DTA: High taxable income NOW \u2192 high tax NOW \u2192 lower tax LATER = asset (prepaid taxes, future savings). Both arise from TEMPORARY differences only."}]},{id:"A9",num:9,title:"Earnings Per Share \u2014 BlueStar Corp",topics:"Basic EPS \xB7 Diluted EPS \xB7 Weighted Average Shares \xB7 Treasury Stock Method",case:`BlueStar Corp reports net income of $450,000 for the year ended December 31. The company has both common shares and potentially dilutive securities outstanding.

The finance team must calculate basic and diluted EPS following ASC 260, applying the weighted average and treasury stock method.`,exhibit:{headers:["Item","Details"],rows:[["Net Income","$450,000"],["Preferred Dividends (non-convertible)","$0"],["Shares Jan 1","100,000 common shares"],["Shares Apr 1","Issued 20,000 new shares (9 months remaining)"],["Shares Oct 1","Repurchased 10,000 treasury shares (3 months remaining)"],["Stock Options Outstanding","10,000 options, exercise price $30"],["Average Market Price","$40 per share"]]},questions:[{type:"calc",id:"A9Q1",text:"Calculate the Weighted Average Shares Outstanding (WASO) for Basic EPS.",hint:"Weight each share tranche by fraction of year: 100,000\xD7(12/12) + 20,000\xD7(9/12) \u2212 10,000\xD7(3/12)",exact:112500,tol:0,pre:"",suf:" shares",fb:"WASO = 100,000\xD71.00 + 20,000\xD70.75 \u2212 10,000\xD70.25 = 100,000 + 15,000 \u2212 2,500 = 112,500. New shares issued Apr 1 are outstanding 9/12 of the year. Treasury shares repurchased Oct 1 reduce shares for 3/12 of the year."},{type:"calc",id:"A9Q2",text:"Calculate Basic EPS.",hint:"Basic EPS = (Net Income \u2212 Preferred Dividends) \xF7 WASO",exact:4,tol:.01,pre:"$",suf:"",fb:"Basic EPS = $450,000 \xF7 112,500 = $4.00. No preferred dividends to subtract. Basic EPS uses only actual shares outstanding \u2014 no adjustment for potentially dilutive options or convertible securities."},{type:"calc",id:"A9Q3",text:"Using the Treasury Stock Method, calculate the NET dilutive shares from the stock options.",hint:"Proceeds = options \xD7 exercise price. Hypothetical buyback = proceeds \xF7 market price. Net dilutive = options \u2212 buyback.",exact:2500,tol:0,pre:"",suf:" shares",fb:"Proceeds = 10,000 \xD7 $30 = $300,000. Hypothetical buyback = $300,000 \xF7 $40 = 7,500 shares. Net dilutive = 10,000 \u2212 7,500 = 2,500 shares."},{type:"calc",id:"A9Q4",text:"Calculate Diluted EPS.",hint:"Diluted WASO = Basic WASO + net dilutive shares from options.",exact:3.91,tol:.02,pre:"$",suf:"",fb:"Diluted WASO = 112,500 + 2,500 = 115,000. Diluted EPS = $450,000 \xF7 115,000 = $3.913 \u2248 $3.91. Diluted EPS is always \u2264 Basic EPS because adding shares to the denominator reduces EPS."},{type:"select",id:"A9Q5",text:"A stock option with an exercise price of $45 when the average market price is $40 would be:",opts:["Dilutive \u2014 always included in diluted EPS","Antidilutive \u2014 excluded from diluted EPS because it would increase EPS","Included at half weight in diluted EPS","Treated the same as a stock dividend"],ans:1,fb:"Exercise price ($45) > Market price ($40): the treasury stock method produces NEGATIVE net dilutive shares, which would INCREASE EPS. Antidilutive securities are EXCLUDED from diluted EPS. Rule: always exclude any security that increases EPS."},{type:"blank",id:"A9Q6",text:"Basic EPS uses [B1] shares outstanding. Diluted EPS adds [B2] dilutive shares from options (using the treasury stock method) to show the maximum potential dilution.",blanks:[{id:"B1",opts:["weighted average actual","total authorized","total issued"],ans:"weighted average actual"},{id:"B2",opts:["net","gross","authorized"],ans:"net"}],fb:"Basic EPS = (NI \u2212 Pref Div) \xF7 WASO. Diluted EPS = (NI + convertible adjustments) \xF7 (WASO + net dilutive shares). Treasury stock method: options grant shares but proceeds buy back shares \u2192 only NET additional shares are added."}]},{id:"A10",num:10,title:"Comprehensive Income & OCI \u2014 OmegaHoldings Corp",topics:"OCI \xB7 Comprehensive Income \xB7 AOCI \xB7 AFS Securities \xB7 Pension Adjustment",case:`OmegaHoldings Corp reports net income of $200,000 for the current year. In addition to net income, several items affected equity during the year but are NOT reported on the income statement.

The AOCI balance at the beginning of the year was $(8,000). The corporate tax rate is 25%.`,exhibit:{headers:["OCI Item","Pre-Tax Amount","Tax Effect (25%)","After-Tax OCI"],rows:[["Unrealized Gain on AFS Debt Securities","$40,000","$(10,000)","$30,000"],["Foreign Currency Translation Loss","$(15,000)","$3,750","$(11,250)"],["Pension Liability Adjustment (loss)","$(5,000)","$1,250","$(3,750)"],["Total OCI","$20,000","$(5,000)","$15,000"]]},questions:[{type:"calc",id:"A10Q1",text:"Calculate Total Other Comprehensive Income (OCI) for the year, net of tax.",hint:"Sum all after-tax OCI items from the exhibit.",exact:15e3,tol:0,pre:"$",suf:"",fb:"Total OCI = $30,000 \u2212 $11,250 \u2212 $3,750 = $15,000 net of tax. OCI captures value changes that affect equity but bypass the income statement."},{type:"calc",id:"A10Q2",text:"Calculate Comprehensive Income for the year.",hint:"Comprehensive Income = Net Income + Other Comprehensive Income",exact:215e3,tol:0,pre:"$",suf:"",fb:"Comprehensive Income = $200,000 + $15,000 = $215,000. Net income captures operating performance; OCI captures valuation and translation changes. Together they equal comprehensive income."},{type:"calc",id:"A10Q3",text:"Calculate the ending balance of Accumulated Other Comprehensive Income (AOCI).",hint:"AOCI ending = AOCI beginning + Current year OCI",exact:7e3,tol:0,pre:"$",suf:"",fb:"AOCI ending = $(8,000) + $15,000 = $7,000. AOCI is a component of Stockholders' Equity on the balance sheet that accumulates all prior OCI items not yet reclassified to net income."},{type:"select",id:"A10Q4",text:"Which financial statement presents Other Comprehensive Income?",opts:["Income Statement only \u2014 as a separate section after net income","Balance Sheet only \u2014 as a component of equity","Either a combined Statement of Comprehensive Income OR two separate statements (IS + SCI)","The Statement of Cash Flows"],ans:2,fb:"GAAP (ASC 220) allows TWO formats: (1) ONE combined statement \u2014 NI section followed by OCI section, OR (2) TWO separate statements. Both are acceptable. AOCI accumulates on the Balance Sheet under stockholders' equity."},{type:"drag",id:"A10Q5",text:"Classify each item as Net Income (NI) or Other Comprehensive Income (OCI):",items:["Revenue from sales","Unrealized gain on AFS securities","Foreign currency translation adjustment","Depreciation expense","Pension liability adjustment"],zones:["Net Income (NI)","Other Comprehensive Income (OCI)"],correct:{"Revenue from sales":"Net Income (NI)","Unrealized gain on AFS securities":"Other Comprehensive Income (OCI)","Foreign currency translation adjustment":"Other Comprehensive Income (OCI)","Depreciation expense":"Net Income (NI)","Pension liability adjustment":"Other Comprehensive Income (OCI)"},fb:"Net Income: revenues, expenses, gains and losses from operations. OCI: 4 main categories \u2014 (1) Unrealized gains/losses on AFS debt securities, (2) Foreign currency translation adjustments, (3) Pension/OPEB adjustments, (4) Effective portion of cash flow hedges."},{type:"blank",id:"A10Q6",text:"Comprehensive Income equals Net Income PLUS [B1]. The cumulative balance of OCI items is reported on the balance sheet as [B2], a component of stockholders' equity.",blanks:[{id:"B1",opts:["Other Comprehensive Income","Retained Earnings","Dividends"],ans:"Other Comprehensive Income"},{id:"B2",opts:["Accumulated Other Comprehensive Income (AOCI)","Additional Paid-in Capital","Treasury Stock"],ans:"Accumulated Other Comprehensive Income (AOCI)"}],fb:"Formula: Comprehensive Income = NI + OCI. The running total of all OCI items lives in AOCI on the balance sheet. When realized (e.g., AFS security sold), the amount is reclassified from AOCI into net income \u2014 called recycling."}]}],B:[{id:"B1",num:1,title:"Flexible Budget Analysis \u2014 Greenfield Manufacturing",topics:"Flexible Budget \xB7 Sales Volume Variance \xB7 Flexible Budget Variance",case:`Greenfield Manufacturing uses a standard costing and flexible budgeting system. At the start of the year, management prepared a static budget based on expected production and sales of 10,000 units.

At year-end, actual results showed production and sales of 12,000 units \u2014 20% above plan. The CFO needs to separate the overall variance into its two components to correctly evaluate performance.`,exhibit:{headers:["Item","Static Budget (10,000 units)","Actual Results (12,000 units)"],rows:[["Units Sold","10,000","12,000"],["Revenue","$500,000  ($50/unit)","$570,000  ($47.50/unit)"],["Variable Costs","$300,000  ($30/unit)","$375,000  ($31.25/unit)"],["Fixed Costs","$80,000","$85,000"],["Operating Income","$120,000","$110,000"]]},questions:[{type:"calc",id:"B1Q1",text:"Calculate the Flexible Budget Operating Income at the actual volume of 12,000 units.",hint:"Flex Revenue = 12,000 \xD7 $50. Flex VC = 12,000 \xD7 $30. Fixed stays at $80,000.",exact:16e4,tol:10,pre:"$",suf:"",fb:"Flex Revenue = 12,000 \xD7 $50 = $600,000. Flex VC = 12,000 \xD7 $30 = $360,000. Fixed = $80,000. Flex OI = $600,000 \u2212 $360,000 \u2212 $80,000 = $160,000."},{type:"calc",id:"B1Q2",text:"Calculate the Sales Volume Variance (in Operating Income).",hint:"Sales Volume Variance = Flexible Budget OI \u2212 Static Budget OI",exact:4e4,tol:10,pre:"$",suf:"",fb:"SV Variance = $160,000 \u2212 $120,000 = $40,000 Favorable. Selling more units than planned creates a favorable volume variance."},{type:"calc",id:"B1Q3",text:"Calculate the Flexible Budget Variance (in Operating Income).",hint:"Flexible Budget Variance = Actual OI \u2212 Flexible Budget OI",exact:5e4,tol:10,pre:"$",suf:"",fb:"FB Variance = $110,000 \u2212 $160,000 = \u2212$50,000 Unfavorable. Despite selling more, higher variable costs and lower selling price per unit eroded profitability."},{type:"select",id:"B1Q4",text:"The Sales Volume Variance is Favorable. What is the most accurate explanation?",opts:["The company charged a higher price than budgeted","The company sold more units than the static budget planned","The company controlled variable costs better than planned","Fixed costs were lower than budgeted"],ans:1,fb:"The Sales Volume Variance measures ONLY the effect of selling more (or fewer) units than planned \u2014 holding prices and costs at standard. Selling 2,000 extra units at the standard CM explains the $40,000 F variance."},{type:"drag",id:"B1Q5",text:"Classify each variance as Favorable (F) or Unfavorable (U):",items:["Sales Volume Variance","Flexible Budget Variance","Overall Static Budget Variance","Selling Price Variance"],zones:["Favorable","Unfavorable"],correct:{"Sales Volume Variance":"Favorable","Flexible Budget Variance":"Unfavorable","Overall Static Budget Variance":"Unfavorable","Selling Price Variance":"Unfavorable"},fb:"SV = $40K F (more units). FB Variance = $50K U (higher VC + lower price). Overall = $10K U ($110K \u2212 $120K). Selling Price = ($47.50 \u2212 $50) \xD7 12,000 = $30,000 U."},{type:"blank",id:"B1Q6",text:"The flexible budget adjusts for changes in [B1], but does NOT adjust for changes in [B2] or selling price.",blanks:[{id:"B1",opts:["volume/activity level","fixed costs","selling price"],ans:"volume/activity level"},{id:"B2",opts:["variable cost per unit","sales units","contribution margin"],ans:"variable cost per unit"}],fb:"The flexible budget only adjusts revenue and variable costs for actual volume \u2014 it keeps the original standard price and standard variable cost per unit. It isolates the volume effect from efficiency and price effects."}]},{id:"B2",num:2,title:"Master Budget \u2014 SkyLine Products",topics:"Production Budget \xB7 DM Purchases Budget \xB7 Budget Sequence",case:`SkyLine Products is preparing its annual master budget. The sales team has finalized the sales forecast, and management has set inventory policies.

The production manager must build the production budget and then the purchasing manager needs the direct materials purchases budget to coordinate with suppliers.`,exhibit:{headers:["Item","Data"],rows:[["Budgeted Sales","8,000 units"],["Beginning Finished Goods","500 units"],["Desired Ending Finished Goods","800 units"],["DM Required per Unit","3 kg"],["DM Cost per kg","$4.00"],["Beginning DM Inventory","600 kg"],["Desired Ending DM Inventory","400 kg"]]},questions:[{type:"calc",id:"B2Q1",text:"Calculate the number of units to be produced.",hint:"Production = Sales + Ending FG Inventory \u2212 Beginning FG Inventory",exact:8300,tol:0,pre:"",suf:" units",fb:"Production = 8,000 + 800 \u2212 500 = 8,300 units. We need to produce more than we sell because desired ending inventory (800) exceeds beginning inventory (500)."},{type:"calc",id:"B2Q2",text:"Calculate the total Direct Materials (kg) needed for production.",hint:"DM Usage = Units to Produce \xD7 DM per Unit",exact:24900,tol:0,pre:"",suf:" kg",fb:"DM Usage = 8,300 units \xD7 3 kg/unit = 24,900 kg. This is the USAGE budget \u2014 how much DM is consumed in production."},{type:"calc",id:"B2Q3",text:"Calculate the Direct Materials to be PURCHASED (in kg).",hint:"Purchases = DM Usage + Ending DM Inventory \u2212 Beginning DM Inventory",exact:24700,tol:0,pre:"",suf:" kg",fb:"Purchases = 24,900 + 400 \u2212 600 = 24,700 kg. We need less than usage because we are drawing down DM inventory (ending < beginning)."},{type:"calc",id:"B2Q4",text:"Calculate the total cost of Direct Materials purchases.",hint:"Cost = kg to Purchase \xD7 Cost per kg",exact:98800,tol:0,pre:"$",suf:"",fb:"DM Purchases Cost = 24,700 kg \xD7 $4.00/kg = $98,800."},{type:"select",id:"B2Q5",text:"Which budget MUST be completed before the Direct Materials Purchases Budget can be prepared?",opts:["Cash Budget","Sales Budget only","Production Budget","Direct Labor Budget"],ans:2,fb:"The sequence is: Sales Budget \u2192 Production Budget \u2192 DM Usage Budget \u2192 DM Purchases Budget. The Production Budget must come first because DM usage depends on how many units will be produced \u2014 which depends on sales and inventory targets."},{type:"blank",id:"B2Q6",text:"Production Budget formula: Units to Produce = Budgeted [B1] + Desired Ending [B2] \u2212 Beginning [B2].",blanks:[{id:"B1",opts:["Sales","Purchases","Production"],ans:"Sales"},{id:"B2",opts:["Raw Materials","Finished Goods","Work in Process"],ans:"Finished Goods"}],fb:"This formula is the core of the production budget. It ensures the company produces enough to meet sales demand AND achieve its desired ending inventory level, while avoiding overproduction of units already in beginning inventory."}]},{id:"B3",num:3,title:"Capital Budgeting \u2014 Apex Industries",topics:"NPV \xB7 Payback Period \xB7 IRR Decision Rule",case:`Apex Industries is evaluating a new automated assembly machine. The CFO must apply capital budgeting techniques to decide whether to proceed.

The finance team has prepared the following data. The company's required rate of return (hurdle rate) is 12%. A PV annuity factor table has been provided.`,exhibit:{headers:["Item","Amount"],rows:[["Initial Investment","$200,000"],["Useful Life","5 years"],["Salvage Value","$0"],["Annual Net Cash Inflows","$60,000 / year"],["Required Rate of Return","12%"],["PV Annuity Factor (12%, 5 yrs)","3.605"],["Calculated IRR","~15.2%"]]},questions:[{type:"calc",id:"B3Q1",text:"Calculate the total Present Value of future cash inflows.",hint:"PV of Annuity = Annual Cash Flow \xD7 PV Annuity Factor",exact:216300,tol:50,pre:"$",suf:"",fb:"PV of Inflows = $60,000 \xD7 3.605 = $216,300. This is the present value of all five annual cash flows discounted at 12%."},{type:"calc",id:"B3Q2",text:"Calculate the Net Present Value (NPV) of the project.",hint:"NPV = PV of Inflows \u2212 Initial Investment",exact:16300,tol:50,pre:"$",suf:"",fb:"NPV = $216,300 \u2212 $200,000 = $16,300. Positive NPV means the project earns MORE than the required 12% \u2014 it creates value for shareholders."},{type:"calc",id:"B3Q3",text:"Calculate the Payback Period (in years). Round to 2 decimal places.",hint:"Payback = Initial Investment \xF7 Annual Cash Flow (even cash flows)",exact:3.33,tol:.05,pre:"",suf:" years",fb:"Payback = $200,000 \xF7 $60,000 = 3.33 years. The company recovers its investment in 3 years and 4 months."},{type:"select",id:"B3Q4",text:"Based on NPV = $16,300 and IRR = 15.2%, what is the correct investment decision?",opts:["Reject \u2014 payback exceeds 3 years","Accept \u2014 both NPV > 0 and IRR > hurdle rate confirm value creation","Reject \u2014 IRR is too close to the hurdle rate","Accept based on payback period only"],ans:1,fb:"Both methods agree: NPV > 0 means value is created above the required return. IRR (15.2%) > hurdle rate (12%) confirms the same. When NPV and IRR agree, the decision is clear. NPV is the superior method \u2014 always trust NPV in conflicts."},{type:"select",id:"B3Q5",text:"The MAJOR weakness of the Payback Period method is:",opts:["It is too difficult to calculate","It ignores cash flows after the payback period and ignores the time value of money","It requires knowledge of the discount rate","It always gives a shorter period than NPV"],ans:1,fb:"Payback ignores: (1) all cash flows AFTER recovery of investment \u2014 a project could pay back quickly then earn nothing; (2) the time value of money \u2014 $60,000 in year 1 is treated the same as $60,000 in year 5. It is used only as a RISK measure (liquidity)."},{type:"blank",id:"B3Q6",text:"When NPV is [B1] zero, the project earns exactly the required rate. When NPV is [B2] zero, the project should be accepted because it creates shareholder value.",blanks:[{id:"B1",opts:["greater than","equal to","less than"],ans:"equal to"},{id:"B2",opts:["greater than","equal to","less than"],ans:"greater than"}],fb:"NPV = 0: project earns exactly the hurdle rate \u2014 break-even in value terms. NPV > 0: earns MORE than required \u2192 ACCEPT. NPV < 0: earns LESS than required \u2192 REJECT. The IRR is actually the discount rate that makes NPV = 0."}]},{id:"B4",num:4,title:"Forecasting Methods \u2014 Bluebell Retail",topics:"Linear Regression \xB7 Exponential Smoothing \xB7 Smoothing Constant \u03B1",case:`Bluebell Retail uses quantitative forecasting to plan inventory and staffing. The analytics team has developed two forecasting models and needs to apply them to generate upcoming period forecasts.

Model 1: Linear regression based on historical monthly sales data.
Model 2: Exponential smoothing with smoothing constant \u03B1 = 0.3.`,exhibit:{headers:["Item","Data"],rows:[["Regression Equation","Y = $50,000 + $3,000X  (X = month number)"],["Forecast Month","Month 8"],["Smoothing Constant (\u03B1)","0.3"],["Prior Forecast (F\u2085)","$60,000"],["Actual Sales Month 5 (A\u2085)","$65,000"],["Rule: \u03B1 close to 1.0","Reacts QUICKLY to recent changes"],["Rule: \u03B1 close to 0","STABLE forecast, reacts slowly"]]},questions:[{type:"calc",id:"B4Q1",text:"Using the regression equation, calculate the sales forecast for Month 8.",hint:"Substitute X = 8 into Y = $50,000 + $3,000X",exact:74e3,tol:0,pre:"$",suf:"",fb:"Y = $50,000 + $3,000(8) = $50,000 + $24,000 = $74,000. The regression equation says sales grow by $3,000 per month (the slope = trend)."},{type:"calc",id:"B4Q2",text:"Using exponential smoothing (\u03B1 = 0.3), calculate the forecast for Month 6.",hint:"F\u2086 = \u03B1 \xD7 A\u2085 + (1 \u2212 \u03B1) \xD7 F\u2085",exact:61500,tol:10,pre:"$",suf:"",fb:"F\u2086 = 0.3 \xD7 $65,000 + 0.7 \xD7 $60,000 = $19,500 + $42,000 = $61,500. The new forecast weights recent actual (30%) more than the old forecast (70%)."},{type:"select",id:"B4Q3",text:"If \u03B1 is changed from 0.3 to 0.9, what happens to the forecast?",opts:["It becomes more stable and less reactive","It becomes more reactive \u2014 recent actual data gets 90% weight","It eliminates random/irregular variation completely","The forecast equals the actual from last period"],ans:1,fb:"\u03B1 = 0.9 means 90% weight on the most recent actual and only 10% on the old forecast. The forecast tracks recent changes very closely \u2014 highly reactive. \u03B1 = 0.1 would be very stable (slow to react). Choose \u03B1 based on how volatile the data is."},{type:"select",id:"B4Q4",text:"In the regression equation Y = $50,000 + $3,000X, what does the slope ($3,000) represent?",opts:["Total sales when X = 0","The fixed cost component of sales","The average monthly INCREASE in sales (trend)","The forecast error from last period"],ans:2,fb:'In regression Y = a + bX: "a" ($50,000) = intercept (base sales when X=0). "b" ($3,000) = slope = the expected change in Y for each one-unit increase in X. Here, sales are expected to grow by $3,000 per month.'},{type:"drag",id:"B4Q5",text:"Match each forecasting method to its best application:",items:["Simple Moving Average","Linear Regression","Exponential Smoothing","Time Series Decomposition"],zones:["Stable data, no trend","Predicts Y from X (trend line)","Weights recent data more","Seasonal patterns"],correct:{"Simple Moving Average":"Stable data, no trend","Linear Regression":"Predicts Y from X (trend line)","Exponential Smoothing":"Weights recent data more","Time Series Decomposition":"Seasonal patterns"},fb:"Moving Average: good for stable data. Regression: identifies trend and relationship between variables. Exponential Smoothing: adapts to recent changes via \u03B1. Time Series Decomposition: separates trend, seasonal, cyclical, and random components."},{type:"blank",id:"B4Q6",text:"Exponential smoothing formula: New Forecast = \u03B1 \xD7 [B1] + (1 \u2212 \u03B1) \xD7 [B2].",blanks:[{id:"B1",opts:["Prior Forecast","Actual Last Period","Moving Average"],ans:"Actual Last Period"},{id:"B2",opts:["Prior Forecast","Actual Last Period","Regression Value"],ans:"Prior Forecast"}],fb:"F(t+1) = \u03B1 \xD7 A(t) + (1\u2212\u03B1) \xD7 F(t). The new forecast is a weighted average of: the most recent ACTUAL result (weighted by \u03B1) and the PRIOR FORECAST (weighted by 1\u2212\u03B1). Higher \u03B1 = more weight to actual = more responsive forecast."}]},{id:"B5",num:5,title:"Cash Budget \u2014 CrystalClear Ltd",topics:"Cash Receipts \xB7 Cash Disbursements \xB7 Financing Needs",case:`CrystalClear Ltd prepares a monthly cash budget to manage liquidity. The treasurer has gathered the following data for March and needs to determine whether external financing will be required.

Company policy: maintain a minimum cash balance of $10,000 at all times. A line of credit is available if needed.`,exhibit:{headers:["Item","March Amount"],rows:[["Beginning Cash Balance","$20,000"],["Cash Sales","$80,000"],["Collections from Accounts Receivable","$45,000"],["Cash Purchases (Materials)","$60,000"],["Wages Paid","$25,000"],["Overhead Paid (cash)","$15,000"],["Equipment Purchase (capital)","$30,000"],["Minimum Required Cash Balance","$10,000"]]},questions:[{type:"calc",id:"B5Q1",text:"Calculate Total Cash Available for March.",hint:"Total Cash Available = Beginning Cash + Cash Receipts (Sales + Collections)",exact:145e3,tol:0,pre:"$",suf:"",fb:"Cash Available = $20,000 + $80,000 + $45,000 = $145,000. Beginning cash PLUS all cash inflows for the period = total cash available before any disbursements."},{type:"calc",id:"B5Q2",text:"Calculate Total Cash Disbursements for March.",hint:"Add all cash outflows: purchases + wages + overhead + equipment",exact:13e4,tol:0,pre:"$",suf:"",fb:"Disbursements = $60,000 + $25,000 + $15,000 + $30,000 = $130,000. Note: the equipment purchase is a cash outflow regardless of whether it is capital or operating in nature."},{type:"calc",id:"B5Q3",text:"Calculate the Ending Cash Balance BEFORE any financing.",hint:"Ending Cash = Total Cash Available \u2212 Total Disbursements",exact:15e3,tol:0,pre:"$",suf:"",fb:"Ending Cash (pre-financing) = $145,000 \u2212 $130,000 = $15,000. This is compared to the minimum required balance to determine if borrowing is needed."},{type:"select",id:"B5Q4",text:"Does CrystalClear need to borrow from its line of credit in March?",opts:["Yes \u2014 ending cash is below the minimum","No \u2014 ending cash of $15,000 exceeds the $10,000 minimum","Yes \u2014 the equipment purchase must always be financed separately","Cannot determine without knowing accounts payable"],ans:1,fb:"Ending cash ($15,000) > Minimum required ($10,000) \u2192 NO borrowing needed. The company has a $5,000 cushion above its minimum. If ending cash had been below $10,000, the company would borrow just enough to reach $10,000."},{type:"drag",id:"B5Q5",text:"Classify each item as Cash Receipt or Cash Disbursement in the cash budget:",items:["Collections from AR","Wages Paid","Equipment Purchase","Cash Sales"],zones:["Cash Receipt","Cash Disbursement"],correct:{"Collections from AR":"Cash Receipt","Wages Paid":"Cash Disbursement","Equipment Purchase":"Cash Disbursement","Cash Sales":"Cash Receipt"},fb:"Cash Receipts = all cash INFLOWS (sales, collections). Cash Disbursements = all cash OUTFLOWS regardless of type (operating or capital). The cash budget does not separate operating vs investing \u2014 it focuses purely on cash in vs cash out."},{type:"blank",id:"B5Q6",text:"The cash budget starts with [B1] cash, adds all cash [B2] to get Total Cash Available, then subtracts all cash [B3] to find ending cash before financing.",blanks:[{id:"B1",opts:["ending","beginning","minimum"],ans:"beginning"},{id:"B2",opts:["receipts","disbursements","profits"],ans:"receipts"},{id:"B3",opts:["receipts","disbursements","liabilities"],ans:"disbursements"}],fb:"Cash Budget structure: (1) Beginning Cash + (2) Cash Receipts = Total Available. Then subtract (3) Cash Disbursements = Ending Cash pre-financing. Compare to minimum balance \u2192 borrow if short, repay if excess. Simple but critical for liquidity management."}]},{id:"B6",num:6,title:"Strategic Analysis \u2014 ThriveWell Health Corp",topics:"SWOT Analysis \xB7 PEST Analysis \xB7 Strategic Planning",case:`ThriveWell Health Corp, a mid-size healthcare provider, is preparing its five-year strategic plan. Management has asked the finance team to help organize internal and external factors before setting objectives.

Internal note: ThriveWell has a strong brand reputation and modern facilities, but relies on a single aging billing system and has high staff turnover in nursing roles.

External note: New government healthcare reimbursement rules take effect next year, and a competitor is entering the local market with lower prices.`,exhibit:{headers:["Factor","Description"],rows:[["Strong brand reputation","Internal, positive"],["Aging billing system","Internal, negative"],["New reimbursement regulation","External"],["New low-price competitor","External"]]},questions:[{type:"select",id:"B6Q1",text:"The primary purpose of a SWOT analysis is to:",opts:["Forecast next years exact revenue","Organize internal and external factors to inform strategy","Calculate the companys cost of capital","Replace the need for a budget"],ans:1,fb:"SWOT organizes Strengths, Weaknesses (internal) and Opportunities, Threats (external) so management can match capabilities to the environment before setting strategy."},{type:"drag",id:"B6Q2",text:"Classify each factor into its correct SWOT category:",items:["Strong brand reputation","Aging billing system","New reimbursement regulation","New low-price competitor"],zones:["Strength","Weakness","Opportunity/Threat (External)"],correct:{"Strong brand reputation":"Strength","Aging billing system":"Weakness","New reimbursement regulation":"Opportunity/Threat (External)","New low-price competitor":"Opportunity/Threat (External)"},fb:"Strengths and weaknesses are internal to the company; opportunities and threats come from the external environment (regulation and competition here)."},{type:"select",id:"B6Q3",text:"A new government healthcare reimbursement rule belongs to which PEST category?",opts:["Political/Legal","Economic","Social","Technological"],ans:0,fb:"Government regulations and reimbursement rules fall under the Political/Legal category of PEST analysis."},{type:"drag",id:"B6Q4",text:"Classify each external factor into its PEST category:",items:["New reimbursement regulation","Aging population in the service area","Rising local interest rates","Telehealth adoption by patients"],zones:["Political","Economic","Social","Technological"],correct:{"New reimbursement regulation":"Political","Aging population in the service area":"Social","Rising local interest rates":"Economic","Telehealth adoption by patients":"Technological"},fb:"PEST separates the external environment into Political, Economic, Social, and Technological forces \u2014 each requires a different strategic response."},{type:"blank",id:"B6Q5",text:"SWOT analysis examines the [B1] environment through Strengths and Weaknesses, and the [B2] environment through Opportunities and Threats.",blanks:[{id:"B1",opts:["internal","external","financial"],ans:"internal"},{id:"B2",opts:["internal","external","financial"],ans:"external"}],fb:"Strengths/Weaknesses = internal (within managements control). Opportunities/Threats = external (outside managements direct control)."},{type:"select",id:"B6Q6",text:"Given the aging billing system (weakness) and the new low-price competitor (threat), the most strategically sound first move is to:",opts:["Ignore the competitor since ThriveWell has a strong brand","Modernize the billing system to protect margins before competing on price","Immediately match the competitors lower prices","Delay strategic planning until next year"],ans:1,fb:"Strategy should address a compounding weakness (inefficient billing raising costs) before engaging a price-based threat, since the weakness undermines the companys ability to compete on cost."}]},{id:"B7",num:7,title:"Standard Cost Card Development \u2014 GreenLeaf Furniture Co.",topics:"Standard Cost Card \xB7 DM/DL/OH Standards \xB7 Inventory Valuation",case:"GreenLeaf Furniture Co. is building the standard cost card for its new bookshelf model before the fiscal year begins. Engineering and purchasing have supplied the standard quantities and prices for each input.",exhibit:{headers:["Input","Standard Quantity","Standard Price/Rate"],rows:[["Direct Material","5 lbs","$4.00 per lb"],["Direct Labor","2 hrs","$15.00 per hr"],["Variable Overhead","2 hrs (labor hours)","$6.00 per hr"],["Fixed Overhead","2 hrs (labor hours)","$8.00 per hr"]]},questions:[{type:"calc",id:"B7Q1",text:"Calculate the standard direct material cost per unit.",hint:"Standard quantity \xD7 standard price",exact:20,tol:.5,pre:"$",suf:"",fb:"Standard DM cost = 5 lbs \xD7 $4.00 = $20.00 per unit."},{type:"calc",id:"B7Q2",text:"Calculate the standard direct labor cost per unit.",hint:"Standard hours \xD7 standard rate",exact:30,tol:.5,pre:"$",suf:"",fb:"Standard DL cost = 2 hrs \xD7 $15.00 = $30.00 per unit."},{type:"calc",id:"B7Q3",text:"Calculate the standard total VARIABLE cost per unit (DM + DL + Variable OH).",hint:"$20 + $30 + (2 hrs \xD7 $6)",exact:62,tol:.5,pre:"$",suf:"",fb:"Standard variable cost = $20 (DM) + $30 (DL) + $12 (2 hrs \xD7 $6 Variable OH) = $62 per unit."},{type:"calc",id:"B7Q4",text:"Calculate the standard TOTAL cost per unit (all four inputs).",hint:"$62 variable + (2 hrs \xD7 $8 Fixed OH)",exact:78,tol:.5,pre:"$",suf:"",fb:"Standard total cost = $62 variable + $16 (2 hrs \xD7 $8 Fixed OH) = $78 per unit."},{type:"select",id:"B7Q5",text:"Under a standard costing system, finished goods inventory is valued at:",opts:["Actual cost incurred","Standard cost","The lower of standard or actual cost","Selling price"],ans:1,fb:"Standard costing values inventory and COGS at standard cost; differences from actual cost are captured separately as variances."},{type:"blank",id:"B7Q6",text:"A standard cost card lists the [B1] quantity and [B2] price/rate for each input, which together set the benchmark used to calculate variances.",blanks:[{id:"B1",opts:["standard","actual","budgeted total"],ans:"standard"},{id:"B2",opts:["standard","actual","market"],ans:"standard"}],fb:"The standard cost card defines the standard quantity and standard price for each input \u2014 the baseline every variance is measured against."}]},{id:"B8",num:8,title:"Learning Curve Analysis \u2014 Precision Aerospace",topics:"Cumulative Average-Time Model \xB7 80% Learning Curve \xB7 Labor Estimation",case:"Precision Aerospace is quoting a contract for a new satellite bracket. The first unit required 100 direct labor hours. Based on historical data for similar assemblies, the engineering team applies an 80% cumulative average-time learning curve to estimate labor for the full production run.",exhibit:{headers:["Cumulative Units","Cumulative Average Time/Unit"],rows:[["1","100 hrs (given)"],["2","? (80% of unit-1 average)"],["4","? (80% of unit-2 average)"]]},questions:[{type:"calc",id:"B8Q1",text:"Calculate the cumulative average time per unit for 2 units.",hint:"100 hrs \xD7 80%",exact:80,tol:1,pre:"",suf:" hrs",fb:"Cumulative average time for 2 units = 100 \xD7 80% = 80 hours per unit."},{type:"calc",id:"B8Q2",text:"Calculate the TOTAL time required to produce the first 2 units.",hint:"Cumulative average \xD7 number of units",exact:160,tol:2,pre:"",suf:" hrs",fb:"Total time for 2 units = 80 hrs average \xD7 2 units = 160 hours."},{type:"calc",id:"B8Q3",text:"Calculate the incremental time required for just the 2nd unit alone.",hint:"Total time for 2 units \u2212 time for unit 1",exact:60,tol:2,pre:"",suf:" hrs",fb:"Time for unit 2 alone = 160 total hrs \u2212 100 hrs (unit 1) = 60 hours."},{type:"calc",id:"B8Q4",text:"Calculate the cumulative average time per unit for 4 units.",hint:"80-hr average (at 2 units) \xD7 80%",exact:64,tol:1,pre:"",suf:" hrs",fb:"Cumulative average time for 4 units = 80 \xD7 80% = 64 hours per unit (each doubling of units multiplies the average by the learning rate)."},{type:"calc",id:"B8Q5",text:"Calculate the TOTAL time required to produce the first 4 units.",hint:"Cumulative average \xD7 number of units",exact:256,tol:3,pre:"",suf:" hrs",fb:"Total time for 4 units = 64 hrs average \xD7 4 units = 256 hours."},{type:"select",id:"B8Q6",text:"An 80% learning curve means that:",opts:["Each additional unit takes 80% more time than the last","Total time falls by 20% every time cumulative output doubles","Cumulative average time falls to 80% of its prior value every time cumulative output doubles","Labor cost is fixed regardless of volume"],ans:2,fb:"The learning rate (80% here) applies to the cumulative AVERAGE time per unit each time cumulative production doubles \u2014 not to total time and not to every single unit."}]},{id:"B9",num:9,title:"Expected Value & Decision Under Uncertainty \u2014 RiverStone Consulting",topics:"Expected Value \xB7 Probability-Weighted Outcomes \xB7 Decision Analysis",case:"RiverStone Consulting is choosing between two possible projects for the coming year. Management has estimated three possible outcomes for each project, along with the probability of each outcome occurring.",exhibit:{headers:["Project A","Probability","Outcome"],rows:[["Best case","30%","$200,000"],["Base case","50%","$80,000"],["Worst case","20%","-$50,000"]]},questions:[{type:"calc",id:"B9Q1",text:"Calculate the Expected Value (EV) of Project A.",hint:"Sum of (probability \xD7 outcome) for all three scenarios",exact:9e4,tol:100,pre:"$",suf:"",fb:"EV(A) = (30% \xD7 $200,000) + (50% \xD7 $80,000) + (20% \xD7 -$50,000) = $60,000 + $40,000 \u2212 $10,000 = $90,000."},{type:"calc",id:"B9Q2",text:"Project B has a 40% chance of $150,000, a 40% chance of $60,000, and a 20% chance of $10,000. Calculate its Expected Value.",hint:"Sum of (probability \xD7 outcome) for all three scenarios",exact:86e3,tol:100,pre:"$",suf:"",fb:"EV(B) = (40% \xD7 $150,000) + (40% \xD7 $60,000) + (20% \xD7 $10,000) = $60,000 + $24,000 + $2,000 = $86,000."},{type:"select",id:"B9Q3",text:"Based on Expected Value alone, RiverStone should choose:",opts:["Project A, since it has the higher EV","Project B, since it has less downside risk","Either project, since EVs are essentially equal","Neither project, since Project A has a possible loss"],ans:0,fb:"Project A has the higher EV ($90,000 vs $86,000), so a purely EV-based decision favors Project A."},{type:"calc",id:"B9Q4",text:"Calculate the difference between Project As EV and Project Bs EV.",hint:"$90,000 \u2212 $86,000",exact:4e3,tol:100,pre:"$",suf:"",fb:"Difference = $90,000 \u2212 $86,000 = $4,000 in favor of Project A."},{type:"select",id:"B9Q5",text:"The main limitation of relying on Expected Value alone for this decision is that it:",opts:["Cannot be calculated without a computer","Ignores the variability (risk) of outcomes around the average","Only works when probabilities are unknown","Automatically accounts for managements risk tolerance"],ans:1,fb:"EV collapses a range of outcomes into a single average and ignores dispersion \u2014 Project A has a possible loss (-$50,000) that a risk-averse manager might weigh heavily even though its EV is higher."},{type:"blank",id:"B9Q6",text:"A [B1] is a visual tool that maps out sequential choices and their probability-weighted outcomes, often used alongside expected value to support decisions made under [B2].",blanks:[{id:"B1",opts:["decision tree","balanced scorecard","cost driver"],ans:"decision tree"},{id:"B2",opts:["certainty","uncertainty","budget constraints"],ans:"uncertainty"}],fb:"Decision trees are commonly paired with expected value analysis to evaluate sequential decisions under uncertainty."}]},{id:"B10",num:10,title:"Pro Forma Financial Statements \u2014 Meridian Retail Co.",topics:"Pro Forma Income Statement \xB7 Percent-of-Sales Method \xB7 Financial Forecasting",case:"Meridian Retail Co. had sales of $2,000,000 this year and expects 15% growth next year. Based on historical relationships, COGS is 60% of sales and operating expenses are 20% of sales. The tax rate is 25%.",exhibit:{headers:["Line Item","Basis"],rows:[["Current-year sales","$2,000,000"],["Growth rate","15%"],["COGS","60% of sales"],["Operating expenses","20% of sales"],["Tax rate","25%"]]},questions:[{type:"calc",id:"B10Q1",text:"Calculate projected (pro forma) sales for next year.",hint:"$2,000,000 \xD7 1.15",exact:23e5,tol:1e3,pre:"$",suf:"",fb:"Projected sales = $2,000,000 \xD7 1.15 = $2,300,000."},{type:"calc",id:"B10Q2",text:"Calculate projected COGS.",hint:"60% of projected sales",exact:138e4,tol:1e3,pre:"$",suf:"",fb:"Projected COGS = $2,300,000 \xD7 60% = $1,380,000."},{type:"calc",id:"B10Q3",text:"Calculate projected gross profit.",hint:"Projected sales \u2212 projected COGS",exact:92e4,tol:1e3,pre:"$",suf:"",fb:"Gross profit = $2,300,000 \u2212 $1,380,000 = $920,000."},{type:"calc",id:"B10Q4",text:"Calculate projected operating expenses.",hint:"20% of projected sales",exact:46e4,tol:1e3,pre:"$",suf:"",fb:"Operating expenses = $2,300,000 \xD7 20% = $460,000."},{type:"calc",id:"B10Q5",text:"Calculate projected net income BEFORE tax.",hint:"Gross profit \u2212 operating expenses",exact:46e4,tol:1e3,pre:"$",suf:"",fb:"Net income before tax = $920,000 \u2212 $460,000 = $460,000."},{type:"calc",id:"B10Q6",text:"Calculate projected net income AFTER tax.",hint:"Net income before tax \xD7 (1 \u2212 tax rate)",exact:345e3,tol:1e3,pre:"$",suf:"",fb:"Net income after tax = $460,000 \xD7 (1 \u2212 25%) = $345,000."}]}],E:[{id:"E1",num:1,title:"COSO Internal Control Framework \u2014 Apex Financial Services",topics:"COSO 5 Components \xB7 Control Deficiencies \xB7 Management Responsibility",case:`Apex Financial Services engaged an internal auditor to assess their internal control environment against the COSO Internal Control \u2014 Integrated Framework (2013).

The auditor identified four control deficiencies. Management must understand which COSO component is violated in each case and the severity classification of each deficiency.`,exhibit:{headers:["Finding","Description"],rows:[["Finding 1","AP clerk can both APPROVE vendor invoices AND record the payment in the system"],["Finding 2","IT system access has not been reviewed in 24 months \u2014 12 terminated employees still have active access"],["Finding 3","No formal process exists to identify and assess business risks that could affect financial reporting"],["Finding 4","Management has overridden controls 3 times this year without documented justification"]]},questions:[{type:"drag",id:"E1Q1",text:"Match each finding to the COSO component it primarily violates:",items:["Finding 1 \u2014 AP clerk dual role","Finding 2 \u2014 Stale IT access","Finding 3 \u2014 No risk process","Finding 4 \u2014 Management override"],zones:["Control Activities","Information & Communication","Risk Assessment","Control Environment"],correct:{"Finding 1 \u2014 AP clerk dual role":"Control Activities","Finding 2 \u2014 Stale IT access":"Information & Communication","Finding 3 \u2014 No risk process":"Risk Assessment","Finding 4 \u2014 Management override":"Control Environment"},fb:"Control Activities = policies that prevent/detect errors (segregation of duties). Information & Communication = accurate and timely data flows (access management is information security). Risk Assessment = identifying and analyzing risks. Control Environment = tone at the top, integrity, management philosophy \u2014 management override undermines the entire control environment."},{type:"select",id:"E1Q2",text:"Who bears PRIMARY responsibility for designing, implementing, and maintaining internal controls?",opts:["External auditors","The internal audit department","Management (CEO and CFO)","The board of directors"],ans:2,fb:"COSO is clear: MANAGEMENT is responsible for establishing and maintaining internal controls. The board provides oversight. Internal audit assesses and advises. External auditors attest (for public companies under SOX 404). Management cannot delegate this responsibility."},{type:"select",id:"E1Q3",text:"Which COSO component is considered the FOUNDATION of all other components?",opts:["Risk Assessment","Control Activities","Control Environment","Monitoring Activities"],ans:2,fb:`The Control Environment is the foundation \u2014 it sets the "tone at the top." It reflects management's commitment to integrity, ethical values, and competence. Without a strong control environment, other components are ineffective. COSO describes it as the "atmosphere" in which controls operate.`},{type:"select",id:"E1Q4",text:"Finding 1 (AP clerk approves AND records payments) is BEST classified as:",opts:["An inconsequential deficiency \u2014 no action needed","A control deficiency only if it results in an actual error","A significant deficiency or material weakness because it creates an unmitigated risk of material misstatement","A compliance issue only \u2014 not an internal control matter"],ans:2,fb:"Lack of segregation of duties in AP (authorization + recording by one person) is a classic SIGNIFICANT DEFICIENCY or MATERIAL WEAKNESS. It creates a direct opportunity for fraud or error with no compensating control. The severity depends on mitigating controls elsewhere \u2014 but as described, it is at minimum a significant deficiency."},{type:"drag",id:"E1Q5",text:"Classify each deficiency severity:",items:["Minor data entry error caught by reconciliation","AP clerk approves AND records \u2014 no compensating control","Risk assessment process completely absent \u2014 could affect all financial reporting"],zones:["Control Deficiency","Significant Deficiency","Material Weakness"],correct:{"Minor data entry error caught by reconciliation":"Control Deficiency","AP clerk approves AND records \u2014 no compensating control":"Significant Deficiency","Risk assessment process completely absent \u2014 could affect all financial reporting":"Material Weakness"},fb:"Control Deficiency: deviation unlikely to result in material misstatement. Significant Deficiency: less severe than material weakness but important \u2014 requires attention by those charged with governance. Material Weakness: reasonable possibility that material misstatement will not be prevented or detected on a timely basis."},{type:"blank",id:"E1Q6",text:"The COSO framework has [B1] components and [B2] underlying principles across those components.",blanks:[{id:"B1",opts:["3","5","8"],ans:"5"},{id:"B2",opts:["10","17","20"],ans:"17"}],fb:"COSO IC (2013): 5 components (Control Environment, Risk Assessment, Control Activities, Information & Communication, Monitoring) and 17 principles total. Each principle maps to a component. All 17 must be present and functioning for IC to be effective. Contrast with COSO ERM (2017) which has 5 components and 20 principles."}]},{id:"E2",num:2,title:"Enterprise Risk Management \u2014 NovaTech Manufacturing",topics:"ERM \xB7 Inherent Risk \xB7 Risk Response \xB7 Risk Appetite",case:`NovaTech Manufacturing is implementing COSO ERM. The risk committee has compiled the annual risk register, scoring each risk by its probability of occurrence and financial impact.

Management must calculate inherent risk scores, prioritize responses, and understand residual risk after controls are applied.`,exhibit:{headers:["Risk","Probability","Potential Impact","Risk Response Being Evaluated"],rows:[["IT System Failure","70%","$500,000","Disaster recovery plan (reduces probability to 20%)"],["Key Supplier Bankruptcy","20%","$800,000","Dual-source supplier strategy"],["Regulatory Fine","40%","$200,000","Compliance training program"],["Currency Fluctuation","60%","$50,000","Accept \u2014 cost of hedging exceeds benefit"]]},questions:[{type:"calc",id:"E2Q1",text:"Calculate the Inherent Risk Score (Expected Value) for IT System Failure.",hint:"Inherent Risk = Probability \xD7 Financial Impact (before any controls)",exact:35e4,tol:0,pre:"$",suf:"",fb:"Inherent Risk = 70% \xD7 $500,000 = $350,000. Inherent risk is the risk level BEFORE any controls or responses are applied. It represents the raw exposure to the risk event."},{type:"calc",id:"E2Q2",text:"Calculate the Inherent Risk Score for Key Supplier Bankruptcy.",hint:"Inherent Risk = Probability \xD7 Financial Impact",exact:16e4,tol:0,pre:"$",suf:"",fb:"Inherent Risk = 20% \xD7 $800,000 = $160,000. Note: although the impact is highest ($800K), the LOW probability (20%) makes this the second-highest risk score. Risk prioritization must consider BOTH dimensions \u2014 not just impact."},{type:"calc",id:"E2Q3",text:"If NovaTech implements the disaster recovery plan for IT, what is the RESIDUAL Risk Score?",hint:"Residual Risk = New Probability (20%) \xD7 Impact. The impact stays at $500,000.",exact:1e5,tol:0,pre:"$",suf:"",fb:"Residual Risk = 20% \xD7 $500,000 = $100,000. The control REDUCES probability from 70% to 20%, cutting the risk score from $350,000 to $100,000 \u2014 a $250,000 risk reduction. Residual risk is what remains AFTER controls are applied."},{type:"select",id:"E2Q4",text:"Accepting the Currency Fluctuation risk (60% probability, $50K impact) is BEST justified because:",opts:["Currency risk is never significant enough to manage","The cost of the hedging control likely exceeds the expected loss of $30,000","Currency fluctuations always resolve themselves","Only high-probability risks need to be managed"],ans:1,fb:"Risk ACCEPTANCE is appropriate when the cost of control > benefit. Expected loss = 60% \xD7 $50,000 = $30,000. If hedging costs more than $30,000, acceptance is rational. This is within management's risk appetite. Acceptance is a valid risk response \u2014 it doesn't mean ignoring the risk."},{type:"drag",id:"E2Q5",text:"Match each risk response strategy to its correct definition:",items:["Risk Avoidance","Risk Reduction","Risk Sharing","Risk Acceptance"],zones:["Exit the activity entirely \u2014 eliminate the risk","Implement controls to lower probability or impact","Transfer risk to another party (insurance, outsourcing)","Acknowledge the risk and take no action"],correct:{"Risk Avoidance":"Exit the activity entirely \u2014 eliminate the risk","Risk Reduction":"Implement controls to lower probability or impact","Risk Sharing":"Transfer risk to another party (insurance, outsourcing)","Risk Acceptance":"Acknowledge the risk and take no action"},fb:"COSO ERM four risk responses: Avoid = stop the activity (exit a risky market). Reduce = controls that lower probability or impact. Share = insurance, hedging, outsourcing (transfer to third party). Accept = do nothing \u2014 appropriate when risk is within appetite or cost of control exceeds benefit."},{type:"blank",id:"E2Q6",text:"Risk [B1] is the total amount of risk an organization is willing to accept in pursuit of its objectives. Residual risk = Inherent risk MINUS the effect of [B2].",blanks:[{id:"B1",opts:["appetite","tolerance","capacity"],ans:"appetite"},{id:"B2",opts:["controls/responses","market changes","audits"],ans:"controls/responses"}],fb:"Risk Appetite: broad statement of how much risk the entity is willing to accept (strategic). Risk Tolerance: acceptable variation around specific objectives (operational level). Residual risk is what remains after management responds \u2014 it should fall within risk tolerance. If residual risk > appetite \u2192 additional controls needed."}]},{id:"E3",num:3,title:"Fraud & the Fraud Triangle \u2014 RetailMax Inc.",topics:"Fraud Triangle \xB7 Asset Misappropriation \xB7 Detection Controls \xB7 Red Flags",case:`RetailMax Inc. discovered that a warehouse manager had been stealing inventory worth $180,000 over two years. The investigation revealed the following facts about the perpetrator and the environment that allowed the fraud to occur.

Management must analyze the fraud triangle elements and identify which controls were absent.`,exhibit:{headers:["Finding","Detail"],rows:[["Perpetrator profile","Had significant gambling debts \u2014 under severe financial pressure"],["Access structure","Was the ONLY person responsible for receiving inventory AND maintaining inventory records"],["Justification found",`Personal notes read: "I'll pay it back next month \u2014 just borrowing from the company"`],["Control gap 1","No physical inventory count had been performed for 18 months"],["Control gap 2","Inventory records were not reconciled to purchases for 6 months"],["Fraud type","Inventory stolen and sold for personal gain"]]},questions:[{type:"drag",id:"E3Q1",text:"Match each finding to the element of the Fraud Triangle it represents:",items:["Gambling debts \u2014 financial pressure","Sole custody of inventory AND records","Viewed theft as temporary borrowing"],zones:["Pressure (Incentive)","Opportunity","Rationalization"],correct:{"Gambling debts \u2014 financial pressure":"Pressure (Incentive)","Sole custody of inventory AND records":"Opportunity","Viewed theft as temporary borrowing":"Rationalization"},fb:`The Fraud Triangle (Donald Cressey): PRESSURE = personal financial need or incentive. OPPORTUNITY = weak controls that allow the fraud without detection. RATIONALIZATION = the perpetrator justifies the act to themselves ("I deserve it," "I'll pay it back"). All three elements are typically present in occupational fraud.`},{type:"select",id:"E3Q2",text:"Which type of occupational fraud did the warehouse manager commit?",opts:["Financial Statement Fraud \u2014 manipulating reported earnings","Corruption \u2014 bribery or kickbacks to/from vendors","Asset Misappropriation \u2014 theft of company assets","Management Override \u2014 bypassing controls"],ans:2,fb:"Asset Misappropriation = theft or misuse of company assets (cash, inventory, equipment). It is the MOST COMMON type of fraud (89% of cases) but typically involves the smallest dollar losses. Financial statement fraud is rarest but most costly. Corruption (bribery, kickbacks) falls in between."},{type:"select",id:"E3Q3",text:"Which control would have BEST PREVENTED this fraud from occurring?",opts:["Annual external audit of financial statements","Segregation of duties \u2014 separate the receiving function from inventory recordkeeping","Installing security cameras in the warehouse","Requiring manager to take annual vacation"],ans:1,fb:"SEGREGATION OF DUTIES is the primary PREVENTIVE control. The manager had BOTH custody (physical inventory) AND recordkeeping \u2014 the classic incompatible duties. Separating these roles means one person cannot steal AND cover it up. Cameras and audits are detective. Vacation is also detective (forces someone else to perform the role, revealing discrepancies)."},{type:"select",id:"E3Q4",text:"Which control would have DETECTED this fraud EARLIER?",opts:["Requiring the manager to sign an ethics code annually","Performing periodic physical inventory counts and reconciling to records","Background checks at the time of hiring","Encrypting the inventory database"],ans:1,fb:"Periodic PHYSICAL INVENTORY COUNTS reconciled to records is a DETECTIVE control \u2014 it would have revealed the shrinkage. The fraud went undetected for 18 months partly because no count was performed. Background checks prevent hiring bad actors (preventive). Ethics codes reduce rationalization but don't detect theft."},{type:"drag",id:"E3Q5",text:"Classify each control as Preventive or Detective:",items:["Segregation of duties in AP","Monthly bank reconciliation","Pre-employment background check","Surprise cash counts","Dual authorization for large payments"],zones:["Preventive Control","Detective Control"],correct:{"Segregation of duties in AP":"Preventive Control","Monthly bank reconciliation":"Detective Control","Pre-employment background check":"Preventive Control","Surprise cash counts":"Detective Control","Dual authorization for large payments":"Preventive Control"},fb:"Preventive: stop errors/fraud BEFORE they occur (segregation, authorization, background checks). Detective: identify errors/fraud AFTER they occur (reconciliations, audits, counts, exception reports). BOTH types are needed \u2014 prevention reduces risk, detection catches what slips through."},{type:"blank",id:"E3Q6",text:"The three elements of the Fraud Triangle are [B1], Opportunity, and [B2]. Removing any one element makes fraud significantly less likely.",blanks:[{id:"B1",opts:["Pressure (Incentive)","Greed","Deception"],ans:"Pressure (Incentive)"},{id:"B2",opts:["Rationalization","Capability","Access"],ans:"Rationalization"}],fb:'Pressure (Incentive): the "why" \u2014 financial stress, greed, lifestyle. Opportunity: the "how" \u2014 weak controls that allow fraud without detection. Rationalization: the "justification" \u2014 why the person convinces themselves it is acceptable. Controls primarily address OPPORTUNITY. Management culture addresses RATIONALIZATION.'}]},{id:"E4",num:4,title:"Control Activities \u2014 BrightStar Corp.",topics:"Segregation of Duties \xB7 Authorization \xB7 Preventive vs Detective \xB7 Physical Controls",case:`BrightStar Corp. is an internal audit client with a manufacturing and retail division. During the annual controls assessment, the internal audit team documented the control environment in the revenue and expenditure cycles.

Management must evaluate whether proper control activities are in place for each function.`,exhibit:{headers:["Function","Current Practice","Risk if Control Absent"],rows:[["Customer credit approval","Sales rep approves AND records credit sales","Fictitious sales, bad debt losses"],["Vendor payments","Controller reviews all payments over $50,000","Unauthorized disbursements"],["Petty cash","One cashier manages fund AND approves requests","Theft of petty cash"],["Inventory access","Warehouse key held only by receiving manager","Theft reduced \u2014 but no second verification"],["Bank reconciliation","Performed monthly by someone who does NOT handle cash","Errors and fraud could go undetected"]]},questions:[{type:"drag",id:"E4Q1",text:"Classify each control by type:",items:["Controller review of payments > $50,000","Monthly bank reconciliation by independent party","Requiring dual signatures on checks > $10,000","Periodic surprise inventory counts","Physical lock on the warehouse"],zones:["Preventive Control","Detective Control"],correct:{"Controller review of payments > $50,000":"Preventive Control","Monthly bank reconciliation by independent party":"Detective Control","Requiring dual signatures on checks > $10,000":"Preventive Control","Periodic surprise inventory counts":"Detective Control","Physical lock on the warehouse":"Preventive Control"},fb:"Preventive: STOP the error/fraud before it happens (authorization, dual signatures, locks). Detective: IDENTIFY errors after they occur (reconciliations, surprise counts, exception reports). Important: No system of controls is perfect \u2014 you need BOTH types. Detective controls are the safety net when preventive controls fail."},{type:"select",id:"E4Q2",text:"The sales rep approving AND recording credit sales violates which fundamental control principle?",opts:["Authorization control \u2014 no approval at all","Segregation of duties \u2014 one person has incompatible functions","Physical control \u2014 no safeguarding of assets","Performance review \u2014 no monitoring of variances"],ans:1,fb:"SEGREGATION OF DUTIES requires separating: (1) Authorization, (2) Custody of assets, and (3) Recordkeeping. When one person has two or more of these functions, they can commit AND conceal errors or fraud. The sales rep both authorizes the credit (creates the transaction) and records it (hides it)."},{type:"select",id:"E4Q3",text:"The bank reconciliation being performed by someone who does NOT handle cash is an example of:",opts:["A detective control AND proper segregation of duties","Only a preventive control \u2014 it stops errors before they happen","A physical control \u2014 protecting assets","An information technology control"],ans:0,fb:"The bank reconciliation is DETECTIVE (finds discrepancies after the fact). The independence of the preparer (someone who doesn't handle cash) is SEGREGATION OF DUTIES \u2014 preventing the same person from handling cash AND hiding discrepancies. This combination (detective + independent) is best practice."},{type:"select",id:"E4Q4",text:"Which of the following is the BEST compensating control for the petty cash weakness (single person manages and approves)?",opts:["Increase the petty cash fund to reduce replenishments","Have the same cashier perform monthly counts","Require a second person to approve petty cash requests AND conduct surprise counts","Post the petty cash policy on the wall"],ans:2,fb:"A COMPENSATING CONTROL addresses a risk when the ideal control (segregation) cannot be fully implemented. Here: requiring a second signature for approvals PLUS surprise counts by management or internal audit reduces the risk that a sole cashier will steal. Compensating controls are acceptable but are generally considered weaker than primary controls."},{type:"drag",id:"E4Q5",text:"Classify each function as compatible (can be combined) or incompatible (must be separated):",items:["Custody of cash AND bank reconciliation","Preparing purchase orders AND approving them","Approving time cards AND distributing paychecks","Recording transactions AND reconciling accounts","Receiving goods AND updating inventory records"],zones:["Incompatible \u2014 Must Separate","Compatible \u2014 Can Combine"],correct:{"Custody of cash AND bank reconciliation":"Incompatible \u2014 Must Separate","Preparing purchase orders AND approving them":"Incompatible \u2014 Must Separate","Approving time cards AND distributing paychecks":"Incompatible \u2014 Must Separate","Recording transactions AND reconciling accounts":"Incompatible \u2014 Must Separate","Receiving goods AND updating inventory records":"Incompatible \u2014 Must Separate"},fb:"All five pairs are INCOMPATIBLE \u2014 each combines two duties that should be separated. The rule: if two functions allow someone to commit AND conceal a fraud or error, they must be separated. In practice, small companies struggle with this and must rely on compensating controls (management review, surprise audits)."},{type:"blank",id:"E4Q6",text:"Segregation of duties separates three incompatible functions: [B1], custody of assets, and [B2].",blanks:[{id:"B1",opts:["Authorization","Monitoring","Reporting"],ans:"Authorization"},{id:"B2",opts:["Recordkeeping","Budgeting","Planning"],ans:"Recordkeeping"}],fb:"The three incompatible functions: AUTHORIZATION (approving transactions), CUSTODY (physical control over assets), RECORDKEEPING (recording in the books). Separating these three prevents one person from initiating, possessing, and concealing a theft or error. This is the cornerstone of internal control over assets."}]},{id:"E5",num:5,title:"SOX Compliance & IT Controls \u2014 PublicCo Corp.",topics:"SOX Sections 302 & 404 \xB7 IT General Controls \xB7 Application Controls",case:`PublicCo Corp. is a publicly traded company preparing its annual SOX compliance assessment. The IT audit team also conducted a review of the IT control environment.

Management must demonstrate understanding of SOX requirements and classify IT control findings correctly.`,exhibit:{headers:["Finding","Area","Detail"],rows:[["SOX 302","Certification","CEO and CFO must certify accuracy of financial statements each quarter"],["SOX 404","ICFR Assessment","Management must assess internal controls over financial reporting annually"],["IT Finding 1","Access Management","User access privileges not reviewed in 12 months \u2014 stale accounts exist"],["IT Finding 2","Change Management","System updates deployed to production without testing or approval"],["IT Finding 3","Input Validation","The accounts payable system accepts negative dollar amounts \u2014 no edit check"],["IT Finding 4","Duplicate Check","No automated control to detect duplicate vendor invoice numbers"]]},questions:[{type:"drag",id:"E5Q1",text:"Classify each IT finding as IT General Control or Application Control:",items:["User access not reviewed \u2014 stale accounts","System updates deployed without approval","AP system accepts negative amounts","No duplicate invoice check"],zones:["IT General Control (ITGC)","Application Control"],correct:{"User access not reviewed \u2014 stale accounts":"IT General Control (ITGC)","System updates deployed without approval":"IT General Control (ITGC)","AP system accepts negative amounts":"Application Control","No duplicate invoice check":"Application Control"},fb:"IT General Controls (ITGCs): govern the overall IT environment \u2014 affect ALL applications. Include: access management, change management, computer operations, data center security. Application Controls: specific to each application/system. Include: input edits, processing controls, output controls. Weak ITGCs undermine ALL application controls \u2014 a key CMA exam point."},{type:"select",id:"E5Q2",text:"Under SOX Section 404, who must assess the effectiveness of Internal Controls over Financial Reporting (ICFR)?",opts:["Only the external auditor","Only the internal audit department","Management \u2014 AND for large accelerated filers, the external auditor also attests","Only the audit committee"],ans:2,fb:"SOX Section 404 requires TWO assessments: (1) MANAGEMENT must assess ICFR effectiveness and include the assessment in the annual report. (2) For large accelerated filers, the EXTERNAL AUDITOR must ATTEST to management's assessment (not just provide an opinion on FS). Non-accelerated filers are exempt from auditor attestation."},{type:"select",id:"E5Q3",text:"A programmed edit check that rejects negative dollar amounts in the AP system is best classified as:",opts:["An IT General Control \u2014 affects all system users","An Application Control \u2014 input validation specific to AP","A physical control \u2014 safeguards company assets","A detective control only \u2014 finds errors after posting"],ans:1,fb:"Input validation is an APPLICATION CONTROL \u2014 specifically an INPUT control. It prevents bad data from entering the system (PREVENTIVE). Application controls are embedded within specific systems/applications to ensure complete, accurate, authorized, and timely processing. Three types: Input, Processing, and Output controls."},{type:"select",id:"E5Q4",text:"Under SOX Section 302, who must certify the accuracy and completeness of financial statements?",opts:["The board of directors and audit committee","The chief accounting officer and controller","The CEO AND CFO","Only the independent external auditor"],ans:2,fb:"SOX Section 302: the CEO AND CFO must personally CERTIFY each quarterly and annual report, confirming: (1) they have reviewed the report, (2) it contains no material misstatements, (3) the financial statements fairly present the company's condition, and (4) they have disclosed all significant IC deficiencies to auditors and the audit committee. Criminal penalties apply for false certifications."},{type:"drag",id:"E5Q5",text:"Match each SOX provision to its requirement:",items:["Section 302","Section 404","Section 409","Audit Committee Independence"],zones:["CEO/CFO certification of FS accuracy","Annual management assessment of ICFR","Real-time disclosure of material events","Board members must be independent; must include financial expert"],correct:{"Section 302":"CEO/CFO certification of FS accuracy","Section 404":"Annual management assessment of ICFR","Section 409":"Real-time disclosure of material events","Audit Committee Independence":"Board members must be independent; must include financial expert"},fb:"SOX key sections: 302 = CEO/CFO sign off on FS. 404 = management assesses ICFR, auditor attests (large filers). 409 = disclose material changes in financial condition or operations in real time (4 business days under SEC rules). Audit committee must be independent and include at least one financial expert."},{type:"blank",id:"E5Q6",text:"IT General Controls affect [B1] applications in the IT environment. Weak ITGCs can [B2] the effectiveness of application controls built on top of them.",blanks:[{id:"B1",opts:["all","only financial","selected"],ans:"all"},{id:"B2",opts:["undermine","strengthen","have no effect on"],ans:"undermine"}],fb:"This is critical for IT audit: ITGCs are the foundation. If access management, change management, or computer operations are weak, ANY application control relying on that system is also unreliable. An auditor finding weak ITGCs must expand testing of ALL applications \u2014 they cannot rely on programmed controls built on a weak infrastructure."}]},{id:"E6",num:6,title:"Risk Assessment Process \u2014 Meridian Financial Group",topics:"COSO Risk Assessment \xB7 Risk Scoring \xB7 Risk Response",case:"Meridian Financial Group is formalizing its COSO-based risk assessment process. The risk team has identified and rated three risks by likelihood (1\u20135 scale) and impact (1\u20135 scale) to prioritize response.",exhibit:{headers:["Risk","Likelihood (1\u20135)","Impact (1\u20135)"],rows:[["Risk A \u2014 Vendor concentration","3","4"],["Risk B \u2014 Currency fluctuation","5","2"],["Risk C \u2014 Regulatory change","2","5"]]},questions:[{type:"calc",id:"E6Q1",text:"Calculate the risk score for Risk A.",hint:"Likelihood \xD7 Impact",exact:12,tol:0,pre:"",suf:"",fb:"Risk A score = 3 \xD7 4 = 12."},{type:"calc",id:"E6Q2",text:"Calculate the risk score for Risk B.",hint:"Likelihood \xD7 Impact",exact:10,tol:0,pre:"",suf:"",fb:"Risk B score = 5 \xD7 2 = 10."},{type:"select",id:"E6Q3",text:"Based on risk score alone, which risk should management prioritize FIRST?",opts:["Risk A (score 12)","Risk B (score 10)","Risk C (score 10)","All three are equal priority"],ans:0,fb:"Risk A has the highest score (12), so it is the top priority for a risk response under a simple likelihood \xD7 impact ranking."},{type:"drag",id:"E6Q4",text:"Match each risk response strategy to its description:",items:["Discontinuing the vendor relationship entirely","Buying insurance to transfer the currency risk","Adding a second control review to reduce error rate","Accepting a low-impact risk with no action"],zones:["Avoid","Share (Transfer)","Reduce","Accept"],correct:{"Discontinuing the vendor relationship entirely":"Avoid","Buying insurance to transfer the currency risk":"Share (Transfer)","Adding a second control review to reduce error rate":"Reduce","Accepting a low-impact risk with no action":"Accept"},fb:"The four classic risk responses are Avoid (eliminate the activity), Reduce (mitigate likelihood/impact), Share/Transfer (insurance, outsourcing), and Accept (no action, usually for low-priority risks)."},{type:"blank",id:"E6Q5",text:"COSOs risk assessment component follows this general sequence: set [B1], identify risks, analyze risks by likelihood and impact, then determine the risk [B2].",blanks:[{id:"B1",opts:["objectives","budgets","audit schedules"],ans:"objectives"},{id:"B2",opts:["response","audit opinion","financial statements"],ans:"response"}],fb:"Risk assessment only makes sense relative to stated objectives; once risks to those objectives are identified and analyzed, management selects a response (avoid, reduce, share, or accept)."},{type:"select",id:"E6Q6",text:"When specifically assessing FRAUD risk (as opposed to general business risk), COSO requires management to additionally consider:",opts:["Only the impact score, never likelihood","The three elements of the fraud triangle: incentive/pressure, opportunity, and rationalization","Only risks identified by external auditors","Risks that have already resulted in a loss"],ans:1,fb:"COSOs Principle 8 specifically calls for considering fraud risk using the fraud triangle \u2014 incentive/pressure, opportunity, and rationalization \u2014 in addition to the general risk assessment process."}]},{id:"E7",num:7,title:"Internal Audit Function & Independence \u2014 Palmetto Industries",topics:"Internal Audit Independence \xB7 IIA Standards \xB7 Assurance vs Consulting",case:"Palmetto Industries is restructuring its internal audit function to strengthen independence. The Chief Audit Executive currently reports administratively to the CFO and is deciding on the appropriate functional reporting line.",exhibit:{headers:["Reporting Line Type","Current / Proposed"],rows:[["Administrative reporting","CFO (day-to-day matters: budget, HR)"],["Functional reporting (proposed)","Audit Committee of the Board"]]},questions:[{type:"select",id:"E7Q1",text:"For maximum independence, internal audit should report FUNCTIONALLY (on audit findings and scope) to:",opts:["The CFO","The CEO","The Audit Committee of the Board","The department being audited"],ans:2,fb:"Functional reporting to the Audit Committee (rather than to management, e.g. the CFO) preserves internal audits independence, since it can then report freely on issues involving senior management."},{type:"select",id:"E7Q2",text:'The distinction between "independence" and "objectivity" for an internal auditor is best described as:',opts:["They mean exactly the same thing","Independence is an organizational/structural condition; objectivity is an individual, unbiased mental attitude","Independence only applies to external auditors","Objectivity is only relevant during fraud investigations"],ans:1,fb:"Independence is freedom from conditions that threaten the internal audit ACTIVITYs ability to act (organizational placement); objectivity is an unbiased mental attitude each INDIVIDUAL auditor must maintain."},{type:"drag",id:"E7Q3",text:"Classify each internal audit engagement type:",items:["Testing controls over the financial close process","Advising management on a new ERP system design","Auditing compliance with a safety regulation","Facilitating a risk workshop at managements request"],zones:["Assurance Engagement","Consulting Engagement"],correct:{"Testing controls over the financial close process":"Assurance Engagement","Advising management on a new ERP system design":"Consulting Engagement","Auditing compliance with a safety regulation":"Assurance Engagement","Facilitating a risk workshop at managements request":"Consulting Engagement"},fb:"Assurance engagements involve the auditors independent assessment of evidence (e.g. testing controls); consulting engagements are advisory in nature and performed at managements specific request."},{type:"blank",id:"E7Q4",text:"The professional framework issued by the [B1] establishes the International Standards that govern internal audit practice worldwide.",blanks:[{id:"B1",opts:["Institute of Internal Auditors (IIA)","Financial Accounting Standards Board (FASB)","Securities and Exchange Commission (SEC)"],ans:"Institute of Internal Auditors (IIA)"}],fb:"The IIA (Institute of Internal Auditors) issues the International Standards for the Professional Practice of Internal Auditing, the primary global framework for the profession."},{type:"select",id:"E7Q5",text:"An internal auditors objectivity would most likely be IMPAIRED if they were asked to:",opts:["Audit a department they have never worked in","Audit the same accounts payable process they personally managed eight months ago","Interview staff as part of a routine control test","Review a policy document before an audit begins"],ans:1,fb:"Auditing an area the person recently managed creates a self-review threat to objectivity \u2014 IIA Standards generally require a cooling-off period before auditing a function one previously operated."},{type:"select",id:"E7Q6",text:"The main difference between internal audit and external (financial statement) audit is that internal audit:",opts:["Is legally required for all public companies while external audit is optional","Primarily serves management and the board across a broad range of risk and control areas, while external audit primarily serves external users by opining on the financial statements","Cannot ever examine financial processes","Reports only to shareholders"],ans:1,fb:"Internal audit has a broad mandate serving the organization itself (operations, compliance, risk, controls); external audit has a narrower statutory purpose \u2014 expressing an opinion on the financial statements for external users."}]},{id:"E8",num:8,title:"Corporate Governance Structures \u2014 Ashford Global Corp",topics:"Board Composition \xB7 Audit Committee \xB7 Fiduciary Duties",case:"Ashford Global Corp, a newly public company, is establishing its board governance structure to comply with exchange listing rules and SOX requirements, including audit committee composition and director duties.",exhibit:{headers:["Governance Item","Requirement/Best Practice"],rows:[["Audit committee independence","Majority (typically all) independent directors"],["Financial expert","At least one member must qualify as a financial expert (SOX)"],["Directors' core fiduciary duties","Duty of Care and Duty of Loyalty"]]},questions:[{type:"select",id:"E8Q1",text:"Listing rules and SOX generally require the audit committee to be composed of:",opts:["A majority of company executives","Independent, non-executive directors","Only the CEO and CFO","External auditors themselves"],ans:1,fb:"To maintain objectivity over financial reporting oversight, audit committees are required to consist of independent, non-executive directors \u2014 free from relationships that could impair judgment."},{type:"select",id:"E8Q2",text:"The fiduciary duty requiring directors to act in good faith, stay informed, and exercise reasonable diligence in decision-making is the:",opts:["Duty of Loyalty","Duty of Care","Duty of Confidentiality","Duty of Disclosure"],ans:1,fb:"The Duty of Care requires directors to make informed, reasonably diligent decisions \u2014 essentially, to act as a reasonably prudent person would in a similar position."},{type:"select",id:"E8Q3",text:"The fiduciary duty requiring directors to avoid conflicts of interest and act in the companys best interest (not their own) is the:",opts:["Duty of Care","Duty of Loyalty","Duty of Competence","Duty of Timeliness"],ans:1,fb:"The Duty of Loyalty requires directors to put the companys interests ahead of personal interests and to avoid or properly disclose conflicts of interest."},{type:"drag",id:"E8Q4",text:"Match each governance stakeholder to their PRIMARY role:",items:["Shareholders","Board of Directors","Executive Management","External Auditors"],zones:["Owners who elect the board","Oversee management on behalf of owners","Run day-to-day operations","Provide independent opinion on financial statements"],correct:{Shareholders:"Owners who elect the board","Board of Directors":"Oversee management on behalf of owners","Executive Management":"Run day-to-day operations","External Auditors":"Provide independent opinion on financial statements"},fb:"Good governance separates ownership (shareholders), oversight (the board), operations (management), and independent verification (external auditors) into distinct roles."},{type:"blank",id:"E8Q5",text:"Under SOX, at least one member of the audit committee must qualify as a [B1], meaning they have the accounting or financial background to understand and challenge complex financial reporting matters.",blanks:[{id:"B1",opts:["financial expert","majority shareholder","internal auditor"],ans:"financial expert"}],fb:'SOX Section 407 requires disclosure of whether the audit committee includes at least one "financial expert," and if not, why not.'},{type:"select",id:"E8Q6",text:"A common governance recommendation to separate the CEO and Board Chairman roles exists mainly to:",opts:["Reduce the companys tax liability","Prevent one individual from having excessive, unchecked control over both management and board oversight","Comply with a universal legal requirement in all countries","Increase executive compensation"],ans:1,fb:"When the same person runs the company AND chairs the board that is supposed to oversee that person, it weakens independent oversight \u2014 separating the roles is a widely recommended (though not universally mandated) governance safeguard."}]},{id:"E9",num:9,title:"Ethics & the IMA Code of Conduct \u2014 Bright Horizon Corp",topics:"IMA Statement of Ethical Professional Practice \xB7 Ethical Conflict Resolution",case:"Sarah, a management accountant at Bright Horizon Corp, is asked by the CEO to record a large customer order as revenue this quarter even though the goods have not yet shipped and the customer has not been billed. Sarah knows this would misstate the quarters results.",exhibit:{headers:["IMA Ethical Principle","Core Idea"],rows:[["Honesty","Be truthful in all professional relationships"],["Fairness","Avoid conflicts of interest and treat all parties fairly"],["Objectivity","Communicate information fairly and without bias"],["Responsibility","Meet professional obligations, comply with laws"]]},questions:[{type:"select",id:"E9Q1",text:"Recording revenue before it is earned, as the CEO requested, would most directly violate the IMA principle of:",opts:["Fairness","Honesty","Confidentiality","Competence"],ans:1,fb:"Honesty requires management accountants to be truthful and avoid misleading financial information \u2014 recording unearned revenue is a direct violation."},{type:"drag",id:"E9Q2",text:"Match each IMA principle to its core idea:",items:["Honesty","Fairness","Objectivity","Responsibility"],zones:["Be truthful in all professional relationships","Avoid conflicts of interest and treat all parties fairly","Communicate information fairly and without bias","Meet professional obligations and comply with laws"],correct:{Honesty:"Be truthful in all professional relationships",Fairness:"Avoid conflicts of interest and treat all parties fairly",Objectivity:"Communicate information fairly and without bias",Responsibility:"Meet professional obligations and comply with laws"},fb:"The IMA Statement of Ethical Professional Practice is built on four core principles: Honesty, Fairness, Objectivity, and Responsibility."},{type:"select",id:"E9Q3",text:"Under the IMA resolution-of-conflict guidance, Sarahs FIRST step should generally be to:",opts:["Report the CEO directly to the SEC","Resign immediately without discussion","Discuss the issue with her immediate supervisor (unless the supervisor is involved, in which case escalate further)","Leak the information to the press"],ans:2,fb:"IMA guidance calls for following the organizations established policy first, typically starting with discussing the concern with an immediate supervisor, and escalating within the organization if that supervisor is implicated."},{type:"select",id:"E9Q4",text:"If Sarah exhausts all reasonable internal resolution channels and the issue remains unresolved, an appropriate next step under IMA guidance is to:",opts:["Immediately contact a national newspaper","Consult IMAs Ethics Helpline for guidance, and consider resigning if the situation cannot be resolved","Falsify the entry as instructed to avoid conflict","Do nothing further, since she already tried once"],ans:1,fb:"IMA guidance points members toward confidential resources like the IMA Ethics Helpline and, as a last resort if the conflict cannot be resolved internally, resignation \u2014 rather than external whistleblowing as the default first response."},{type:"blank",id:"E9Q5",text:"The IMA resolution process generally follows an [B1] escalation \u2014 starting within the organization \u2014 before a management accountant considers [B2] options.",blanks:[{id:"B1",opts:["internal","external","random"],ans:"internal"},{id:"B2",opts:["external","identical","no"],ans:"external"}],fb:"Ethical conflicts should first be escalated within the organizations own reporting structure; external options are a later step if internal resolution fails."},{type:"select",id:"E9Q6",text:"The IMA principle of Confidentiality (closely tied to these four core principles) would be violated if a management accountant:",opts:["Refused an unethical instruction from a supervisor","Disclosed confidential company financial information to a personal acquaintance for their trading advantage","Reported a legitimate concern to the audit committee","Asked a colleague to double-check a calculation"],ans:1,fb:"Confidentiality requires management accountants to keep information confidential except when disclosure is authorized or legally required \u2014 using it for personal or a third partys trading advantage is a clear violation."}]},{id:"E10",num:10,title:"Business Continuity Planning \u2014 Coastal Insurance Group",topics:"Business Impact Analysis \xB7 RTO/RPO \xB7 Disaster Recovery",case:"Coastal Insurance Group is building its business continuity plan (BCP) for its claims-processing system. The Business Impact Analysis determined the system can be down for at most 4 hours before unacceptable losses occur, and backups are taken every 2 hours.",exhibit:{headers:["BCP Metric","Value"],rows:[["Recovery Time Objective (RTO)","4 hours"],["Recovery Point Objective (RPO)","2 hours (backup frequency)"],["Time since last backup when a disruption occurs","90 minutes"]]},questions:[{type:"select",id:"E10Q1",text:"Recovery Time Objective (RTO) is best defined as:",opts:["The maximum acceptable amount of data loss, measured in time","The maximum acceptable length of downtime before unacceptable consequences occur","The exact time a disaster is expected to occur","The cost of the disaster recovery plan"],ans:1,fb:"RTO defines how long a system can be down before the disruption causes unacceptable harm to the business \u2014 it drives how fast recovery must happen."},{type:"select",id:"E10Q2",text:"Recovery Point Objective (RPO) is best defined as:",opts:["The maximum acceptable downtime",'The maximum acceptable amount of data loss, measured as a point in time (e.g. "up to the last backup")',"The physical location of the backup data center","The individual responsible for recovery"],ans:1,fb:"RPO defines how much data the organization can afford to lose, expressed as a time interval \u2014 driving how frequently backups (or replication) must occur."},{type:"select",id:"E10Q3",text:"A disruption occurs 90 minutes after the last backup. Is this within the 2-hour RPO?",opts:["Yes, 90 minutes is within the 2-hour RPO","No, 90 minutes exceeds the 2-hour RPO","RPO does not apply to this scenario","Cannot be determined from the information given"],ans:0,fb:"Since 90 minutes (1.5 hours) is less than the 2-hour RPO, the data loss in this scenario is within the organizations acceptable tolerance."},{type:"select",id:"E10Q4",text:"The FIRST step in developing a business continuity plan is typically to perform a:",opts:["Disaster recovery test","Business Impact Analysis (BIA) to identify critical processes and set RTO/RPO","Employee training session","Insurance policy review"],ans:1,fb:"A Business Impact Analysis identifies which processes are critical and quantifies acceptable downtime (RTO) and data loss (RPO) \u2014 this drives every later BCP decision."},{type:"drag",id:"E10Q5",text:"Match each activity to its BCP lifecycle phase:",items:["Identifying critical processes and setting RTO/RPO","Writing detailed recovery procedures and assigning responsibilities","Running a simulated outage to validate the plan works","Updating the plan after a system change"],zones:["Assessment (BIA)","Planning","Testing","Maintenance"],correct:{"Identifying critical processes and setting RTO/RPO":"Assessment (BIA)","Writing detailed recovery procedures and assigning responsibilities":"Planning","Running a simulated outage to validate the plan works":"Testing","Updating the plan after a system change":"Maintenance"},fb:"A mature BCP program cycles through Assessment (BIA), Planning (documenting procedures), Testing (validating the plan actually works), and ongoing Maintenance as the business changes."},{type:"blank",id:"E10Q6",text:"A plan that is written but never [B1] provides false assurance, since untested recovery procedures often fail when actually needed during a real [B2].",blanks:[{id:"B1",opts:["tested","printed","approved"],ans:"tested"},{id:"B2",opts:["disaster","audit","budget cycle"],ans:"disaster"}],fb:"Regular testing (tabletop exercises, simulated outages) is essential \u2014 an untested BCP frequently reveals gaps only when a real disruption occurs, which is far too late."}]}],F:[{id:"F1",num:1,title:"Data Analytics \u2014 InsightRetail Corp.",topics:"Analytics Types \xB7 Descriptive \xB7 Diagnostic \xB7 Predictive \xB7 Prescriptive \xB7 ROI",case:`InsightRetail Corp. processes 500 invoices with data quality errors every month. Each error costs $50 to investigate and correct. Management is evaluating a data analytics platform costing $120,000 per year that would eliminate these errors AND provide advanced analytical capabilities.

The analytics team must calculate the ROI and match each analytics use case to the correct type.`,exhibit:{headers:["Analytics Type","Question It Answers","Complexity"],rows:[["Descriptive","What HAPPENED?","Low \u2014 baseline"],["Diagnostic","WHY did it happen?","Medium \u2014 root cause"],["Predictive","What WILL happen?","High \u2014 statistical models"],["Prescriptive","What SHOULD we do?","Highest \u2014 optimization"],["Current Use Cases at InsightRetail","Sales reports, trend charts, variance alerts, demand forecasting, pricing optimizer","\u2014"]]},questions:[{type:"calc",id:"F1Q1",text:"Calculate the annual cost of data quality errors BEFORE implementing the analytics platform.",hint:"Annual cost = Errors per month \xD7 12 months \xD7 Cost per error",exact:3e5,tol:0,pre:"$",suf:"",fb:'Annual error cost = 500 \xD7 12 \xD7 $50 = $300,000. Poor data quality is a significant hidden cost \u2014 this is sometimes called the "cost of bad data." Data governance and analytics tools help reduce this waste.'},{type:"calc",id:"F1Q2",text:"Calculate the Net Annual Savings from implementing the analytics platform.",hint:"Net Savings = Annual Error Cost Eliminated \u2212 Annual Platform Cost",exact:18e4,tol:0,pre:"$",suf:"",fb:"Net savings = $300,000 \u2212 $120,000 = $180,000. ROI = $180,000 \xF7 $120,000 = 150%. The platform pays for itself and generates an additional $180,000 in value per year \u2014 before even counting benefits from predictive and prescriptive analytics."},{type:"drag",id:"F1Q3",text:"Match each InsightRetail use case to the correct analytics type:",items:["Monthly sales summary dashboard","Root cause analysis of a sudden sales drop","Demand forecast for next quarter","AI-driven dynamic pricing optimization"],zones:["Descriptive","Diagnostic","Predictive","Prescriptive"],correct:{"Monthly sales summary dashboard":"Descriptive","Root cause analysis of a sudden sales drop":"Diagnostic","Demand forecast for next quarter":"Predictive","AI-driven dynamic pricing optimization":"Prescriptive"},fb:"Descriptive = what happened (reports, dashboards). Diagnostic = why it happened (drill-down, root cause). Predictive = what will happen (regression, ML forecasting). Prescriptive = what SHOULD we do (optimization, decision models). Each builds on the previous \u2014 prescriptive requires a solid foundation of good descriptive and predictive data."},{type:"select",id:"F1Q4",text:"InsightRetail wants to predict which customers are likely to churn in the next 90 days. Which analytics type is this?",opts:["Descriptive \u2014 it summarizes historical churn rates","Diagnostic \u2014 it explains why customers churned in the past","Predictive \u2014 it uses models to forecast future behavior","Prescriptive \u2014 it tells managers which customers to call"],ans:2,fb:'PREDICTIVE analytics uses historical data and statistical/ML models to forecast future events. Predicting which customers will churn = predictive. Deciding WHICH action to take (call them, offer discount) = prescriptive. The line between predictive and prescriptive is: "what will happen" vs "what should we DO about it."'},{type:"select",id:"F1Q5",text:"Which statement about data analytics in management accounting is MOST accurate?",opts:["Analytics only adds value for large corporations with big data","Descriptive analytics alone is sufficient for strategic decision-making","Prescriptive analytics requires clean, reliable data at lower levels before it can function effectively","Predictive analytics eliminates the need for professional judgment"],ans:2,fb:"Data quality is foundational: garbage in, garbage out. Prescriptive and predictive models are only as reliable as the data they are built on. Descriptive analytics must be accurate before diagnostics are meaningful. Analytics AUGMENTS professional judgment \u2014 it does not replace it. Management accountants must critically evaluate model outputs."},{type:"blank",id:"F1Q6",text:"The four types of data analytics in ascending order of complexity and value are: [B1] \u2192 Diagnostic \u2192 [B2] \u2192 Prescriptive.",blanks:[{id:"B1",opts:["Descriptive","Predictive","Comparative"],ans:"Descriptive"},{id:"B2",opts:["Prescriptive","Predictive","Normative"],ans:"Predictive"}],fb:"The analytics maturity ladder: Descriptive (hindsight) \u2192 Diagnostic (insight) \u2192 Predictive (foresight) \u2192 Prescriptive (action). As complexity and data requirements increase, so does business value. Most organizations start with descriptive and gradually build toward prescriptive capabilities."}]},{id:"F2",num:2,title:"Big Data & Data Governance \u2014 MegaData Corp.",topics:"5 Vs of Big Data \xB7 Structured vs Unstructured \xB7 Data Governance",case:`MegaData Corp. processes customer transactions, social media mentions, IoT sensor readings, and supplier emails daily. The CDO (Chief Data Officer) is presenting the Big Data strategy to the board.

The board needs to understand the five dimensions of big data (5 Vs), data classification, and why data governance is essential.`,exhibit:{headers:["Data Source","Daily Volume","Update Frequency","Format"],rows:[["Point-of-sale transactions","2.5 million records","Real-time","Structured (database)"],["Customer social media mentions","850,000 posts","Continuous stream","Unstructured (text/images)"],["IoT warehouse sensors","12 million readings","Every 5 seconds","Semi-structured (JSON)"],["Supplier contracts & emails","3,000 documents","Daily","Unstructured (text/PDF)"],["Financial ledger entries","45,000 records","Daily batch","Structured (database)"]]},questions:[{type:"drag",id:"F2Q1",text:'Match each "V" of Big Data to its correct description:',items:["Volume","Velocity","Variety","Veracity","Value"],zones:["Massive scale of data generated","Speed at which data is created and must be processed","Different formats: structured, semi-structured, unstructured","Accuracy, reliability, and trustworthiness of data","Business benefit extracted from data"],correct:{Volume:"Massive scale of data generated",Velocity:"Speed at which data is created and must be processed",Variety:"Different formats: structured, semi-structured, unstructured",Veracity:"Accuracy, reliability, and trustworthiness of data",Value:"Business benefit extracted from data"},fb:'5 Vs of Big Data: Volume (scale \u2014 terabytes/petabytes), Velocity (speed \u2014 real-time vs batch), Variety (format \u2014 SQL tables, text, images, video), Veracity (quality \u2014 can we trust the data?), Value (the "so what" \u2014 what business decisions can we improve?). Value is the ultimate goal; the first four Vs are challenges to achieving it.'},{type:"drag",id:"F2Q2",text:"Classify each data source as Structured, Semi-structured, or Unstructured:",items:["POS transactions in a SQL database","Customer social media posts","IoT sensor data in JSON format","Supplier contracts in PDF","Financial ledger entries"],zones:["Structured","Semi-structured","Unstructured"],correct:{"POS transactions in a SQL database":"Structured","Customer social media posts":"Unstructured","IoT sensor data in JSON format":"Semi-structured","Supplier contracts in PDF":"Unstructured","Financial ledger entries":"Structured"},fb:"Structured: organized in rows/columns (relational databases) \u2014 easy to query. Semi-structured: has tags or markers (JSON, XML, CSV) \u2014 not in tables but has organization. Unstructured: no predefined format (text, images, video, audio) \u2014 hardest to analyze. 80% of enterprise data is unstructured \u2014 AI/NLP tools are needed to extract value."},{type:"select",id:"F2Q3",text:"IoT sensors updating every 5 seconds present primarily which Big Data challenge?",opts:["Volume \u2014 the sheer number of sensors","Velocity \u2014 data arrives so fast it must be processed in near-real-time","Variety \u2014 sensor data uses unusual formats","Veracity \u2014 sensor readings are often unreliable"],ans:1,fb:"When data arrives continuously and must be processed immediately (streaming analytics), VELOCITY is the primary challenge. Traditional batch processing (run reports overnight) cannot keep pace. Technologies like Apache Kafka and Apache Spark handle high-velocity streaming data. Real-time dashboards and alerts require velocity management."},{type:"select",id:"F2Q4",text:"The PRIMARY purpose of Data Governance in an organization is to:",opts:["Reduce the volume of data collected","Ensure data quality, security, privacy, and accountability through defined policies and ownership","Eliminate the need for data analysts","Convert unstructured data to structured format automatically"],ans:1,fb:"Data Governance = the framework of policies, processes, and responsibilities that ensures data is accurate, consistent, secure, and used appropriately. Key components: data ownership (who is responsible), data quality standards, data privacy (GDPR, HIPAA), data lifecycle management, and access controls. Without governance, organizations cannot trust their analytics outputs."},{type:"select",id:"F2Q5",text:'MegaData Corp. discovers that 12% of customer records have duplicate entries. This is primarily a problem of which Big Data "V"?',opts:["Volume \u2014 too many records to manage","Velocity \u2014 records were entered too quickly","Variety \u2014 customer data has too many formats","Veracity \u2014 data accuracy and reliability is compromised"],ans:3,fb:"VERACITY = data trustworthiness. Duplicates, missing values, inconsistencies, and errors are veracity problems. Poor veracity undermines ALL analytics \u2014 even the most sophisticated AI models produce wrong outputs with bad input data. Data cleansing, deduplication, and master data management address veracity challenges."},{type:"blank",id:"F2Q6",text:"Data that is organized in rows and columns in a relational database is called [B1] data. Data with no predefined structure, such as social media text or emails, is called [B2] data.",blanks:[{id:"B1",opts:["structured","semi-structured","unstructured"],ans:"structured"},{id:"B2",opts:["structured","semi-structured","unstructured"],ans:"unstructured"}],fb:"Structured: SQL databases, spreadsheets \u2014 easy to query and analyze with traditional BI tools. Unstructured: text, images, video, audio \u2014 requires NLP, computer vision, or AI to extract meaning. Semi-structured: JSON, XML, email headers \u2014 has some organization but not relational. The shift to unstructured data is driving AI/ML adoption in analytics."}]},{id:"F3",num:3,title:"Business Intelligence & Dashboards \u2014 ClearVision Corp.",topics:"BI \xB7 OLAP vs OLTP \xB7 Data Warehouse \xB7 KPI Dashboards",case:`ClearVision Corp. is implementing a Business Intelligence (BI) platform. The CFO wants an executive dashboard and the IT team must choose the right database architecture.

The analytics team must distinguish between operational systems and analytical systems, and design effective dashboards for different audiences.`,exhibit:{headers:["System / Feature","Description"],rows:[["OLTP System","Processes daily transactions \u2014 sales, inventory, AP, AR"],["Data Warehouse","Integrated historical data from multiple sources for analysis"],["OLAP Cube","Multi-dimensional analysis with drill-down, slice, dice capabilities"],["Executive Dashboard","High-level KPIs \u2014 updated daily"],["Operational Dashboard","Real-time metrics for day-to-day decisions"],["Data Mart","Subject-specific subset of data warehouse (e.g., Sales mart, Finance mart)"]]},questions:[{type:"drag",id:"F3Q1",text:"Match each use case to the correct system:",items:["Record a customer sale in real time","Analyze 5 years of sales trends by region and product","View today's production output vs. target","Generate quarterly financial statements for the board"],zones:["OLTP \u2014 Operational System","OLAP / Data Warehouse \u2014 Analytical System"],correct:{"Record a customer sale in real time":"OLTP \u2014 Operational System","Analyze 5 years of sales trends by region and product":"OLAP / Data Warehouse \u2014 Analytical System","View today's production output vs. target":"OLTP \u2014 Operational System","Generate quarterly financial statements for the board":"OLAP / Data Warehouse \u2014 Analytical System"},fb:"OLTP (Online Transaction Processing): real-time, row-level, many small transactions, normalized database, current data. OLAP (Online Analytical Processing): historical, aggregated, complex queries, denormalized/star schema, supports drill-down. A Data Warehouse integrates OLTP data from multiple sources to enable OLAP analysis."},{type:"select",id:"F3Q2",text:'A manager "drills down" from total company revenue to individual store revenue, then to product category. This is a feature of which system?',opts:["OLTP \u2014 it handles all transaction-level queries","Data entry system \u2014 for recording real-time events","OLAP \u2014 multi-dimensional analysis with drill-down capability","ERP \u2014 enterprise resource planning module"],ans:2,fb:"OLAP supports: Drill-down (go from summary to detail), Roll-up (go from detail to summary), Slice (filter one dimension \u2014 show only Q3), Dice (filter multiple dimensions \u2014 Q3 + North Region + Electronics). These multi-dimensional views require a pre-aggregated, denormalized data structure \u2014 not possible efficiently in OLTP systems."},{type:"drag",id:"F3Q3",text:"Match each chart type to its BEST use case:",items:["Bar / Column Chart","Line Chart","Pie / Donut Chart","Scatter Plot","Heat Map"],zones:["Compare categories at a point in time","Show trends over time","Show proportions of a whole","Show correlation between two variables","Show intensity across a matrix (e.g., risk grid)"],correct:{"Bar / Column Chart":"Compare categories at a point in time","Line Chart":"Show trends over time","Pie / Donut Chart":"Show proportions of a whole","Scatter Plot":"Show correlation between two variables","Heat Map":"Show intensity across a matrix (e.g., risk grid)"},fb:"Choosing the right visualization is critical for clear communication. Common mistakes: using pie charts with too many slices, using bar charts for trend data (line is better), using 3D charts that distort data. The rule: choose the chart type that makes the insight IMMEDIATELY obvious to the audience."},{type:"select",id:"F3Q4",text:"Which statement about a Data Warehouse is MOST accurate?",opts:["It replaces OLTP systems for all transaction processing","It stores only current-period data to keep queries fast","It integrates historical data from multiple source systems for analytical querying","It is the same as a database used for daily operations"],ans:2,fb:"Data Warehouse: integrates data from ERP, CRM, HRM, and other sources into a single analytical repository. Characteristics: subject-oriented, integrated, time-variant (historical), non-volatile (data not updated after loading). ETL (Extract, Transform, Load) is used to populate it. Data Marts are smaller, subject-specific subsets."},{type:"select",id:"F3Q5",text:"An executive dashboard shows Revenue, Gross Margin, and Customer Satisfaction trending below target with red indicators. These are examples of:",opts:["Operational metrics only \u2014 not suitable for executive view","Key Performance Indicators (KPIs) \u2014 strategic measures linked to organizational objectives","Raw data feeds \u2014 should be in the data warehouse","Diagnostic analytics outputs \u2014 explain why targets were missed"],ans:1,fb:"KPIs = Key Performance Indicators. They are strategic measures that reflect progress toward organizational goals. Effective KPIs are: specific, measurable, achievable, relevant, time-bound (SMART). Dashboard design: strategic KPIs for executives (high-level), operational metrics for managers (more detail), transactional data for staff."},{type:"blank",id:"F3Q6",text:"OLTP systems are optimized for [B1] transactions in real time. Data warehouses are optimized for [B2] queries across large historical datasets.",blanks:[{id:"B1",opts:["processing small","running complex","aggregating"],ans:"processing small"},{id:"B2",opts:["complex analytical","real-time transactional","batch entry"],ans:"complex analytical"}],fb:"OLTP: many users, small transactions, normalized schema (reduces redundancy), optimized for INSERT/UPDATE speed. Data Warehouse: few users, complex queries, denormalized/star schema (faster reads), optimized for SELECT aggregation speed. This fundamental difference drives the ETL process \u2014 transforming OLTP data into a warehouse-friendly format."}]},{id:"F4",num:4,title:"Cloud Computing & ERP \u2014 TechManufacturing Inc.",topics:"IaaS \xB7 PaaS \xB7 SaaS \xB7 TCO Analysis \xB7 Cloud Migration",case:`TechManufacturing Inc. is evaluating whether to replace their on-premise ERP system with a cloud-based SaaS solution. The CFO has compiled a 3-year Total Cost of Ownership (TCO) comparison.

The IT team must also classify cloud service models and understand the risk and control implications of each.`,exhibit:{headers:["Cost Item","On-Premise Year 1","On-Premise Year 2\u20133 (each)","Cloud Year 1","Cloud Year 2\u20133 (each)"],rows:[["Software License / Subscription","$300,000","$0","$0","$0"],["Implementation / Migration","$80,000","$0","$60,000","$0"],["Annual Maintenance (15% of license)","$0","$60,000","$0","$0"],["Annual Subscription Fee","$0","$0","$0","$120,000"],["IT Infrastructure & Staff","$40,000","$20,000","$0","$0"],["Vendor Support & Updates","$0","$0","$100,000","$10,000"],["Year Total","$420,000","$80,000","$160,000","$130,000"]]},questions:[{type:"calc",id:"F4Q1",text:"Calculate the 3-Year Total Cost of Ownership for the On-Premise solution.",hint:"TCO = Year 1 + Year 2 + Year 3",exact:58e4,tol:0,pre:"$",suf:"",fb:"On-Premise 3yr TCO = $420,000 + $80,000 + $80,000 = $580,000. On-premise has high upfront costs (license + hardware) but lower annual costs in years 2+. The large Year 1 investment creates a long payback period."},{type:"calc",id:"F4Q2",text:"Calculate the 3-Year Total Cost of Ownership for the Cloud solution.",hint:"TCO = Year 1 + Year 2 + Year 3",exact:42e4,tol:0,pre:"$",suf:"",fb:"Cloud 3yr TCO = $160,000 + $130,000 + $130,000 = $420,000. Cloud has lower upfront cost (no license) and predictable annual subscription fees \u2014 converting capital expenditure (CapEx) to operating expenditure (OpEx). This improves cash flow in Year 1 significantly."},{type:"calc",id:"F4Q3",text:"What are the total 3-year cost savings of choosing Cloud over On-Premise?",hint:"Savings = On-Premise TCO \u2212 Cloud TCO",exact:16e4,tol:0,pre:"$",suf:"",fb:"Cloud savings = $580,000 \u2212 $420,000 = $160,000 over 3 years. Note: the cloud ALSO saves $260,000 in Year 1 alone ($420K vs $160K) \u2014 critical for cash flow. However, in years 4+ the on-premise may become cheaper since license is already paid \u2014 the long-term analysis is important."},{type:"drag",id:"F4Q4",text:"Match each cloud service model to its correct description:",items:["IaaS (Infrastructure as a Service)","PaaS (Platform as a Service)","SaaS (Software as a Service)"],zones:["Rent virtual servers, storage, networking \u2014 manage your own OS and applications","Rent development platform \u2014 build and deploy your own applications","Rent complete software application \u2014 provider manages everything"],correct:{"IaaS (Infrastructure as a Service)":"Rent virtual servers, storage, networking \u2014 manage your own OS and applications","PaaS (Platform as a Service)":"Rent development platform \u2014 build and deploy your own applications","SaaS (Software as a Service)":"Rent complete software application \u2014 provider manages everything"},fb:"IaaS: most control, most responsibility (AWS EC2, Azure VMs). PaaS: middle ground \u2014 build apps without managing servers (AWS Elastic Beanstalk, Heroku). SaaS: least control, least responsibility \u2014 fully managed (Salesforce, SAP ByDesign, Microsoft 365). Cloud ERP is typically SaaS \u2014 the vendor handles upgrades, security patches, and infrastructure."},{type:"select",id:"F4Q5",text:"Which cloud model gives the organization the MOST control over the computing environment?",opts:["SaaS \u2014 the vendor manages everything","PaaS \u2014 developer controls the application code","IaaS \u2014 the organization controls OS, middleware, and applications","All three models provide equal control"],ans:2,fb:"IaaS provides the most control: you manage OS, runtime, middleware, and applications. The vendor only manages the physical hardware and virtualization. SaaS is the opposite \u2014 you control only data and user configuration. The more control \u2192 more responsibility for security and maintenance. Organizations with compliance requirements (banking, healthcare) often prefer IaaS for sensitive workloads."},{type:"blank",id:"F4Q6",text:"Cloud computing converts capital expenditure (CapEx) to [B1] expenditure (OpEx). A key risk of SaaS is [B2] on the vendor for data access, uptime, and security.",blanks:[{id:"B1",opts:["operating","investing","financing"],ans:"operating"},{id:"B2",opts:["vendor lock-in and dependency","complete independence","elimination of risk"],ans:"vendor lock-in and dependency"}],fb:"CapEx \u2192 OpEx conversion is a major cloud benefit: no large upfront investment, subscription is expensed immediately, improves balance sheet (no large asset). Key SaaS risks: vendor lock-in (hard to migrate data), data security (data leaves your premises), internet dependency (outage = no access), and reduced customization. Organizations must assess these trade-offs carefully."}]},{id:"F5",num:5,title:"Emerging Technologies \u2014 FinanceForward Inc.",topics:"RPA \xB7 Artificial Intelligence \xB7 Blockchain \xB7 Technology Selection",case:`FinanceForward Inc. is a finance transformation team evaluating three emerging technologies to automate and improve finance operations: Robotic Process Automation (RPA), Artificial Intelligence / Machine Learning (AI/ML), and Blockchain.

The team must match each technology to the right finance use case and understand the implications for internal controls.`,exhibit:{headers:["Technology","Core Capability","Key Characteristic"],rows:[["RPA (Robotic Process Automation)","Automates repetitive, rule-based digital tasks","Follows EXACT rules \u2014 no learning or judgment"],["AI / Machine Learning","Learns patterns from data \u2014 improves over time","Handles unstructured data, exceptions, predictions"],["Blockchain","Distributed, immutable ledger shared across a network","Decentralized, transparent, tamper-proof records"],["Smart Contracts","Self-executing contracts coded on blockchain","Automatic execution when predefined conditions are met"],["Natural Language Processing (NLP)","AI subfield: understands and generates human language","Text analysis, chatbots, document extraction"]]},questions:[{type:"drag",id:"F5Q1",text:"Match each finance task to the BEST technology:",items:["Automatically reconcile 10,000 bank transactions daily using fixed matching rules","Detect unusual journal entries that deviate from normal patterns (fraud detection)","Record an asset transfer on a shared ledger visible to all parties simultaneously","Automatically pay a supplier when goods receipt is confirmed in the system"],zones:["RPA","AI / Machine Learning","Blockchain","Smart Contract"],correct:{"Automatically reconcile 10,000 bank transactions daily using fixed matching rules":"RPA","Detect unusual journal entries that deviate from normal patterns (fraud detection)":"AI / Machine Learning","Record an asset transfer on a shared ledger visible to all parties simultaneously":"Blockchain","Automatically pay a supplier when goods receipt is confirmed in the system":"Smart Contract"},fb:"RPA: rule-based repetitive tasks (reconciliation, data entry, report generation). AI/ML: pattern recognition, anomaly detection, prediction \u2014 learns from data. Blockchain: shared trusted ledger for multi-party transactions. Smart Contracts: self-executing on blockchain when conditions are met (goods received \u2192 payment released automatically)."},{type:"select",id:"F5Q2",text:"Which finance process is MOST suitable for RPA implementation?",opts:["Evaluating the creditworthiness of a new customer (requires judgment)","Extracting invoice data from unstructured vendor emails","Matching purchase orders to invoices to goods receipts (3-way match) using predefined rules","Predicting which accounts receivable will become uncollectible"],ans:2,fb:"RPA works best for: high-volume, repetitive, rule-based, digital processes with structured data. 3-way PO matching = perfect RPA candidate. Creditworthiness requires judgment \u2192 AI or human. Extracting from unstructured emails \u2192 NLP (AI). Predicting bad debts \u2192 ML. RPA does NOT learn or adapt \u2014 if the rule changes, the bot must be reprogrammed."},{type:"select",id:"F5Q3",text:"A blockchain record that has already been confirmed CANNOT be altered. This property is called:",opts:["Decentralization \u2014 no single point of control","Immutability \u2014 records cannot be changed once added to the chain","Transparency \u2014 all participants can view all transactions","Consensus \u2014 all nodes must agree before adding a record"],ans:1,fb:"IMMUTABILITY is the defining feature of blockchain for audit and control purposes. Once a block is added and confirmed, changing it would require altering every subsequent block AND achieving consensus from 51%+ of the network \u2014 computationally infeasible. This makes blockchain ideal for audit trails, supply chain provenance, and financial settlement."},{type:"select",id:"F5Q4",text:"An AI model trained on 3 years of expense reports flags a new expense claim as suspicious because it deviates from the employee's historical patterns. This is an example of:",opts:["RPA \u2014 following a programmed rule to flag exceptions","Descriptive analytics \u2014 summarizing past expense patterns","Machine Learning \u2014 the model learned patterns from historical data to detect anomalies","Blockchain \u2014 recording the expense on an immutable ledger"],ans:2,fb:'This is MACHINE LEARNING (anomaly detection). The model was trained on historical data and LEARNED what "normal" looks like for each employee. It can flag deviations without being explicitly programmed with rules for every possible fraud scenario. This is a key differentiator from RPA \u2014 ML can handle complexity and novel patterns that rules cannot anticipate.'},{type:"drag",id:"F5Q5",text:"Classify each statement as describing RPA or AI/Machine Learning:",items:["Follows exact rules \u2014 fails if data format changes","Improves accuracy the more data it processes","Cannot handle unstructured data (images, emails)","Can detect patterns humans cannot see in large datasets","Best for high-volume, stable, well-defined processes"],zones:["RPA","AI / Machine Learning"],correct:{"Follows exact rules \u2014 fails if data format changes":"RPA","Improves accuracy the more data it processes":"AI / Machine Learning","Cannot handle unstructured data (images, emails)":"RPA","Can detect patterns humans cannot see in large datasets":"AI / Machine Learning","Best for high-volume, stable, well-defined processes":"RPA"},fb:'RPA = automation without intelligence. It does exactly what it is programmed to do \u2014 efficiently and tirelessly \u2014 but breaks when inputs change. AI/ML = automation WITH intelligence. It learns, adapts, and improves. Together they are powerful: RPA handles structured automation, AI handles exceptions and complexity. "Intelligent Automation" combines both.'},{type:"blank",id:"F5Q6",text:"RPA automates [B1], rule-based tasks and cannot handle exceptions or learn. AI/ML learns from [B2] and improves performance over time as more data is available.",blanks:[{id:"B1",opts:["repetitive structured","creative complex","strategic"],ans:"repetitive structured"},{id:"B2",opts:["historical data and patterns","programmed rules","human instructions only"],ans:"historical data and patterns"}],fb:"CMA exam summary: RPA = digital worker following rules (reconciliation, data entry, report distribution). AI/ML = pattern recognition, prediction, anomaly detection (fraud, forecasting, credit risk). Blockchain = immutable shared ledger (supply chain, asset transfers, smart contracts). NLP = text understanding (invoice extraction, contract review, chatbots). Finance professionals must understand when each applies."}]},{id:"F6",num:6,title:"ERP Architecture & Module Selection \u2014 Meridian Industrial Group",topics:"ERP Modules \xB7 System Integration \xB7 Implementation Risk",case:"Meridian Industrial Group is replacing several standalone legacy systems (separate payroll, inventory, and order-entry software) with a single integrated ERP system.",exhibit:{headers:["Legacy System","Function"],rows:[["Standalone payroll software","Employee pay processing"],["Standalone inventory system","Stock tracking"],["Standalone order-entry system","Sales order processing"]]},questions:[{type:"select",id:"F6Q1",text:"The main advantage of replacing these standalone systems with an integrated ERP is:",opts:["ERP systems are always cheaper to purchase upfront","A single, shared database eliminates data silos and duplicate/inconsistent data entry","ERP systems require no employee training","ERP eliminates the need for internal controls"],ans:1,fb:"ERPs core value is integration: all modules share one database, so data entered once (e.g. a sales order) automatically flows to inventory, finance, and other modules \u2014 eliminating silos and reconciliation problems."},{type:"drag",id:"F6Q2",text:"Match each business function to the ERP module that would typically handle it:",items:["Processing employee pay and benefits","Managing the order-to-cash cycle","Planning raw material purchases based on production needs","Consolidating financial statements"],zones:["Human Resources (HR) Module","Sales/CRM Module","Manufacturing/SCM Module","Finance/Accounting Module"],correct:{"Processing employee pay and benefits":"Human Resources (HR) Module","Managing the order-to-cash cycle":"Sales/CRM Module","Planning raw material purchases based on production needs":"Manufacturing/SCM Module","Consolidating financial statements":"Finance/Accounting Module"},fb:"Modern ERP suites are organized into modules by business function, all built on the same underlying database so they can share data seamlessly."},{type:"select",id:"F6Q3",text:"The MAIN risk that typically drives ERP implementations over budget and behind schedule is:",opts:["Insufficient office space","Excessive customization and scope creep during implementation","Too few software vendors in the market","Currency exchange rate fluctuation"],ans:1,fb:"Heavy customization to match every existing business process (rather than adapting processes to the ERPs standard functionality) is one of the most common causes of ERP cost and schedule overruns."},{type:"select",id:"F6Q4",text:'A "best of breed" software strategy, as an alternative to a single-vendor ERP, means:',opts:["Buying the cheapest software available regardless of fit","Selecting the top specialized system for each function and integrating them, versus buying one unified suite","Only using open-source software","Avoiding all cloud-based systems"],ans:1,fb:"Best-of-breed means choosing the leading specialized application for each function (e.g. best CRM, best WMS) and integrating them, trading deeper functionality per module for more integration complexity than a single-vendor ERP."},{type:"blank",id:"F6Q5",text:"A typical ERP implementation moves through [B1] (requirements and configuration), data migration, testing, and finally [B2] (go-live), followed by ongoing support.",blanks:[{id:"B1",opts:["design/configuration","disposal","audit"],ans:"design/configuration"},{id:"B2",opts:["deployment","budgeting","recruiting"],ans:"deployment"}],fb:"A standard ERP rollout progresses from design/configuration through data migration and testing to deployment (go-live) and post-implementation support."},{type:"select",id:"F6Q6",text:'The concept of a "single source of truth" in an ERP context refers to:',opts:["One employee who approves all transactions","One shared, authoritative dataset that all modules and users reference, avoiding conflicting versions of the same data","A single backup server","One vendor providing all IT support"],ans:1,fb:"Because ERP modules share one database, everyone across the organization works from the same authoritative data \u2014 eliminating the conflicting numbers that arise when separate systems each keep their own copy."}]},{id:"F7",num:7,title:"Cybersecurity Risk Management \u2014 DataVault Financial Services",topics:"NIST Cybersecurity Framework \xB7 Preventive/Detective Controls \xB7 Phishing Risk",case:"DataVault Financial Services recently experienced a phishing email that led one employee to enter their credentials on a fake login page. The security team is reviewing the incident using the NIST Cybersecurity Framework functions: Identify, Protect, Detect, Respond, Recover.",exhibit:{headers:["NIST Function","Purpose"],rows:[["Identify","Understand assets and risks"],["Protect","Implement safeguards (firewalls, access controls, training)"],["Detect","Identify a cybersecurity event as it happens"],["Respond","Contain and mitigate an active incident"],["Recover","Restore normal operations after an incident"]]},questions:[{type:"select",id:"F7Q1",text:"Firewalls, access controls, and employee security-awareness training primarily fall under which NIST function?",opts:["Identify","Protect","Detect","Respond"],ans:1,fb:"The Protect function covers safeguards implemented BEFORE an incident \u2014 access controls, firewalls, training \u2014 designed to prevent or limit the impact of an attack."},{type:"select",id:"F7Q2",text:"An intrusion detection system that flags unusual login activity primarily supports which NIST function?",opts:["Protect","Detect","Recover","Identify"],ans:1,fb:"The Detect function covers the timely discovery of cybersecurity events as they occur \u2014 intrusion detection and monitoring systems are core Detect tools."},{type:"drag",id:"F7Q3",text:"Classify each control by its type:",items:["A firewall blocking unauthorized network traffic","An intrusion detection alert on unusual login activity","Restoring data from backup after a ransomware attack","Employee security-awareness training"],zones:["Preventive Control","Detective Control","Corrective Control"],correct:{"A firewall blocking unauthorized network traffic":"Preventive Control","An intrusion detection alert on unusual login activity":"Detective Control","Restoring data from backup after a ransomware attack":"Corrective Control","Employee security-awareness training":"Preventive Control"},fb:"Preventive controls stop an incident before it happens, detective controls identify one in progress or after the fact, and corrective controls fix the damage once an incident has occurred."},{type:"select",id:"F7Q4",text:"The primary danger of a successful phishing attack, as in this case, is that it:",opts:["Always destroys physical hardware","Can lead to stolen credentials that give an attacker unauthorized access to systems and data","Only affects the employees personal email, never company systems","Cannot be prevented through any control"],ans:1,fb:"Phishing is primarily a credential-theft vector: once an attacker has valid login credentials, they can access systems as if they were the legitimate user, bypassing many perimeter defenses."},{type:"blank",id:"F7Q5",text:"The NIST Cybersecurity Framework organizes activity into five functions: Identify, Protect, [B1], Respond, and [B2].",blanks:[{id:"B1",opts:["Detect","Delete","Disclose"],ans:"Detect"},{id:"B2",opts:["Recover","Report","Retire"],ans:"Recover"}],fb:"The five NIST CSF functions are Identify, Protect, Detect, Respond, and Recover \u2014 covering the full incident lifecycle from preparation through restoration."},{type:"select",id:"F7Q6",text:"Requiring multi-factor authentication (MFA) reduces the risk from a successful phishing attack primarily because:",opts:["It prevents all phishing emails from being sent","A stolen password alone is no longer sufficient to access the account without the second factor","It eliminates the need for firewalls","It automatically deletes phishing emails"],ans:1,fb:"MFA means a compromised password is not enough on its own \u2014 the attacker would also need the second factor (e.g. a one-time code), which significantly reduces the impact of credential theft from phishing."}]},{id:"F8",num:8,title:"Systems Development Life Cycle \u2014 Continental Software Solutions",topics:"SDLC Phases \xB7 User Acceptance Testing \xB7 Waterfall vs Agile",case:"Continental Software Solutions is building a new in-house financial reporting system. The project manager is walking the finance team through the systems development life cycle before development begins.",exhibit:{headers:["SDLC Phase","Key Activity"],rows:[["Planning","Define scope, feasibility, budget"],["Analysis","Gather and document requirements"],["Design","Design system architecture and screens"],["Development","Write and build the system"],["Testing","Verify the system works correctly, including User Acceptance Testing"],["Implementation","Deploy the system (go-live)"],["Maintenance","Ongoing support and updates"]]},questions:[{type:"drag",id:"F8Q1",text:"Match each activity to its correct SDLC phase:",items:["Gathering detailed requirements from finance users","Designing the database schema and screen layouts","Writing the actual program code","Deploying the finished system to all users"],zones:["Analysis","Design","Development","Implementation"],correct:{"Gathering detailed requirements from finance users":"Analysis","Designing the database schema and screen layouts":"Design","Writing the actual program code":"Development","Deploying the finished system to all users":"Implementation"},fb:"The traditional (waterfall) SDLC moves sequentially: Planning, Analysis (requirements), Design, Development (build), Testing, Implementation (go-live), then Maintenance."},{type:"select",id:"F8Q2",text:"The purpose of User Acceptance Testing (UAT) is to:",opts:["Test whether the code compiles without errors","Confirm that actual business users can use the system to perform their real-world tasks correctly before go-live","Replace the need for any other testing","Train the IT help desk staff"],ans:1,fb:"UAT is performed by the actual business users (not just IT) to confirm the system meets their real needs and works correctly in realistic scenarios before it goes live."},{type:"select",id:"F8Q3",text:"The main risk of skipping or rushing the testing phase is:",opts:["The project will finish too early","Defects and control weaknesses go undetected until after go-live, when they are far more costly and disruptive to fix","Users will be too well trained","Nothing \u2014 testing is optional for financial systems"],ans:1,fb:"Defects caught before go-live are far cheaper and less disruptive to fix than the same defects discovered in production, especially in a financial reporting system where errors can affect reported results."},{type:"blank",id:"F8Q4",text:"Maintaining a documented history of code changes through [B1] helps ensure that if a new version introduces a defect, the team can [B2] to the last known-good version.",blanks:[{id:"B1",opts:["version control","marketing plans","payroll records"],ans:"version control"},{id:"B2",opts:["roll back","permanently delete data","ignore the issue"],ans:"roll back"}],fb:"Version control tracks every change to the codebase, enabling a team to roll back to a prior stable version quickly if a new release introduces a defect."},{type:"select",id:"F8Q5",text:"Compared to traditional Waterfall, an Agile SDLC approach is characterized by:",opts:["A single, fixed sequential phase with no revisiting earlier steps","Short, iterative cycles (sprints) that deliver working functionality incrementally and adapt to changing requirements","Never involving business users until the very end of the project","Eliminating the need for any testing"],ans:1,fb:"Agile breaks the project into short iterative sprints, delivering working increments of the system and incorporating feedback continuously, rather than committing to one long sequential Waterfall path."},{type:"select",id:"F8Q6",text:"For a financial reporting system specifically, a strong reason to favor rigorous testing (regardless of SDLC methodology) is that:",opts:["Testing has no bearing on internal control assessments","Undetected system errors could directly cause material misstatements in the financial statements","Testing is only relevant for consumer mobile apps","Auditors never review IT change management"],ans:1,fb:"A financial reporting system is directly tied to the accuracy of reported results \u2014 undetected calculation or logic errors can cause material misstatements, making thorough testing and change management a key internal control."}]},{id:"F9",num:9,title:"Data Privacy & Regulatory Compliance \u2014 GlobalTech Consumer Products",topics:"GDPR \xB7 Data Minimization \xB7 Right to Erasure \xB7 Breach Notification",case:"GlobalTech Consumer Products sells to customers across the EU and must comply with GDPR. The privacy team is training staff on core requirements after a recent data handling review.",exhibit:{headers:["GDPR Concept","Requirement"],rows:[["Breach notification","Notify the supervisory authority within 72 hours of becoming aware"],["Data minimization","Collect only data necessary for the stated purpose"],["Right to erasure",'Individuals can request deletion of their personal data ("right to be forgotten")']]},questions:[{type:"select",id:"F9Q1",text:"Under GDPR, a company that discovers a personal data breach must generally notify the supervisory authority within:",opts:["24 hours","72 hours","30 days","1 year"],ans:1,fb:"GDPR requires notifying the relevant supervisory authority without undue delay, and where feasible, within 72 hours of becoming aware of the breach."},{type:"select",id:"F9Q2",text:'The GDPR principle requiring a company to collect ONLY the personal data necessary for its stated purpose (nothing extra "just in case") is called:',opts:["Data minimization","Data maximization","Purpose expansion","Storage limitation"],ans:0,fb:'Data minimization requires that personal data collected be adequate, relevant, and limited to what is necessary for the specified purpose \u2014 collecting extra "just in case" data violates this principle.'},{type:"select",id:"F9Q3",text:"The GDPR right allowing an individual to request that a company delete their personal data is known as:",opts:["The right to portability","The right to erasure (right to be forgotten)","The right to rectification","The right to restrict processing"],ans:1,fb:'The right to erasure, commonly called the "right to be forgotten," lets individuals request deletion of their personal data under certain conditions.'},{type:"drag",id:"F9Q4",text:"Match each GDPR term to its definition:",items:["Consent","Data controller","Data processor","Personal data"],zones:["Freely given, specific, informed agreement to processing","The entity that determines why/how data is processed","The entity that processes data on the controllers behalf","Any information relating to an identifiable individual"],correct:{Consent:"Freely given, specific, informed agreement to processing","Data controller":"The entity that determines why/how data is processed","Data processor":"The entity that processes data on the controllers behalf","Personal data":"Any information relating to an identifiable individual"},fb:"GDPR defines precise roles and terms: the controller decides the purpose of processing, the processor acts on the controllers instructions, consent must be freely given and specific, and personal data covers any identifiable individuals information."},{type:"blank",id:"F9Q5",text:"Under GDPR, consent to process personal data must be [B1] given, specific, and informed \u2014 pre-checked boxes or bundled consent generally do [B2] qualify.",blanks:[{id:"B1",opts:["freely","forcibly","automatically"],ans:"freely"},{id:"B2",opts:["not","always","only sometimes"],ans:"not"}],fb:"GDPR sets a high bar for valid consent: it must be freely given, specific, and clearly affirmative \u2014 pre-ticked boxes or consent bundled into unrelated terms do not meet this standard."},{type:"select",id:"F9Q6",text:"A key consequence of GDPR non-compliance is that regulators can impose fines of up to:",opts:["A small fixed fee regardless of company size","A significant percentage of the companys global annual revenue","Only a formal warning letter, with no financial penalty","Fines that apply only to companies physically located in the EU"],ans:1,fb:"GDPR allows fines of up to 4% of global annual revenue (or a fixed maximum, whichever is higher) for the most serious violations \u2014 making compliance a material financial risk, not just a legal formality."}]},{id:"F10",num:10,title:"IT Audit & Governance Frameworks \u2014 Apex Financial Technologies",topics:"COBIT \xB7 ITIL \xB7 ISO 27001 \xB7 CIA Triad",case:"Apex Financial Technologies is selecting frameworks to strengthen its IT governance, service management, and information security practices, and is training its IT audit team on the CIA triad of security objectives.",exhibit:{headers:["Framework","Primary Focus"],rows:[["COBIT","IT governance and control objectives, aligning IT with business goals"],["ITIL","IT service management best practices (incident, change, problem management)"],["ISO 27001","Information security management system (ISMS) standard"]]},questions:[{type:"select",id:"F10Q1",text:"Which framework primarily addresses overall IT GOVERNANCE and control objectives, aligning IT investment with business strategy?",opts:["ITIL","COBIT","ISO 27001","GDPR"],ans:1,fb:"COBIT (Control Objectives for Information and Related Technologies) is the leading framework for IT governance, focused on aligning IT processes and controls with business objectives."},{type:"select",id:"F10Q2",text:"Which framework focuses specifically on IT SERVICE MANAGEMENT best practices, such as incident and change management?",opts:["COBIT","ITIL","COSO","ISO 27001"],ans:1,fb:"ITIL (Information Technology Infrastructure Library) provides best-practice guidance for delivering and managing IT services, including incident, problem, and change management processes."},{type:"select",id:"F10Q3",text:"Which standard focuses specifically on establishing an Information Security Management System (ISMS)?",opts:["ITIL","COBIT","ISO 27001","SDLC"],ans:2,fb:"ISO 27001 is the international standard for establishing, implementing, and continually improving an organizations information security management system."},{type:"drag",id:"F10Q4",text:"Match each element of the CIA triad to its definition:",items:["Confidentiality","Integrity","Availability"],zones:["Information is accessible only to those authorized to see it","Information is accurate and has not been improperly altered","Information and systems are accessible when needed by authorized users"],correct:{Confidentiality:"Information is accessible only to those authorized to see it",Integrity:"Information is accurate and has not been improperly altered",Availability:"Information and systems are accessible when needed by authorized users"},fb:"The CIA triad \u2014 Confidentiality, Integrity, and Availability \u2014 defines the three core objectives that virtually all information security controls aim to protect."},{type:"blank",id:"F10Q5",text:"IT audit objectives generally center on evaluating whether systems and data maintain [B1], integrity, and [B2] \u2014 the three pillars of the CIA triad.",blanks:[{id:"B1",opts:["confidentiality","profitability","popularity"],ans:"confidentiality"},{id:"B2",opts:["availability","flexibility","simplicity"],ans:"availability"}],fb:"IT audits are largely organized around testing controls that protect Confidentiality, Integrity, and Availability of systems and data."},{type:"select",id:"F10Q6",text:"IT GENERAL controls (e.g. access provisioning, change management) differ from IT APPLICATION controls in that IT general controls:",opts:["Only apply to a single specific application or transaction type","Support the reliable operation of the IT environment as a whole, providing the foundation that application controls depend on","Are irrelevant to financial statement audits","Are always more expensive than application controls"],ans:1,fb:"IT general controls (access, change management, operations) apply across the whole IT environment and support the effectiveness of application controls (like automated edit checks) built into specific systems \u2014 weak general controls undermine even well-designed application controls."}]}]};
